DROP TABLE IF EXISTS questions CASCADE;
DROP TABLE IF EXISTS exam_results CASCADE;

CREATE TABLE questions (
    id SERIAL PRIMARY KEY,
    qid VARCHAR(50) NOT NULL,
    version VARCHAR(20) NOT NULL DEFAULT '2026',
    part INT NOT NULL,
    topic VARCHAR(100),
    question_en TEXT NOT NULL,
    question_th TEXT NOT NULL,
    options_en JSONB NOT NULL,
    options_th JSONB NOT NULL,
    answer_index INT NOT NULL,
    explanation_en TEXT,
    explanation_th TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_questions_lookup ON questions (version, part);
CREATE INDEX idx_questions_qid ON questions (qid);

CREATE TABLE exam_results (
    id SERIAL PRIMARY KEY,
    user_id VARCHAR(100) DEFAULT 'anonymous',
    version VARCHAR(20) NOT NULL,
    part INT NOT NULL,
    score INT NOT NULL,
    total_questions INT NOT NULL,
    percentage INT NOT NULL,
    is_pass BOOLEAN NOT NULL,
    is_real_exam BOOLEAN NOT NULL,
    time_spent_seconds INT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_exam_results_user ON exam_results (user_id, created_at DESC);


-- Inserting 195 items for Version '2026', Part 1 from questions_part1_2026.json
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10275', '2026', 1, 'A.1.a', $q$What is the primary purpose of internal auditing?$q$, $q$วัตถุประสงค์หลักของการตรวจสอบภายในคืออะไร?$q$, $q$["It systematically coordinates with external stakeholders to address regulatory requirements and reporting guidelines.", "It actively monitors daily tasks to confirm adherence to established policies and operational procedures.", "It routinely evaluates employee objectives to ensure that management directives are followed consistently.", "It delivers independent assurance that strengthens risk management, internal controls, and overall governance practices."]$q$::jsonb, $q$["ประสานงานกับผู้มีส่วนได้ส่วนเสียภายนอกอย่างเป็นระบบเพื่อตอบสนองข้อกำหนดด้านกฎระเบียบและแนวทางการรายงาน", "ติดตามงานประจำวันอย่างแข็งขันเพื่อยืนยันการปฏิบัติตามนโยบายและขั้นตอนการปฏิบัติงานที่กำหนดไว้", "ประเมินวัตถุประสงค์ของพนักงานเป็นประจำเพื่อให้แน่ใจว่ามีการปฏิบัติตามคำสั่งการจัดการอย่างสม่ำเสมอ", "โดยให้การรับรองที่เป็นอิสระซึ่งเสริมสร้างความเข้มแข็งให้กับการบริหารความเสี่ยง การควบคุมภายใน และแนวปฏิบัติด้านการกำกับดูแลโดยรวม"]$q$::jsonb, 3, $q$Correct. Internal auditing is designed to provide independent assurance that improves  governance, risk management, and controls.$q$, $q$ถูกต้อง. การตรวจสอบภายในได้รับการออกแบบเพื่อให้การรับรองที่เป็นอิสระซึ่งจะช่วยปรับปรุงการกำกับดูแล การบริหารความเสี่ยง และการควบคุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10276', '2026', 1, 'A.1.a', $q$A company aiming to optimize its organizational procedures  requests an internal audit review. What is a primary benefit of the  internal audit function in this context?$q$, $q$บริษัทที่มีเป้าหมายที่จะเพิ่มประสิทธิภาพขั้นตอนขององค์กรจะต้องได้รับการตรวจสอบการตรวจสอบภายใน ประโยชน์หลักของหน่วยงานตรวจสอบภายในในบริบทนี้คืออะไร?$q$, $q$["It supplies independent insight to enhance operational efficiency.", "It evaluates daily operational tasks and verifies that established policies are enforced uniformly.", "It monitors routine employee activities to maintain consistent adherence to internal guidelines.", "It performs a self-assessment of the internal audit function's processes to evaluate adherence to the Global Internal Audit Standards."]$q$::jsonb, $q$["โดยให้ข้อมูลเชิงลึกที่เป็นอิสระเพื่อเพิ่มประสิทธิภาพการดำเนินงาน", "ประเมินงานการปฏิบัติงานประจำวันและตรวจสอบว่ามีการบังคับใช้นโยบายที่กำหนดไว้อย่างสม่ำเสมอ", "ติดตามกิจกรรมประจำวันของพนักงานเพื่อรักษาการปฏิบัติตามแนวทางภายในอย่างสม่ำเสมอ", "ดำเนินการประเมินตนเองของกระบวนการของหน่วยงานตรวจสอบภายในเพื่อประเมินการปฏิบัติตามมาตรฐานการตรวจสอบภายในระดับโลก"]$q$::jsonb, 0, $q$Correct. Internal auditing can independently provide insight into leading business  practices to enhance efficiency.$q$, $q$ถูกต้อง. การตรวจสอบภายในสามารถให้ข้อมูลเชิงลึกเกี่ยวกับการดำเนินธุรกิจชั้นนำเพื่อเพิ่มประสิทธิภาพได้อย่างอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10277', '2026', 1, 'A.1.a', $q$A manufacturing company is launching a new financial reporting  system and seeks independent evaluation of its control design.  Based on the overall objectives and benefits of the internal audit  function, how does internal auditing support organizational  improvement in this context?$q$, $q$บริษัทผู้ผลิตแห่งหนึ่งกำลังเปิดตัวระบบการรายงานทางการเงินใหม่และพยายามประเมินการออกแบบการควบคุมโดยอิสระ  จากวัตถุประสงค์โดยรวมและประโยชน์ของหน่วยงานตรวจสอบภายใน การตรวจสอบภายในสนับสนุนการปรับปรุงองค์กรในบริบทนี้อย่างไร$q$, $q$["It delivers independent assurance services that evaluate the system's design of financial reporting controls.", "It reviews individual transactions to ensure financial reporting accuracy.", "It evaluates management's selection of the new financial reporting system.", "It coordinates with the external auditors to obtain their concurrence with the new financial reporting system."]$q$::jsonb, $q$["ให้บริการประกันอิสระที่ประเมินการออกแบบระบบการควบคุมการรายงานทางการเงิน", "ตรวจสอบธุรกรรมแต่ละรายการเพื่อให้มั่นใจว่าการรายงานทางการเงินมีความถูกต้อง", "ประเมินการเลือกระบบการรายงานทางการเงินใหม่ของฝ่ายบริหาร", "ประสานงานกับผู้ตรวจสอบภายนอกเพื่อให้ได้รับความเห็นชอบกับระบบการรายงานทางการเงินใหม่"]$q$::jsonb, 0, $q$Correct. The internal audit function provides independent assurance that evaluates the  design of controls.$q$, $q$ถูกต้อง. หน่วยงานตรวจสอบภายในให้การรับรองที่เป็นอิสระเพื่อประเมินการออกแบบการควบคุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10278', '2026', 1, 'A.1.b', $q$A company is updating its internal audit procedure manual to  boost audit quality. Which condition is most critical in ensuring the  consistent quality of internal audit work?$q$, $q$บริษัทแห่งหนึ่งกำลังปรับปรุงคู่มือขั้นตอนการตรวจสอบภายในเพื่อเพิ่มคุณภาพการตรวจสอบ เงื่อนไขใดที่สำคัญที่สุดในการรับรองคุณภาพงานตรวจสอบภายในที่สม่ำเสมอ?$q$, $q$["Professional development initiatives that focus on established audit practices.", "Supervisor review of audit workpapers.", "Training programs that concentrate on standard procedures applied in previous audit engagements.", "Educational efforts that prioritize familiar techniques over emerging practices."]$q$::jsonb, $q$["โครงการริเริ่มด้านการพัฒนาวิชาชีพที่มุ่งเน้นแนวทางปฏิบัติด้านการตรวจสอบที่กำหนดไว้", "หัวหน้างานตรวจสอบเอกสารงานตรวจสอบ", "โปรแกรมการฝึกอบรมที่มุ่งเน้นขั้นตอนมาตรฐานที่ใช้ในการปฏิบัติงานการตรวจสอบครั้งก่อน", "ความพยายามด้านการศึกษาที่ให้ความสำคัญกับเทคนิคที่คุ้นเคยมากกว่าแนวทางปฏิบัติที่เกิดขึ้นใหม่"]$q$::jsonb, 1, $q$Correct. Supervisor review of audit workpapers is more critical to ensuring high audit  quality than training and education.$q$, $q$ถูกต้อง. การตรวจสอบเอกสารงานการตรวจสอบของหัวหน้างานมีความสำคัญอย่างยิ่งต่อการรับรองคุณภาพการตรวจสอบในระดับสูงมากกว่าการฝึกอบรมและการศึกษา$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10279', '2026', 1, 'A.2.a', $q$An organization is updating its internal audit charter. How does  the internal audit mandate typically delineate the responsibilities  of the board and the chief audit executive?$q$, $q$องค์กรกำลังปรับปรุงกฎบัตรการตรวจสอบภายใน โดยทั่วไปอำนาจการตรวจสอบภายในจะแบ่งแยกความรับผิดชอบของคณะกรรมการและหัวหน้าฝ่ายตรวจสอบภายในอย่างไร?$q$, $q$["It implies that management provides strategic oversight of the internal audit function and the board is well- informed of the internal audit results.", "Management provides strategic oversight while assigning the chief audit executive to manage operational details and execute the audit process.", "It suggests that the board establish audit policies and that the chief audit executive implement these policies across the organization consistently.", "It designates the board with overall governance and strategic oversight, while assigning operational management of the audit engagement to the chief audit executive."]$q$::jsonb, $q$["หมายความว่าฝ่ายบริหารจัดให้มีการกำกับดูแลเชิงกลยุทธ์ของหน่วยงานตรวจสอบภายใน และคณะกรรมการได้รับแจ้งผลการตรวจสอบภายในเป็นอย่างดี", "ฝ่ายบริหารให้การกำกับดูแลเชิงกลยุทธ์ในขณะที่มอบหมายให้หัวหน้าฝ่ายตรวจสอบบัญชีจัดการรายละเอียดการปฏิบัติงานและดำเนินการตามกระบวนการตรวจสอบ", "โดยเสนอแนะให้คณะกรรมการกำหนดนโยบายการตรวจสอบและหัวหน้าฝ่ายตรวจสอบบัญชีนำนโยบายเหล่านี้ไปปฏิบัติทั่วทั้งองค์กรอย่างสม่ำเสมอ", "โดยจะมอบหมายให้คณะกรรมการมีการกำกับดูแลโดยรวมและการกำกับดูแลเชิงกลยุทธ์ ขณะเดียวกันก็มอบหมายการจัดการการปฏิบัติงานของงานตรวจสอบให้กับหัวหน้าฝ่ายตรวจสอบบัญชี"]$q$::jsonb, 3, $q$Correct. The audit mandate assigns overall governance and strategic oversight to the  board, with operational management and execution of audit engagements handled by  the chief audit executive.$q$, $q$ถูกต้อง. อำนาจการตรวจสอบจะมอบหมายการกำกับดูแลโดยรวมและการกำกับดูแลเชิงกลยุทธ์ให้กับคณะกรรมการ โดยมีการจัดการการปฏิบัติงานและการดำเนินการตรวจสอบที่จัดการโดยหัวหน้าฝ่ายตรวจสอบบัญชี$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10280', '2026', 1, 'A.2.a', $q$A financial services company is clarifying the role of its chief audit  executive. Based on the internal audit mandate, what is a primary  responsibility of the chief audit executive?$q$, $q$บริษัทผู้ให้บริการทางการเงินแห่งหนึ่งกำลังชี้แจงบทบาทของหัวหน้าฝ่ายตรวจสอบบัญชีของตน ตามอำนาจการตรวจสอบภายใน ความรับผิดชอบหลักของหัวหน้าฝ่ายตรวจสอบภายในคืออะไร?$q$, $q$["To oversee operational activities, integrate comprehensive risk management strategies, and contribute to enhancing internal control processes across the organization.", "To determine the internal audit function's strategic priorities, set audit policies, and guide the overall approach to internal auditing in support of governance.", "To help the board and management determine the scope and types of internal audit services.", "To coordinate with external auditors, ensure compliance with regulatory requirements, and support the overall governance framework through systematic audit planning."]$q$::jsonb, $q$["กำกับดูแลกิจกรรมการดำเนินงาน บูรณาการกลยุทธ์การบริหารความเสี่ยงที่ครอบคลุม และมีส่วนร่วมในการปรับปรุงกระบวนการควบคุมภายในทั่วทั้งองค์กร", "เพื่อกำหนดลำดับความสำคัญเชิงกลยุทธ์ของหน่วยงานตรวจสอบภายใน กำหนดนโยบายการตรวจสอบ และชี้แนะแนวทางโดยรวมในการตรวจสอบภายในเพื่อสนับสนุนการกำกับดูแล", "เพื่อช่วยคณะกรรมการและฝ่ายจัดการกำหนดขอบเขตและประเภทของบริการตรวจสอบภายใน", "เพื่อประสานงานกับผู้ตรวจสอบภายนอก ตรวจสอบการปฏิบัติตามข้อกำหนดด้านกฎระเบียบ และสนับสนุนกรอบการกำกับดูแลโดยรวมผ่านการวางแผนการตรวจสอบอย่างเป็นระบบ"]$q$::jsonb, 2, $q$Correct. Based on the internal audit mandate, the chief audit executive is responsible for  helping the board and management determine the scope and types of internal audit  services.$q$, $q$ถูกต้อง. ตามอำนาจการตรวจสอบภายใน หัวหน้าฝ่ายตรวจสอบภายในมีหน้าที่ช่วยคณะกรรมการและฝ่ายบริหารในการกำหนดขอบเขตและประเภทของบริการตรวจสอบภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10281', '2026', 1, 'A.2.a', $q$An organization is evaluating its internal audit function to ensure it  meets defined standards. How does the internal audit function's  authority support its role and responsibilities?$q$, $q$องค์กรกำลังประเมินหน่วยงานตรวจสอบภายในเพื่อให้แน่ใจว่าเป็นไปตามมาตรฐานที่กำหนด อำนาจหน้าที่ของหน่วยงานตรวจสอบภายในสนับสนุนบทบาทและความรับผิดชอบอย่างไร?$q$, $q$["It is permitted to review select areas identified by management for targeted improvements.", "It has authority to access all relevant records for independent evaluations.", "It is allowed to consult with external auditors for specialized assessments.", "It is authorized to monitor routine compliance during scheduled reviews."]$q$::jsonb, $q$["ได้รับอนุญาตให้ตรวจสอบพื้นที่ที่เลือกซึ่งระบุโดยฝ่ายบริหารเพื่อการปรับปรุงตามเป้าหมาย", "มีอำนาจในการเข้าถึงบันทึกที่เกี่ยวข้องทั้งหมดสำหรับการประเมินโดยอิสระ", "อนุญาตให้ปรึกษากับผู้ตรวจสอบภายนอกเพื่อการประเมินเฉพาะทางได้", "ได้รับอนุญาตให้ตรวจสอบการปฏิบัติตามปกติในระหว่างการตรวจสอบตามกำหนดเวลา"]$q$::jsonb, 1, $q$Correct. The internal audit function’s broad access supports unbiased evaluations and  ensures comprehensive oversight.$q$, $q$ถูกต้อง. การเข้าถึงอย่างกว้างๆ ของหน่วยงานตรวจสอบภายในสนับสนุนการประเมินที่เป็นกลางและรับประกันการกำกับดูแลที่ครอบคลุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10282', '2026', 1, 'A.2.a', $q$In reviewing internal audit responsibilities, which of the following  best reflects the internal audit function’s authority and role within  an organization?$q$, $q$In reviewing internal audit responsibilities, which of the following  best reflects the internal audit function’s authority and role within  an organization?$q$, $q$["It collaborates with departments mainly to provide advice on administrative tasks.", "It functions under management oversight and focuses on routine monitoring of processes.", "It operates independently to evaluate risk management and controls while reporting to the board.", "It conducts reviews limited to areas specified by management."]$q$::jsonb, $q$["ทำงานร่วมกับหน่วยงานต่างๆ เป็นหลักในการให้คำแนะนำงานธุรการ", "ทำหน้าที่ภายใต้การกำกับดูแลของฝ่ายบริหารและมุ่งเน้นไปที่การตรวจสอบกระบวนการตามปกติ", "ดำเนินการอย่างอิสระเพื่อประเมินการจัดการความเสี่ยงและการควบคุมในขณะที่รายงานต่อคณะกรรมการ", "ดำเนินการตรวจสอบโดยจำกัดเฉพาะพื้นที่ที่ฝ่ายบริหารกำหนด"]$q$::jsonb, 2, $q$Correct. Operating independently and reporting to the board is key to effective  evaluations of risk management and controls.$q$, $q$ถูกต้อง. Operating independently and reporting to the board is key to effective  evaluations of risk management and controls.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10283', '2026', 1, 'A.2.a', $q$When considering the authority of the internal audit function,  which aspect is most important in supporting its responsibilities?$q$, $q$ในการพิจารณาอำนาจหน้าที่ของหน่วยงานตรวจสอบภายใน ประเด็นใดที่สำคัญที่สุดในการสนับสนุนความรับผิดชอบของหน่วยงานตรวจสอบภายใน?$q$, $q$["Access centered on monitoring communication channels for timely reporting.", "Access limited to select operational areas identified in management reports.", "Access focused on regulatory compliance checks during routine inspections.", "Unrestricted access to all records and systems, enabling comprehensive evaluations."]$q$::jsonb, $q$["การเข้าถึงที่เน้นการติดตามช่องทางการสื่อสารเพื่อการรายงานที่ทันท่วงที", "การเข้าถึงถูกจำกัดไว้สำหรับพื้นที่ปฏิบัติงานที่เลือกซึ่งระบุไว้ในรายงานการจัดการ", "การเข้าถึงมุ่งเน้นไปที่การตรวจสอบการปฏิบัติตามกฎระเบียบในระหว่างการตรวจสอบตามปกติ", "การเข้าถึงบันทึกและระบบทั้งหมดได้อย่างไม่จำกัด ทำให้สามารถประเมินผลได้อย่างครอบคลุม"]$q$::jsonb, 3, $q$Correct. Unrestricted access is fundamental for conducting comprehensive and  unbiased evaluations within the organization.$q$, $q$ถูกต้อง. การเข้าถึงที่ไม่จำกัดเป็นพื้นฐานสำหรับการดำเนินการประเมินที่ครอบคลุมและเป็นกลางภายในองค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10284', '2026', 1, 'A.2.b', $q$In what way does the chief audit executive (CAE) help the board  validate the effectiveness of an updated internal audit mandate?$q$, $q$หัวหน้าฝ่ายตรวจสอบภายใน (CAE) ช่วยให้คณะกรรมการตรวจสอบประสิทธิผลของคำสั่งตรวจสอบภายในที่ได้รับการปรับปรุงได้อย่างไร?$q$, $q$["The CAE communicates how the internal audit function performs the responsibilities described in the updated mandate.", "The CAE collects feedback from management about an appropriate mandate.", "The CAE communicates audit results to the board.", "The CAE compares the internal audit mandate to external examples without updating."]$q$::jsonb, $q$["CAE สื่อสารว่าหน่วยงานตรวจสอบภายในปฏิบัติหน้าที่ตามความรับผิดชอบที่อธิบายไว้ในอาณัติฉบับปรับปรุงอย่างไร", "CAE รวบรวมข้อเสนอแนะจากฝ่ายบริหารเกี่ยวกับอาณัติที่เหมาะสม", "CAE สื่อสารผลการตรวจสอบไปยังคณะกรรมการ", "CAE เปรียบเทียบคำสั่งการตรวจสอบภายในกับตัวอย่างภายนอกโดยไม่ต้องอัปเดต"]$q$::jsonb, 0, $q$Correct. The CAE communicates how internal auditing performs the responsibilities  described in the mandate, which helps the board to validate and update the mandate.$q$, $q$ถูกต้อง. CAE สื่อสารถึงวิธีที่การตรวจสอบภายในปฏิบัติหน้าที่ตามที่อธิบายไว้ในอาณัติ ซึ่งจะช่วยให้คณะกรรมการสามารถตรวจสอบและปรับปรุงอาณัติได้$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10285', '2026', 1, 'A.2.b', $q$What role does the chief audit executive (CAE) play in updating  the internal audit mandate to address changes in the business  environment?$q$, $q$หัวหน้าฝ่ายตรวจสอบภายใน (CAE) มีบทบาทอย่างไรในการปรับปรุงอำนาจการตรวจสอบภายในเพื่อแก้ไขการเปลี่ยนแปลงในสภาพแวดล้อมทางธุรกิจ$q$, $q$["The CAE limits updates to changes in financial reporting standards and external auditor requirements.", "The CAE preserves traditional audit practices to maintain consistency with prior mandates.", "The CAE evaluates changes in the business environment and recommends mandate updates to address new risks.", "The CAE oversees revisions without assessing the impact of environmental changes."]$q$::jsonb, $q$["CAE จำกัดการอัปเดตการเปลี่ยนแปลงในมาตรฐานการรายงานทางการเงินและข้อกำหนดของผู้ตรวจสอบภายนอก", "CAE รักษาแนวปฏิบัติการตรวจสอบแบบดั้งเดิมเพื่อรักษาความสอดคล้องกับข้อบังคับก่อนหน้านี้", "CAE ประเมินการเปลี่ยนแปลงในสภาพแวดล้อมทางธุรกิจและแนะนำการปรับปรุงข้อบังคับเพื่อจัดการกับความเสี่ยงใหม่", "CAE กำกับดูแลการแก้ไขโดยไม่ต้องประเมินผลกระทบของการเปลี่ยนแปลงสิ่งแวดล้อม"]$q$::jsonb, 2, $q$Correct. Evaluating changes in the business environment and recommending updates  ensures the internal audit mandate remains responsive to new risks.$q$, $q$ถูกต้อง. การประเมินการเปลี่ยนแปลงในสภาพแวดล้อมทางธุรกิจและการแนะนำการอัปเดตทำให้มั่นใจได้ว่าคำสั่งการตรวจสอบภายในยังคงตอบสนองต่อความเสี่ยงใหม่ ๆ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10286', '2026', 1, 'A.2.c', $q$How do the board and senior management determine the internal  audit function’s responsibilities?$q$, $q$คณะกรรมการและผู้บริหารระดับสูงกำหนดความรับผิดชอบของหน่วยงานตรวจสอบภายในอย่างไร?$q$, $q$["The board and senior management concentrate on financial performance, and the chief audit executive determines internal audit responsibilities.", "The board provides oversight of the internal audit function, and senior management sets the responsibilities.", "The board and senior management delegate most responsibilities to the chief audit executive, with only limited board oversight.", "The board, with input from the chief audit executive and senior management, sets the responsibilities of internal auditing."]$q$::jsonb, $q$["คณะกรรมการและผู้บริหารระดับสูงให้ความสำคัญกับผลการดำเนินงานทางการเงิน และหัวหน้าฝ่ายตรวจสอบภายในจะกำหนดความรับผิดชอบด้านการตรวจสอบภายใน", "คณะกรรมการมีหน้าที่กำกับดูแลหน่วยงานตรวจสอบภายใน และผู้บริหารระดับสูงเป็นผู้กำหนดความรับผิดชอบ", "คณะกรรมการและผู้บริหารระดับสูงมอบหมายความรับผิดชอบส่วนใหญ่ให้กับหัวหน้าฝ่ายตรวจสอบบัญชี โดยมีเพียงคณะกรรมการกำกับดูแลที่จำกัดเท่านั้น", "คณะกรรมการจะใช้ข้อมูลจากหัวหน้าฝ่ายตรวจสอบภายในและผู้บริหารระดับสูงในการกำหนดความรับผิดชอบของการตรวจสอบภายใน"]$q$::jsonb, 3, $q$Correct. The board effectively defines the internal audit function’s responsibilities, role,  and authority, with input from the chief audit executive and management.$q$, $q$ถูกต้อง. คณะกรรมการกำหนดความรับผิดชอบ บทบาท และอำนาจของหน่วยงานตรวจสอบภายในอย่างมีประสิทธิผล โดยได้รับข้อมูลจากหัวหน้าฝ่ายตรวจสอบภายในและฝ่ายบริหาร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10287', '2026', 1, 'A.2.c', $q$How do the board and senior management balance strategic  oversight with operational support for the internal audit function?$q$, $q$คณะกรรมการและผู้บริหารระดับสูงมีความสมดุลระหว่างการกำกับดูแลเชิงกลยุทธ์กับการสนับสนุนการปฏิบัติงานสำหรับหน่วยงานตรวจสอบภายในอย่างไร$q$, $q$["They alternate between strategic oversight and operational roles as necessary.", "The board focuses on developing high-level policies, while senior management handles routine operational tasks consistently.", "They jointly support the recognition of the internal audit function across the organization.", "The board handles oversight exclusively, and senior management executes the strategy."]$q$::jsonb, $q$["สลับกันระหว่างการกำกับดูแลเชิงกลยุทธ์และบทบาทการปฏิบัติงานตามความจำเป็น", "คณะกรรมการมุ่งเน้นไปที่การพัฒนานโยบายระดับสูง ในขณะที่ผู้บริหารระดับสูงจะจัดการงานการปฏิบัติงานตามปกติอย่างสม่ำเสมอ", "พวกเขาร่วมกันสนับสนุนการรับรู้ของหน่วยงานตรวจสอบภายในทั่วทั้งองค์กร", "คณะกรรมการจะดูแลการกำกับดูแลโดยเฉพาะ และผู้บริหารระดับสูงจะดำเนินกลยุทธ์ดังกล่าว"]$q$::jsonb, 2, $q$Correct. A joint approach with the board and management provides recognition for the  internal audit function that helps support the authority and role of internal auditing.$q$, $q$ถูกต้อง. แนวทางร่วมกับคณะกรรมการและฝ่ายบริหารทำให้มีการยกย่องหน่วยงานตรวจสอบภายในที่ช่วยสนับสนุนอำนาจและบทบาทของการตรวจสอบภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10288', '2026', 1, 'A.2.c', $q$In establishing the internal audit function's responsibilities, how do  the board and senior management contribute to its overall  effectiveness?$q$, $q$ในการกำหนดความรับผิดชอบของหน่วยงานตรวจสอบภายใน คณะกรรมการและผู้บริหารระดับสูงมีส่วนทำให้มีประสิทธิผลโดยรวมอย่างไร?$q$, $q$["They have completely separate roles, with the board handling strategy and senior management managing day- to-day operations in isolation.", "The board determines overall policy, and senior management executes daily tasks without further strategic input.", "Senior management and the chief audit executive communicate to the board expectations for responsibilities to be included in the internal audit charter.", "The board reviews the charter, considers any needed changes, and approves the charter. They maintain a traditional status quo by relying on historical practices rather than aligning with current strategic needs."]$q$::jsonb, $q$["พวกเขามีบทบาทที่แยกจากกันโดยสิ้นเชิง โดยมีกลยุทธ์การจัดการของคณะกรรมการและผู้บริหารระดับสูงที่จัดการการปฏิบัติงานในแต่ละวันแยกจากกัน", "คณะกรรมการจะเป็นผู้กำหนดนโยบายโดยรวม และผู้บริหารระดับสูงจะดำเนินงานประจำวันโดยไม่มีการป้อนข้อมูลเชิงกลยุทธ์เพิ่มเติม", "ผู้บริหารระดับสูงและหัวหน้าฝ่ายตรวจสอบภายในสื่อสารกับคณะกรรมการเกี่ยวกับความคาดหวังเกี่ยวกับความรับผิดชอบที่จะรวมอยู่ในกฎบัตรการตรวจสอบภายใน", "คณะกรรมการจะทบทวนกฎบัตร พิจารณาการเปลี่ยนแปลงที่จำเป็น และอนุมัติกฎบัตร พวกเขารักษาสภาพที่เป็นอยู่แบบดั้งเดิมโดยอาศัยแนวทางปฏิบัติทางประวัติศาสตร์มากกว่าการปรับให้สอดคล้องกับความต้องการเชิงกลยุทธ์ในปัจจุบัน"]$q$::jsonb, 2, $q$Correct. Senior management and the chief audit executive work together to communicate  to the board their expectations for responsibilities to be included in the internal audit  charter. The board reviews the charter, considers any needed changes, and approves  the charter.$q$, $q$ถูกต้อง. ผู้บริหารระดับสูงและหัวหน้าฝ่ายตรวจสอบภายในทำงานร่วมกันเพื่อสื่อสารความคาดหวังต่อคณะกรรมการเกี่ยวกับความรับผิดชอบที่จะรวมอยู่ในกฎบัตรการตรวจสอบภายใน คณะกรรมการจะทบทวนกฎบัตร พิจารณาการเปลี่ยนแปลงที่จำเป็น และอนุมัติกฎบัตร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10289', '2026', 1, 'A.3.a', $q$A public company is preparing for a regulatory inspection by  reviewing its internal audit charter. Which requirement is  fundamental for an effective charter?$q$, $q$บริษัทมหาชนแห่งหนึ่งกำลังเตรียมการตรวจสอบตามกฎระเบียบโดยทบทวนกฎบัตรการตรวจสอบภายใน ข้อกำหนดใดที่เป็นพื้นฐานสำหรับกฎบัตรที่มีประสิทธิภาพ$q$, $q$["It must include detailed operational performance metrics for each audited unit.", "It should list the audit procedures and technical methodologies to be followed.", "It is expected to include interaction with the external auditors.", "It must clearly define the internal audit function’s authority, responsibilities, and independence from management."]$q$::jsonb, $q$["จะต้องมีตัวชี้วัดประสิทธิภาพการปฏิบัติงานโดยละเอียดสำหรับหน่วยงานที่ได้รับการตรวจสอบแต่ละหน่วย", "ควรระบุขั้นตอนการตรวจสอบและวิธีการทางเทคนิคที่ต้องปฏิบัติตาม", "คาดว่าจะรวมถึงการมีปฏิสัมพันธ์กับผู้ตรวจสอบภายนอกด้วย", "โดยต้องกำหนดอำนาจ ความรับผิดชอบ และความเป็นอิสระของฝ่ายตรวจสอบภายในให้ชัดเจน"]$q$::jsonb, 3, $q$Correct. A fundamental requirement of the internal audit charter is to define the internal  audit function’s authority, responsibilities, and its independence, ensuring effective  governance.$q$, $q$ถูกต้อง. ข้อกำหนดพื้นฐานของกฎบัตรการตรวจสอบภายในคือการกำหนดอำนาจ ความรับผิดชอบ และความเป็นอิสระของหน่วยงานตรวจสอบภายใน เพื่อให้มั่นใจว่ามีการกำกับดูแลที่มีประสิทธิผล$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10290', '2026', 1, 'B.1.b', $q$In accordance with the Global Internal Audit Standards, which  ethical component must internal audit professionals adhere to?$q$, $q$ตามมาตรฐานการตรวจสอบภายในสากล องค์ประกอบทางจริยธรรมใดที่ผู้เชี่ยวชาญด้านการตรวจสอบภายในต้องปฏิบัติตาม?$q$, $q$["General business ethics, without a structured ethical framework.", "Informal ethical guidelines suggested by industry peers and management.", "Personal judgment in ethical matters based on past experiences.", "The organization's code of ethical conduct that guides staff's professional conduct and ethical behavior."]$q$::jsonb, $q$["จริยธรรมทางธุรกิจโดยทั่วไปโดยไม่มีกรอบจริยธรรมที่มีโครงสร้าง", "แนวปฏิบัติทางจริยธรรมที่ไม่เป็นทางการแนะนำโดยเพื่อนร่วมงานในอุตสาหกรรมและผู้บริหาร", "การตัดสินส่วนบุคคลในเรื่องจริยธรรมจากประสบการณ์ในอดีต", "จรรยาบรรณขององค์กรที่กำหนดแนวทางปฏิบัติทางวิชาชีพและพฤติกรรมทางจริยธรรมของพนักงาน"]$q$::jsonb, 3, $q$Correct. Adherence to the organization's code of conduct is a required component to  ensure that internal audit professionals maintain ethical conduct.$q$, $q$ถูกต้อง. การปฏิบัติตามหลักจรรยาบรรณขององค์กรเป็นองค์ประกอบที่จำเป็นเพื่อให้แน่ใจว่าผู้ประกอบวิชาชีพตรวจสอบภายในรักษาหลักจริยธรรม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10291', '2026', 1, 'A.3.a', $q$Which component required by the Global Internal Audit Standards  is key to defining the scope and boundaries of the internal audit  function?$q$, $q$องค์ประกอบใดที่กำหนดโดยมาตรฐานการตรวจสอบภายในสากลซึ่งเป็นกุญแจสำคัญในการกำหนดขอบเขตและขอบเขตของหน่วยงานตรวจสอบภายใน$q$, $q$["An informal statement listing activities for review without precise scope definitions.", "A general guideline that offers broad directions without specifying the types of audit services.", "A defined internal audit charter that clearly outlines the scope, types of audit services, and responsibilities of the function.", "A brief outline that mentions audit tasks but does not specify responsibilities."]$q$::jsonb, $q$["ข้อความที่ไม่เป็นทางการซึ่งแสดงรายการกิจกรรมเพื่อการตรวจสอบโดยไม่มีคำจำกัดความขอบเขตที่ชัดเจน", "แนวปฏิบัติทั่วไปที่ให้แนวทางกว้างๆ โดยไม่ระบุประเภทของบริการตรวจสอบ", "กฎบัตรการตรวจสอบภายในที่กำหนดขอบเขต ประเภทของบริการตรวจสอบ และความรับผิดชอบของหน่วยงานอย่างชัดเจน", "โครงร่างโดยย่อที่กล่าวถึงงานตรวจสอบแต่ไม่ได้ระบุความรับผิดชอบ"]$q$::jsonb, 2, $q$Correct. A defined internal audit charter is necessary to clearly establish the scope,  types of audit services, and responsibilities of the internal audit function, as required by  the Standards.$q$, $q$ถูกต้อง. กฎบัตรการตรวจสอบภายในที่กำหนดไว้มีความจำเป็นเพื่อกำหนดขอบเขต ประเภทของบริการตรวจสอบ และความรับผิดชอบของหน่วยงานตรวจสอบภายในอย่างชัดเจน ตามที่มาตรฐานกำหนด$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10292', '2026', 1, 'A.3.b', $q$An organization plans to update its internal audit charter. How  does engaging the board and senior management in this process  contribute to the charter's effectiveness?$q$, $q$องค์กรวางแผนที่จะปรับปรุงกฎบัตรการตรวจสอบภายใน การมีส่วนร่วมของคณะกรรมการและผู้บริหารระดับสูงในกระบวนการนี้มีส่วนช่วยให้กฎบัตรมีประสิทธิผลอย่างไร$q$, $q$["It emphasizes audit plan coverage over strategic objectives.", "It limits the charter’s scope to primarily satisfy regulatory requirements.", "It incorporates diverse perspectives, ensuring the charter reflects both strategic oversight and organizational needs.", "It directs attention solely to internal control effectiveness rather than overall audit objectives."]$q$::jsonb, $q$["โดยเน้นความครอบคลุมแผนการตรวจสอบมากกว่าวัตถุประสงค์เชิงกลยุทธ์", "โดยจำกัดขอบเขตของกฎบัตรเพื่อให้เป็นไปตามข้อกำหนดด้านกฎระเบียบเป็นหลัก", "ประกอบด้วยมุมมองที่หลากหลาย เพื่อให้มั่นใจว่ากฎบัตรสะท้อนทั้งการกำกับดูแลเชิงกลยุทธ์และความต้องการขององค์กร", "โดยให้ความสำคัญกับประสิทธิผลของการควบคุมภายในเพียงอย่างเดียวมากกว่าวัตถุประสงค์การตรวจสอบโดยรวม"]$q$::jsonb, 2, $q$Correct. Engaging both groups brings varied insights that help create a balanced  internal audit charter addressing strategic and organizational considerations.$q$, $q$ถูกต้อง. การมีส่วนร่วมของทั้งสองกลุ่มนำมาซึ่งข้อมูลเชิงลึกที่หลากหลายซึ่งช่วยสร้างกฎบัตรการตรวจสอบภายในที่สมดุลโดยคำนึงถึงข้อพิจารณาเชิงกลยุทธ์และองค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10293', '2026', 1, 'A.4', $q$A board member is comparing internal audit offerings. How  should the differences between assurance and advisory services  be evaluated?$q$, $q$สมาชิกคณะกรรมการกำลังเปรียบเทียบข้อเสนอการตรวจสอบภายใน ควรประเมินความแตกต่างระหว่างบริการให้ความเชื่อมั่นและบริการให้คำปรึกษาอย่างไร$q$, $q$["Assurance services provide independent reviews without formal conclusions, whereas advisory services focus on consultative recommendations for performance enhancement.", "Assurance services result in formal opinions based on independent assessments, while advisory services offer flexible, nonbinding advice on improvements.", "Assurance services offer formal evaluations of risk and controls, while advisory services deliver formal recommendations to improve processes.", "Assurance services provide consultative insights without formal opinions, while advisory services provide independent evaluations and opinions."]$q$::jsonb, $q$["งานบริการให้ความเชื่อมั่นให้การตรวจสอบอย่างเป็นอิสระโดยไม่มีข้อสรุปอย่างเป็นทางการ ในขณะที่บริการให้คำปรึกษามุ่งเน้นไปที่คำแนะนำเชิงปรึกษาเพื่อการปรับปรุงประสิทธิภาพ", "งานบริการให้ความเชื่อมั่นส่งผลให้เกิดความคิดเห็นอย่างเป็นทางการตามการประเมินที่เป็นอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำที่ยืดหยุ่นและไม่มีข้อผูกมัดในการปรับปรุง", "งานบริการให้ความเชื่อมั่นนำเสนอการประเมินความเสี่ยงและการควบคุมอย่างเป็นทางการ ในขณะที่บริการให้คำปรึกษาให้คำแนะนำอย่างเป็นทางการเพื่อปรับปรุงกระบวนการ", "บริการด้านการรับประกันให้ข้อมูลเชิงลึกเชิงปรึกษาโดยไม่ต้องแสดงความคิดเห็นอย่างเป็นทางการ ในขณะที่บริการให้คำปรึกษาให้การประเมินและความคิดเห็นที่เป็นอิสระ"]$q$::jsonb, 1, $q$Correct. The key difference is that assurance services yield formal opinions through  independent reviews, while advisory services offer nonbinding, consultative advice.$q$, $q$ถูกต้อง. ข้อแตกต่างที่สำคัญคือบริการให้ความเชื่อมั่นจะให้ความคิดเห็นอย่างเป็นทางการผ่านการทบทวนโดยอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำที่ไม่ผูกมัดและเป็นที่ปรึกษา$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10294', '2026', 1, 'A.4', $q$A corporate audit committee is assessing internal audit offerings.  How should it analyze the differences between assurance and  advisory services?$q$, $q$คณะกรรมการตรวจสอบองค์กรกำลังประเมินข้อเสนอการตรวจสอบภายใน  ควรวิเคราะห์ความแตกต่างระหว่างงานบริการให้ความเชื่อมั่นและบริการให้คำปรึกษาอย่างไร$q$, $q$["Assurance services yield independent, formal assessments of processes while advisory services serve as consultative partners for internal control design.", "Assurance services provide structured evaluations with formal outcomes, whereas advisory services focus on offering suggestions for improvements along with opinions.", "Assurance services deliver formal opinions based on independent reviews, while advisory services offer consultative advice without formal conclusions.", "Assurance services result in formal, independent evaluations of risks, and advisory services supply nonbinding recommendations for control improvements."]$q$::jsonb, $q$["งานบริการให้ความเชื่อมั่นให้การประเมินกระบวนการอย่างเป็นทางการและเป็นอิสระ ในขณะที่บริการให้คำปรึกษาทำหน้าที่เป็นพันธมิตรที่ปรึกษาสำหรับการออกแบบการควบคุมภายใน", "งานบริการให้ความเชื่อมั่นจะให้การประเมินที่มีโครงสร้างพร้อมผลลัพธ์ที่เป็นทางการ ในขณะที่บริการให้คำปรึกษามุ่งเน้นไปที่การเสนอข้อเสนอแนะเพื่อการปรับปรุงพร้อมกับความคิดเห็น", "บริการด้านการรับประกันจะให้ความคิดเห็นอย่างเป็นทางการโดยอิงจากการตรวจสอบโดยอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำปรึกษาโดยไม่มีข้อสรุปอย่างเป็นทางการ", "งานบริการให้ความเชื่อมั่นส่งผลให้เกิดการประเมินความเสี่ยงอย่างเป็นทางการและเป็นอิสระ และบริการให้คำปรึกษาจะให้คำแนะนำที่ไม่มีข้อผูกมัดสำหรับการปรับปรุงการควบคุม"]$q$::jsonb, 2, $q$Correct. The distinction is that assurance services culminate in formal opinions from  independent reviews, whereas advisory services offer nonbinding consultative advice.$q$, $q$ถูกต้อง. ความแตกต่างก็คือ บริการให้ความเชื่อมั่นจะมีผลสูงสุดในความคิดเห็นอย่างเป็นทางการจากการทบทวนโดยอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำปรึกษาที่ไม่มีข้อผูกมัด$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10295', '2026', 1, 'A.4.a', $q$In an internal audit review, how can differences between  assurance and advisory services be analyzed for their impact on  decision-making?$q$, $q$ในการทบทวนการตรวจสอบภายใน จะวิเคราะห์ความแตกต่างระหว่างบริการให้ความเชื่อมั่นและบริการให้คำปรึกษาเกี่ยวกับผลกระทบต่อการตัดสินใจได้อย่างไร$q$, $q$["Assurance services result in formal opinions, but may lack independence, while advisory services serve as consultative, objective advice to aid process improvements.", "Assurance services provide independent assessments with formal conclusions. whereas advisory services direct management to make required process changes.", "Assurance services offer formal, independent evaluations that lead to opinions, while advisory services provide consultative advice without formal conclusions.", "Assurance services direct management to make required changes, and advisory services offer nonbinding advice to facilitate decision- making."]$q$::jsonb, $q$["งานบริการให้ความเชื่อมั่นส่งผลให้เกิดความคิดเห็นอย่างเป็นทางการ แต่อาจขาดความเป็นอิสระ ในขณะที่บริการให้คำปรึกษาทำหน้าที่เป็นคำแนะนำที่เป็นกลางเพื่อช่วยปรับปรุงกระบวนการ", "งานบริการให้ความเชื่อมั่นให้การประเมินที่เป็นอิสระพร้อมข้อสรุปที่เป็นทางการ ในขณะที่บริการให้คำปรึกษาจัดการโดยตรงเพื่อทำการเปลี่ยนแปลงกระบวนการที่จำเป็น", "งานบริการให้ความเชื่อมั่นนำเสนอการประเมินที่เป็นทางการและเป็นอิสระซึ่งนำไปสู่ความคิดเห็น ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำปรึกษาโดยไม่มีข้อสรุปที่เป็นทางการ", "งานบริการให้ความเชื่อมั่นบริหารจัดการโดยตรงเพื่อทำการเปลี่ยนแปลงที่จำเป็น และบริการให้คำปรึกษาให้คำแนะนำที่ไม่มีข้อผูกมัดเพื่ออำนวยความสะดวกในการตัดสินใจ"]$q$::jsonb, 2, $q$Correct. The key distinction is that assurance services result in formal, independent  opinions, while advisory services offer consultative guidance that supports decision- making without issuing formal opinions.$q$, $q$ถูกต้อง. ความแตกต่างที่สำคัญคือบริการให้ความเชื่อมั่นส่งผลให้เกิดความคิดเห็นที่เป็นทางการและเป็นอิสระ ในขณะที่บริการให้คำปรึกษาเสนอแนวทางให้คำปรึกษาที่สนับสนุนการตัดสินใจโดยไม่ต้องออกความคิดเห็นที่เป็นทางการ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10296', '2026', 1, 'A.4.a', $q$In internal auditing, what best defines assurance services?$q$, $q$ในการตรวจสอบภายใน อะไรเป็นตัวกำหนดบริการด้านความเชื่อมั่นได้ดีที่สุด?$q$, $q$["They are objective assessments that result in formal opinions on the effectiveness of risk controls.", "They are advisory sessions that provide management with improvement suggestions informally.", "They are internal reviews performed to ensure routine adherence to established guidelines.", "They are external audit engagements carried out to verify compliance with statutory requirements."]$q$::jsonb, $q$["เป็นการประเมินตามวัตถุประสงค์ซึ่งส่งผลให้เกิดความคิดเห็นอย่างเป็นทางการเกี่ยวกับประสิทธิผลของการควบคุมความเสี่ยง", "เป็นช่วงให้คำปรึกษาที่ให้คำแนะนำในการปรับปรุงแก่ฝ่ายบริหารอย่างไม่เป็นทางการ", "เป็นการทบทวนภายในที่ดำเนินการเพื่อให้แน่ใจว่ามีการปฏิบัติตามหลักเกณฑ์ที่กำหนดเป็นประจำ", "เป็นงานตรวจสอบภายนอกที่ดำเนินการเพื่อตรวจสอบการปฏิบัติตามข้อกำหนดทางกฎหมาย"]$q$::jsonb, 0, $q$Correct. Assurance services are objective, independent assessments that produce  formal opinions on risk control effectiveness.$q$, $q$ถูกต้อง. บริการให้ความเชื่อมั่นเป็นการประเมินที่เป็นกลางและเป็นอิสระซึ่งให้ความเห็นอย่างเป็นทางการเกี่ยวกับประสิทธิผลในการควบคุมความเสี่ยง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10297', '2026', 1, 'A.4.a', $q$In a training workshop, how are assurance services defined within  internal auditing?$q$, $q$ในการประชุมเชิงปฏิบัติการการฝึกอบรม มีการกำหนดบริการด้านการรับประกันภายในการตรวจสอบภายในอย่างไร$q$, $q$["They are internal assessments conducted to check routine compliance with policies.", "They are independent evaluations that yield formal opinions on controls and risks.", "They are advisory reviews that provide guidance on enhancing operational performance.", "They are external audit engagements used primarily for verifying financial reporting accuracy."]$q$::jsonb, $q$["เป็นการประเมินภายในที่ดำเนินการเพื่อตรวจสอบการปฏิบัติตามนโยบายเป็นประจำ", "เป็นการประเมินที่เป็นอิสระซึ่งให้ความเห็นอย่างเป็นทางการเกี่ยวกับการควบคุมและความเสี่ยง", "เป็นการทบทวนที่ปรึกษาที่ให้คำแนะนำในการเพิ่มประสิทธิภาพการดำเนินงาน", "เป็นงานตรวจสอบภายนอกที่ใช้เพื่อตรวจสอบความถูกต้องของการรายงานทางการเงินเป็นหลัก"]$q$::jsonb, 1, $q$Correct. Assurance services are defined as independent evaluations that yield formal  opinions on controls and risks.$q$, $q$ถูกต้อง. งานบริการให้ความเชื่อมั่นหมายถึงการประเมินโดยอิสระที่ให้ความเห็นอย่างเป็นทางการเกี่ยวกับการควบคุมและความเสี่ยง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10298', '2026', 1, 'A.4.d', $q$How do internal auditors determine the appropriate scope for an  advisory engagement?$q$, $q$ผู้ตรวจสอบภายในจะกำหนดขอบเขตที่เหมาะสมสำหรับงานที่ปรึกษาได้อย่างไร?$q$, $q$["They use preset criteria drawn from past advisory engagements, without considering current risks or obtaining stakeholder input in defining scope.", "They define scope based on clear engagement objectives, in‑depth risk assessment, and stakeholder feedback to ensure focused service delivery.", "They primarily define scope on historical data and routine procedures, thereby providing consultative guidance.", "They use standard protocols, limited risk evaluations, and informal management discussions when defining the engagement’s scope."]$q$::jsonb, $q$["พวกเขาใช้เกณฑ์ที่กำหนดไว้ล่วงหน้าจากงานที่ปรึกษาที่ผ่านมา โดยไม่คำนึงถึงความเสี่ยงในปัจจุบันหรือรับข้อมูลจากผู้มีส่วนได้ส่วนเสียในการกำหนดขอบเขต", "โดยกำหนดขอบเขตตามวัตถุประสงค์การมีส่วนร่วมที่ชัดเจน การประเมินความเสี่ยงในเชิงลึก และผลตอบรับของผู้มีส่วนได้ส่วนเสียเพื่อให้แน่ใจว่าการส่งมอบบริการที่มุ่งเน้น", "โดยหลักแล้วจะกำหนดขอบเขตเกี่ยวกับข้อมูลในอดีตและขั้นตอนการปฏิบัติงานตามปกติ โดยจะให้คำแนะนำในการให้คำปรึกษา", "พวกเขาใช้โปรโตคอลมาตรฐาน การประเมินความเสี่ยงที่จำกัด และการอภิปรายของฝ่ายบริหารอย่างไม่เป็นทางการเมื่อกำหนดขอบเขตของงาน"]$q$::jsonb, 1, $q$Correct. Determining boundaries with clear objectives, in‑depth risk assessments, and  systematic stakeholder feedback ensures the engagement is well-focused.$q$, $q$ถูกต้อง. การกำหนดขอบเขตโดยมีวัตถุประสงค์ที่ชัดเจน การประเมินความเสี่ยงในเชิงลึก และผลตอบรับของผู้มีส่วนได้ส่วนเสียอย่างเป็นระบบ ช่วยให้มั่นใจว่าการมีส่วนร่วมนั้นมุ่งเน้นอย่างดี$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10299', '2026', 1, 'A.4.d', $q$When planning an advisory engagement in a dynamic  environment, how is the scope established?$q$, $q$เมื่อวางแผนการให้คำปรึกษาในสภาพแวดล้อมแบบไดนามิก ขอบเขตจะถูกกำหนดอย่างไร$q$, $q$["By evaluating the engagement objectives, conducting risk assessments, and incorporating stakeholder feedback to meet current needs.", "By using an pre-existing template that relies on historical data and standard processes.", "By evaluating routine procedures that focus on past practices, without considering stakeholder input.", "By evaluating existing protocols and stakeholder feedback into the engagement scope."]$q$::jsonb, $q$["โดยการประเมินวัตถุประสงค์ของการมีส่วนร่วม ดำเนินการประเมินความเสี่ยง และนำผลตอบรับของผู้มีส่วนได้ส่วนเสียมาใช้เพื่อสนองความต้องการในปัจจุบัน", "โดยใช้เทมเพลตที่มีอยู่แล้วซึ่งอาศัยข้อมูลประวัติและกระบวนการมาตรฐาน", "โดยการประเมินขั้นตอนการปฏิบัติงานประจำที่เน้นการปฏิบัติที่ผ่านมา โดยไม่พิจารณาข้อมูลจากผู้มีส่วนได้ส่วนเสีย", "โดยการประเมินระเบียบการที่มีอยู่และผลตอบรับของผู้มีส่วนได้ส่วนเสียในขอบเขตการมีส่วนร่วม"]$q$::jsonb, 0, $q$Correct. Evaluating clear objectives, conducting thorough risk assessments, and  incorporating stakeholder feedback ensures the engagement meets current needs.$q$, $q$ถูกต้อง. การประเมินวัตถุประสงค์ที่ชัดเจน การประเมินความเสี่ยงอย่างละเอียด และการนำผลตอบรับของผู้มีส่วนได้ส่วนเสียมาใช้ ช่วยให้มั่นใจว่าการมีส่วนร่วมจะตรงตามความต้องการในปัจจุบัน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10300', '2026', 1, 'A.4.d', $q$How can an internal audit function effectively modify the scope of  its advisory services in response to evolving risks and stakeholder  requirements?$q$, $q$หน่วยงานตรวจสอบภายในสามารถปรับเปลี่ยนขอบเขตบริการให้คำปรึกษาอย่างมีประสิทธิภาพเพื่อตอบสนองต่อความเสี่ยงที่เปลี่ยนแปลงและข้อกำหนดของผู้มีส่วนได้ส่วนเสียได้อย่างไร$q$, $q$["By adjusting the scope based on historical engagement data and current processes.", "By maintaining the advisory objective set at the beginning of the engagement.", "By postponing scope modifications until the annual review despite noticeable changes in risk and stakeholder input.", "By reviewing the engagement objectives, considering emerging risks, and including stakeholder feedback to update the scope."]$q$::jsonb, $q$["โดยการปรับขอบเขตตามข้อมูลการมีส่วนร่วมในอดีตและกระบวนการปัจจุบัน", "โดยคงไว้ซึ่งวัตถุประสงค์ของการให้คำปรึกษาที่กำหนดไว้เมื่อเริ่มต้นงาน", "โดยเลื่อนการปรับเปลี่ยนขอบเขตไปจนถึงการทบทวนประจำปี แม้ว่าจะมีการเปลี่ยนแปลงความเสี่ยงและข้อมูลของผู้มีส่วนได้ส่วนเสียอย่างเห็นได้ชัดก็ตาม", "โดยการทบทวนวัตถุประสงค์ของการมีส่วนร่วม พิจารณาความเสี่ยงที่เกิดขึ้น และรวมถึงข้อเสนอแนะของผู้มีส่วนได้เสียเพื่อปรับปรุงขอบเขต"]$q$::jsonb, 3, $q$Correct. Reviewing objectives, risks, and stakeholder feedback is essential to keeping  the advisory scope current and effective.$q$, $q$ถูกต้อง. การทบทวนวัตถุประสงค์ ความเสี่ยง และผลตอบรับของผู้มีส่วนได้ส่วนเสียถือเป็นสิ่งสำคัญในการรักษาขอบเขตการให้คำปรึกษาให้เป็นปัจจุบันและมีประสิทธิภาพ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10301', '2026', 1, 'A.4.e', $q$A government agency seeks internal audit support to verify the  accuracy of its financial reporting. Which service type is most  suitable if the agency requires a formal, independent opinion on  its financial controls?$q$, $q$หน่วยงานของรัฐต้องการการสนับสนุนการตรวจสอบภายในเพื่อตรวจสอบความถูกต้องของการรายงานทางการเงิน บริการประเภทใดที่เหมาะสมที่สุดหากหน่วยงานต้องการความเห็นอย่างเป็นทางการและเป็นอิสระเกี่ยวกับการควบคุมทางการเงิน$q$, $q$["Advisory services, because they combine formal evaluation with advisory guidance to enhance the reliability of financial reporting.", "Advisory services, because they offer insights and recommendations for improving financial reporting practices through consultative methods.", "Assurance services, because they provide both formal opinions and recommendations for process improvement within a single engagement framework.", "Assurance services, because they systematically evaluate internal controls culminating in a formal, independent opinion."]$q$::jsonb, $q$["บริการให้คำปรึกษา เนื่องจากเป็นการรวมการประเมินอย่างเป็นทางการเข้ากับคำแนะนำที่ปรึกษาเพื่อเพิ่มความน่าเชื่อถือของการรายงานทางการเงิน", "บริการให้คำปรึกษา เนื่องจากให้ข้อมูลเชิงลึกและคำแนะนำในการปรับปรุงแนวทางการรายงานทางการเงินผ่านวิธีการให้คำปรึกษา", "บริการให้ความเชื่อมั่น เนื่องจากให้ทั้งความคิดเห็นอย่างเป็นทางการและคำแนะนำสำหรับการปรับปรุงกระบวนการภายในกรอบงานการปฏิบัติงานเดียว", "บริการด้านการรับประกัน เนื่องจากพวกเขาจะประเมินการควบคุมภายในอย่างเป็นระบบซึ่งจะมีความเห็นอย่างเป็นทางการและเป็นอิสระ"]$q$::jsonb, 3, $q$Correct. Assurance services are the appropriate choice when a formal, independent  opinion is required for the evaluation of internal controls.$q$, $q$ถูกต้อง. บริการให้ความเชื่อมั่นเป็นทางเลือกที่เหมาะสมเมื่อต้องมีความเห็นที่เป็นอิสระและเป็นทางการสำหรับการประเมินการควบคุมภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10302', '2026', 1, 'A.5.a', $q$A technology firm integrates risk and control assessments into its  planning process. Which statement best describes these  assessments?$q$, $q$บริษัทเทคโนโลยีรวมการประเมินความเสี่ยงและการควบคุมเข้ากับกระบวนการวางแผน ข้อความใดอธิบายการประเมินเหล่านี้ได้ดีที่สุด$q$, $q$["They are routine checks that focus on historical performance data rather than on current risk and control effectiveness.", "They are targeted reviews that consider only the most recent incidents without a full evaluation of internal controls.", "They are comprehensive analyses that identify potential risks and evaluate how well internal controls manage these risks.", "They are simplified reviews that emphasize risk identification while giving minimal attention to control evaluation."]$q$::jsonb, $q$["เป็นการตรวจสอบตามปกติที่มุ่งเน้นไปที่ข้อมูลประสิทธิภาพในอดีตมากกว่าความเสี่ยงในปัจจุบันและประสิทธิผลในการควบคุม", "เป็นการทบทวนแบบกำหนดเป้าหมายที่พิจารณาเฉพาะเหตุการณ์ล่าสุดเท่านั้น โดยไม่มีการประเมินการควบคุมภายในอย่างเต็มรูปแบบ", "เป็นการวิเคราะห์ที่ครอบคลุมซึ่งระบุความเสี่ยงที่อาจเกิดขึ้นและประเมินว่าการควบคุมภายในจัดการความเสี่ยงเหล่านี้ได้ดีเพียงใด", "เป็นการทบทวนที่เรียบง่ายซึ่งเน้นการระบุความเสี่ยงในขณะที่ให้ความสำคัญกับการประเมินการควบคุมน้อยที่สุด"]$q$::jsonb, 2, $q$Correct. The comprehensive nature of risk and control assessments highlights both risk  identification and control evaluation.$q$, $q$ถูกต้อง. ลักษณะที่ครอบคลุมของการประเมินความเสี่ยงและการควบคุมเน้นทั้งการระบุความเสี่ยงและการประเมินการควบคุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10303', '2026', 1, 'A.6.g', $q$A company uses process mapping to enhance its internal control  system. What is the internal auditor's role in this context?$q$, $q$บริษัทใช้แผนผังกระบวนการเพื่อปรับปรุงระบบควบคุมภายใน บทบาทของผู้ตรวจสอบภายในในบริบทนี้คืออะไร?$q$, $q$["The auditor designs new control procedures solely based on process mapping outcomes.", "The auditor verifies process accuracy and indicates the identified controls.", "The auditor compiles mapping results for management review and focuses on documenting processes.", "The auditor assists in depicting workflows and providing general oversight of process documentation."]$q$::jsonb, $q$["ผู้ตรวจสอบจะออกแบบขั้นตอนการควบคุมใหม่โดยยึดตามผลลัพธ์ของแผนผังกระบวนการเท่านั้น", "ผู้ตรวจสอบตรวจสอบความถูกต้องของกระบวนการและระบุการควบคุมที่ระบุ", "ผู้ตรวจสอบจะรวบรวมผลลัพธ์การทำแผนที่เพื่อทบทวนฝ่ายบริหารและมุ่งเน้นไปที่กระบวนการจัดทำเอกสาร", "ผู้ตรวจสอบช่วยในการอธิบายขั้นตอนการทำงานและกำกับดูแลทั่วไปของเอกสารกระบวนการ"]$q$::jsonb, 1, $q$Correct. Process mapping captures the steps in process and highlights the controls  identified.$q$, $q$ถูกต้อง. การแม็ปกระบวนการบันทึกขั้นตอนในกระบวนการและเน้นการควบคุมที่ระบุ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10304', '2026', 1, 'A.8.a', $q$When internal auditors are denied access to key management  systems for data analysis, which scenario best represents a risk to  audit independence?$q$, $q$เมื่อผู้ตรวจสอบภายในถูกปฏิเสธไม่ให้เข้าถึงระบบการจัดการที่สำคัญสำหรับการวิเคราะห์ข้อมูล สถานการณ์ใดที่แสดงถึงความเสี่ยงต่อความเป็นอิสระของการตรวจสอบได้ดีที่สุด$q$, $q$["Auditors receive scheduled system updates that partially mitigate the effects of restricted access while maintaining independence.", "Auditors compensate by integrating alternative data sources, which helps preserve the overall objectivity of the review.", "Denied access forces auditors to work with incomplete information, thereby reducing the reliability of their independent assessments.", "Auditors utilize external verification to supplement missing system data, ensuring that independence is largely preserved."]$q$::jsonb, $q$["ผู้ตรวจสอบจะได้รับการอัปเดตระบบตามกำหนดเวลาซึ่งช่วยลดผลกระทบบางส่วนจากการเข้าถึงแบบจำกัดในขณะที่ยังคงความเป็นอิสระ", "ผู้ตรวจสอบจะชดเชยด้วยการบูรณาการแหล่งข้อมูลทางเลือก ซึ่งช่วยให้รักษาความเที่ยงธรรมโดยรวมของการตรวจสอบ", "การเข้าถึงที่ถูกปฏิเสธบังคับให้ผู้ตรวจสอบทำงานกับข้อมูลที่ไม่สมบูรณ์ จึงลดความน่าเชื่อถือของการประเมินโดยอิสระ", "ผู้ตรวจสอบใช้การตรวจสอบจากภายนอกเพื่อเสริมข้อมูลระบบที่ขาดหายไป เพื่อให้มั่นใจว่าความเป็นอิสระส่วนใหญ่จะถูกรักษาไว้"]$q$::jsonb, 2, $q$Correct. Lack of direct access to key management systems can lead to reliance on  incomplete information, which undermines independent evaluations.$q$, $q$ถูกต้อง. การขาดการเข้าถึงโดยตรงไปยังระบบการจัดการที่สำคัญอาจนำไปสู่การพึ่งพาข้อมูลที่ไม่สมบูรณ์ ซึ่งบ่อนทำลายการประเมินโดยหน่วยงานอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10305', '2026', 1, 'A.8.a', $q$When management restricts internal auditors from interviewing key  personnel, which scenario best illustrates a threat to  independence?$q$, $q$เมื่อฝ่ายบริหารจำกัดไม่ให้ผู้ตรวจสอบภายในสัมภาษณ์บุคลากรสำคัญ เหตุการณ์ใดที่แสดงให้เห็นถึงภัยคุกคามต่อความเป็นอิสระได้ดีที่สุด$q$, $q$["Auditors substitute restricted interviews with enhanced document reviews to gather necessary evidence to maintain independence.", "Restricting interviews with key personnel reduces the depth of evidence available, which may compromise the auditors’ ability to assess risks objectively.", "Auditors receive indirect input through alternative communication channels that help ensure adequate information for independent assessments.", "Auditors use structured questionnaires to capture essential insights when direct interviews are not possible, preserving objectivity."]$q$::jsonb, $q$["ผู้ตรวจสอบแทนที่การสัมภาษณ์แบบจำกัดด้วยการตรวจสอบเอกสารที่ได้รับการปรับปรุงเพื่อรวบรวมหลักฐานที่จำเป็นเพื่อรักษาความเป็นอิสระ", "การจำกัดการสัมภาษณ์กับบุคลากรสำคัญจะช่วยลดความลึกของหลักฐานที่มีอยู่ ซึ่งอาจส่งผลต่อความสามารถของผู้ตรวจสอบในการประเมินความเสี่ยงอย่างเป็นกลาง", "ผู้ตรวจสอบจะได้รับข้อมูลทางอ้อมผ่านช่องทางการสื่อสารทางเลือกที่ช่วยให้มั่นใจว่ามีข้อมูลที่เพียงพอสำหรับการประเมินโดยอิสระ", "ผู้ตรวจสอบใช้แบบสอบถามที่มีโครงสร้างเพื่อรวบรวมข้อมูลเชิงลึกที่สำคัญเมื่อไม่สามารถสัมภาษณ์โดยตรงได้ โดยคงไว้ซึ่งความเป็นกลาง"]$q$::jsonb, 1, $q$Correct. Restricting direct interviews with key personnel can limit the completeness of  evidence, affecting the internal auditors’ capacity for independent evaluation.$q$, $q$ถูกต้อง. การจำกัดการสัมภาษณ์โดยตรงกับบุคลากรสำคัญสามารถจำกัดความสมบูรณ์ของหลักฐาน ซึ่งส่งผลต่อความสามารถของผู้ตรวจสอบภายในในการประเมินความเป็นอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10306', '2026', 1, 'B.2.a', $q$In an internal audit engagement, which factor related to self- review of workpapers may impair an auditor's objectivity?$q$, $q$ในการปฏิบัติงานตรวจสอบภายใน ปัจจัยใดที่เกี่ยวข้องกับการตรวจสอบเอกสารทำงานด้วยตนเองอาจทำให้ความเป็นกลางของผู้ตรวจสอบลดลง$q$, $q$["When an auditor gathers supplementary information from external sources to verify their previous analyses.", "When an auditor collaborates with a peer review team, thereby supporting objective evaluation of prior work.", "When an auditor reviews work they previously prepared, it diminishes their critical perspective.", "When an auditor rotates assignments frequently, reducing the chance of reviewing their own prior work."]$q$::jsonb, $q$["เมื่อผู้ตรวจสอบรวบรวมข้อมูลเพิ่มเติมจากแหล่งภายนอกเพื่อตรวจสอบการวิเคราะห์ก่อนหน้านี้", "เมื่อผู้ตรวจสอบร่วมมือกับทีมตรวจสอบโดยผู้ทรงคุณวุฒิ ซึ่งจะสนับสนุนการประเมินตามวัตถุประสงค์ของงานก่อนหน้า", "เมื่อผู้ตรวจสอบตรวจสอบงานที่พวกเขาเตรียมไว้ก่อนหน้านี้ มุมมองที่สำคัญจะลดน้อยลง", "เมื่อผู้ตรวจสอบสับเปลี่ยนการมอบหมายงานบ่อยครั้ง จะเป็นการลดโอกาสในการทบทวนงานก่อนหน้าของตนเอง"]$q$::jsonb, 2, $q$Correct. Self-review bias occurs when auditors examine work they previously performed,  which can impair objectivity.$q$, $q$ถูกต้อง. อคติในการตรวจสอบตนเองเกิดขึ้นเมื่อผู้ตรวจสอบตรวจสอบงานที่พวกเขาทำก่อนหน้านี้ ซึ่งอาจบั่นทอนความเป็นกลางได้$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10307', '2026', 1, 'B.2.a', $q$Which measure is effective in mitigating the impact of self-review  and familiarity bias on an internal auditor's objectivity?$q$, $q$มาตรการใดมีประสิทธิผลในการบรรเทาผลกระทบจากการตรวจสอบตนเองและความลำเอียงด้านความคุ้นเคยต่อความเที่ยงธรรมของผู้ตรวจสอบภายใน$q$, $q$["Requiring auditors to sign a form acknowledging their commitment to ethical behavior.", "Encouraging auditors to use historical data as the primary basis for evaluation minimizes self-review risk.", "Assigning independent review work to auditors not involved in the original audit engagement helps prevent bias.", "Implementing strict standardized procedures alone is sufficient to control both self-review and familiarity bias."]$q$::jsonb, $q$["กำหนดให้ผู้ตรวจสอบลงนามในแบบฟอร์มรับทราบความมุ่งมั่นต่อพฤติกรรมที่มีจริยธรรม", "การสนับสนุนให้ผู้ตรวจสอบใช้ข้อมูลในอดีตเป็นพื้นฐานหลักในการประเมินช่วยลดความเสี่ยงในการตรวจสอบตนเอง", "การมอบหมายงานสอบทานที่เป็นอิสระให้กับผู้ตรวจสอบที่ไม่เกี่ยวข้องกับงานตรวจสอบเริ่มแรกจะช่วยป้องกันอคติ", "การใช้ขั้นตอนมาตรฐานที่เข้มงวดเพียงอย่างเดียวก็เพียงพอแล้วในการควบคุมทั้งการทบทวนตนเองและความลำเอียงด้านความคุ้นเคย"]$q$::jsonb, 2, $q$Correct. Independent review assignments effectively mitigate the risk of self-review and  familiarity bias, supporting objective assessments.$q$, $q$ถูกต้อง. การมอบหมายการทบทวนโดยอิสระช่วยลดความเสี่ยงของการทบทวนตนเองและความลำเอียงด้านความคุ้นเคยได้อย่างมีประสิทธิภาพ ซึ่งสนับสนุนการประเมินตามวัตถุประสงค์$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10308', '2026', 1, 'B.2.b', $q$When management limits internal auditors’ access to key financial  records, which scenario best demonstrates a potential impairment  of internal audit independence?$q$, $q$เมื่อฝ่ายบริหารจำกัดการเข้าถึงบันทึกทางการเงินที่สำคัญของผู้ตรวจสอบภายใน สถานการณ์ใดที่แสดงให้เห็นถึงความบกพร่องของความเป็นอิสระในการตรวจสอบภายในได้ดีที่สุด$q$, $q$["Auditors obtain comprehensive, summarized financial records that enable a reasonably independent review despite some data limitations.", "Auditors receive incomplete financial data that reduces their ability to form independent conclusions and compromises overall objectivity.", "Auditors access redacted financial records along with supplementary reconciliations that support an independent evaluation of controls.", "Auditors receive partial financial data that is regularly supplemented by scheduled management updates, helping to maintain overall objectivity."]$q$::jsonb, $q$["ผู้ตรวจสอบจะได้รับบันทึกทางการเงินโดยสรุปที่ครอบคลุม ซึ่งช่วยให้สามารถตรวจสอบอย่างเป็นอิสระได้อย่างสมเหตุสมผล แม้ว่าจะมีข้อจำกัดด้านข้อมูลบางประการก็ตาม", "ผู้ตรวจสอบได้รับข้อมูลทางการเงินที่ไม่สมบูรณ์ ซึ่งทำให้ความสามารถในการสรุปผลที่เป็นอิสระลดลง และลดทอนความเที่ยงธรรมโดยรวม", "ผู้ตรวจสอบจะเข้าถึงบันทึกทางการเงินที่แก้ไขแล้วพร้อมกับการกระทบยอดเพิ่มเติมที่สนับสนุนการประเมินการควบคุมที่เป็นอิสระ", "ผู้ตรวจสอบจะได้รับข้อมูลทางการเงินบางส่วนซึ่งเสริมด้วยการอัปเดตการจัดการตามกำหนดเวลาเป็นประจำ ซึ่งช่วยรักษาความเที่ยงธรรมโดยรวม"]$q$::jsonb, 1, $q$Correct. Limited access to complete financial records may force auditors to rely on  incomplete data, undermining their ability to evaluate risks independently.$q$, $q$ถูกต้อง. การเข้าถึงบันทึกทางการเงินที่ครบถ้วนอย่างจำกัดอาจบังคับให้ผู้ตรวจสอบต้องพึ่งพาข้อมูลที่ไม่สมบูรณ์ ซึ่งบั่นทอนความสามารถในการประเมินความเสี่ยงอย่างอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10309', '2026', 1, 'B.2.b', $q$When an internal auditor holds a financial interest in a vendor,  which scenario best reflects a potential conflict of interest that  could impair objectivity?$q$, $q$เมื่อผู้ตรวจสอบภายในถือครองผลประโยชน์ทางการเงินในผู้ขาย สถานการณ์ใดที่สะท้อนถึงความขัดแย้งทางผลประโยชน์ที่อาจเกิดขึ้นซึ่งอาจทำให้ความเป็นกลางลดลงได้ดีที่สุด$q$, $q$["An auditor with no personal financial interest in any vendor consistently ensures that evaluations remain completely unbiased throughout the audit process.", "An auditor with a financial stake in a vendor under review faces a conflict that may impair impartiality and audit outcomes.", "An auditor who fully discloses financial investments minimizes the risk of impaired objectivity effectively.", "An auditor assigned to a different vendor audit engagement avoids conflicts and maintains independent judgment throughout the audit process."]$q$::jsonb, $q$["ผู้ตรวจสอบที่ไม่มีผลประโยชน์ทางการเงินส่วนบุคคลในผู้ขายรายใดๆ จะคอยให้แน่ใจว่าการประเมินมีความเป็นกลางอย่างสมบูรณ์ตลอดกระบวนการตรวจสอบ", "ผู้ตรวจสอบที่มีส่วนได้ส่วนเสียทางการเงินในผู้ขายที่อยู่ระหว่างการตรวจสอบต้องเผชิญกับความขัดแย้งที่อาจทำให้ความเป็นกลางและผลการตรวจสอบลดลง", "ผู้ตรวจสอบบัญชีที่เปิดเผยการลงทุนทางการเงินอย่างครบถ้วนจะช่วยลดความเสี่ยงของความเป็นกลางได้อย่างมีประสิทธิภาพ", "ผู้ตรวจสอบที่ได้รับมอบหมายให้ทำหน้าที่ตรวจสอบผู้ขายรายอื่นจะหลีกเลี่ยงความขัดแย้งและรักษาดุลยพินิจที่เป็นอิสระตลอดกระบวนการตรวจสอบ"]$q$::jsonb, 1, $q$Correct. A financial stake in a vendor creates a direct conflict that may impair impartiality  and compromise audit outcomes.$q$, $q$ถูกต้อง. สัดส่วนทางการเงินในผู้ขายก่อให้เกิดความขัดแย้งโดยตรงซึ่งอาจบั่นทอนความเป็นกลางและกระทบต่อผลลัพธ์การตรวจสอบ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10310', '2026', 1, 'B.3.a', $q$Which policy option best promotes objectivity when potential  conflicts of interest arise from an internal auditor’s assignment to a  department where personal relationships exist?$q$, $q$ตัวเลือกนโยบายใดที่ส่งเสริมความเป็นกลางได้ดีที่สุดเมื่อความขัดแย้งทางผลประโยชน์ที่อาจเกิดขึ้นจากการมอบหมายของผู้ตรวจสอบภายในให้กับแผนกที่มีความสัมพันธ์ส่วนตัว$q$, $q$["Enhancing supervisory reviews of the auditor’s work while maintaining the current departmental assignment.", "Requiring the auditor to disclose the personal relationship while continuing in the same department.", "Implementing a peer review process while allowing the auditor to remain in the same assignment.", "Reassigning the auditor to a different department to eliminate negative impact on objectivity."]$q$::jsonb, $q$["เสริมสร้างการตรวจสอบการกำกับดูแลงานของผู้ตรวจสอบบัญชีในขณะที่ยังคงรักษาการมอบหมายงานของแผนกในปัจจุบัน", "กำหนดให้ผู้ตรวจสอบบัญชีเปิดเผยความสัมพันธ์ส่วนตัวในขณะที่ยังอยู่ในแผนกเดียวกัน", "การใช้กระบวนการทบทวนโดยผู้ทรงคุณวุฒิในขณะที่อนุญาตให้ผู้ตรวจสอบยังคงอยู่ในงานที่ได้รับมอบหมายเดิม", "มอบหมายผู้ตรวจสอบใหม่ให้กับแผนกอื่นเพื่อลดผลกระทบด้านลบต่อความเป็นกลาง"]$q$::jsonb, 3, $q$Correct. Reassigning the auditor removes the conflict of interest and thereby promotes  objectivity.$q$, $q$ถูกต้อง. การมอบหมายผู้ตรวจสอบใหม่จะขจัดความขัดแย้งทางผลประโยชน์และส่งเสริมความเที่ยงธรรม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10311', '2026', 1, 'B.3.a', $q$A firm's audit policy includes a regular rotation of audit  assignments. What is the primary benefit of this rotation in terms of  maintaining objectivity?$q$, $q$นโยบายการตรวจสอบของบริษัทรวมถึงการหมุนเวียนงานตรวจสอบเป็นประจำ ประโยชน์หลักของการหมุนเวียนนี้ในแง่ของการรักษาความเป็นกลางคืออะไร?$q$, $q$["It reduces the workload on auditors, thereby decreasing the risk of errors in evaluations.", "It minimizes familiarity bias by ensuring auditors are periodically exposed to new areas and challenges.", "It improves auditors' skills through exposure to diverse operational processes, regardless of objectivity.", "It allows auditors to develop closer working relationships with management in different areas, enhancing collaboration."]$q$::jsonb, $q$["ช่วยลดภาระงานของผู้ตรวจสอบ จึงลดความเสี่ยงของข้อผิดพลาดในการประเมิน", "ลดอคติด้านความคุ้นเคยโดยทำให้แน่ใจว่าผู้ตรวจสอบจะต้องเผชิญกับความท้าทายและความท้าทายใหม่ๆ เป็นระยะๆ", "ช่วยเพิ่มทักษะของผู้ตรวจสอบผ่านการสัมผัสกับกระบวนการปฏิบัติงานที่หลากหลาย โดยไม่คำนึงถึงวัตถุประสงค์", "ช่วยให้ผู้ตรวจสอบพัฒนาความสัมพันธ์ในการทำงานที่ใกล้ชิดกับฝ่ายบริหารในด้านต่างๆ มากขึ้น เสริมสร้างการทำงานร่วมกัน"]$q$::jsonb, 1, $q$Correct. Regular rotation minimizes familiarity bias by exposing internal auditors to  various areas, which supports independent evaluations.$q$, $q$ถูกต้อง. การหมุนเวียนอย่างสม่ำเสมอจะช่วยลดอคติด้านความคุ้นเคยโดยทำให้ผู้ตรวจสอบภายในได้สัมผัสกับพื้นที่ต่างๆ ซึ่งสนับสนุนการประเมินโดยอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10312', '2026', 1, 'B.3.a', $q$When repeated audit engagements in the same business unit  raise concerns about an internal auditor’s impartiality, which  option best supports a mitigation strategy?$q$, $q$เมื่อการตรวจสอบซ้ำในหน่วยธุรกิจเดียวกันทำให้เกิดความกังวลเกี่ยวกับความเป็นกลางของผู้ตรวจสอบภายใน ตัวเลือกใดที่สนับสนุนกลยุทธ์การลดผลกระทบได้ดีที่สุด$q$, $q$["Implementing a rotation policy that periodically reassigns auditors to different business units to prevent excessive familiarity.", "Increasing the frequency of internal quality reviews for the auditor in the same business unit.", "Requiring detailed documentation of potential biases during engagements in that business unit.", "Augmenting the auditor’s assignment with external oversight without changing the current assignment."]$q$::jsonb, $q$["การใช้นโยบายการหมุนเวียนที่กำหนดผู้ตรวจสอบบัญชีใหม่เป็นระยะๆ ไปยังหน่วยธุรกิจต่างๆ เพื่อป้องกันความคุ้นเคยมากเกินไป", "เพิ่มความถี่ในการตรวจสอบคุณภาพภายในของผู้ตรวจสอบบัญชีในหน่วยธุรกิจเดียวกัน", "ต้องการเอกสารโดยละเอียดเกี่ยวกับอคติที่อาจเกิดขึ้นระหว่างการนัดหมายในหน่วยธุรกิจนั้น", "เพิ่มการมอบหมายงานของผู้สอบบัญชีด้วยการกำกับดูแลจากภายนอกโดยไม่ต้องเปลี่ยนงานมอบหมายปัจจุบัน"]$q$::jsonb, 0, $q$Correct. Periodic rotation to different business units is an effective strategy to reduce  familiarity bias and preserve objectivity.$q$, $q$ถูกต้อง. การหมุนเวียนไปยังหน่วยธุรกิจต่างๆ เป็นระยะเป็นกลยุทธ์ที่มีประสิทธิภาพในการลดอคติด้านความคุ้นเคยและรักษาความเป็นกลาง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10313', '2026', 1, 'B.3.b', $q$In an internal audit engagement involving a politically sensitive  department, which option best mitigates internal influence to  ensure objective evaluation?$q$, $q$ในการปฏิบัติงานตรวจสอบภายในที่เกี่ยวข้องกับแผนกที่มีความอ่อนไหวทางการเมือง ตัวเลือกใดที่จะลดอิทธิพลภายในได้ดีที่สุดเพื่อให้มั่นใจว่ามีการประเมินตามวัตถุประสงค์$q$, $q$["Enhancing the independence of the internal audit engagement team by rotating assignments more frequently within the sensitive area.", "Reassigning the engagement internally to an auditor from a different division with limited exposure to the sensitive department.", "Implementing strict internal controls and a dual-review process within the department to mitigate potential bias.", "Outsourcing the supervision of the engagement to an external party with no internal political affiliations to ensure unbiased oversight."]$q$::jsonb, $q$["เพิ่มความเป็นอิสระให้กับทีมงานผู้ปฏิบัติงานตรวจสอบภายในโดยการหมุนเวียนงานมอบหมายให้บ่อยขึ้นภายในขอบเขตที่ละเอียดอ่อน", "มอบหมายงานมอบหมายใหม่ภายในให้กับผู้ตรวจสอบบัญชีจากแผนกอื่นโดยจำกัดความเสี่ยงต่อแผนกที่มีความละเอียดอ่อน", "การใช้การควบคุมภายในที่เข้มงวดและกระบวนการตรวจสอบแบบคู่ภายในแผนกเพื่อลดอคติที่อาจเกิดขึ้น", "จ้างบุคคลภายนอกในการกำกับดูแลการมีส่วนร่วมกับบุคคลภายนอกที่ไม่มีความเกี่ยวข้องทางการเมืองภายในเพื่อให้การกำกับดูแลที่เป็นกลาง"]$q$::jsonb, 3, $q$Correct. Outsourcing supervision to an external party helps remove internal political  influences, thereby promoting an unbiased evaluation in sensitive contexts.$q$, $q$ถูกต้อง. การกำกับดูแลจากภายนอกไปยังบุคคลภายนอกช่วยขจัดอิทธิพลทางการเมืองภายใน ดังนั้นจึงส่งเสริมการประเมินที่เป็นกลางในบริบทที่ละเอียดอ่อน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10314', '2026', 1, 'B.3.d', $q$In situations where an internal auditor receives a favor from  operational management, which approach best upholds  objectivity according to internal policies?$q$, $q$ในสถานการณ์ที่ผู้ตรวจสอบภายในได้รับความโปรดปรานจากฝ่ายบริหารการปฏิบัติงาน วิธีใดที่ยึดถือความเป็นกลางตามนโยบายภายในได้ดีที่สุด$q$, $q$["Accepting the favor only after obtaining written consent from a supervisor.", "Refusing the favor and promptly reporting the incident to the appropriate oversight body.", "Discussing the favor with peers and then deciding on acceptance based on documented criteria.", "Temporarily postponing the decision on the favor until after the engagement."]$q$::jsonb, $q$["การยอมรับความโปรดปรานหลังจากได้รับความยินยอมเป็นลายลักษณ์อักษรจากหัวหน้างานเท่านั้น", "ปฏิเสธความโปรดปรานและรายงานเหตุการณ์ดังกล่าวต่อหน่วยงานกำกับดูแลที่เหมาะสมโดยทันที", "หารือเกี่ยวกับความโปรดปรานกับเพื่อนฝูง และตัดสินใจยอมรับตามเกณฑ์ที่บันทึกไว้", "เลื่อนการตัดสินใจเรื่องโปรดปรานออกไปชั่วคราวจนกว่าจะมีการหมั้นหมาย"]$q$::jsonb, 1, $q$Correct. Refusing the favor and reporting it ensures that personal biases are minimized  and objectivity is preserved.$q$, $q$ถูกต้อง. การปฏิเสธความโปรดปรานและการรายงานจะทำให้มั่นใจได้ว่าอคติส่วนบุคคลจะลดลงและรักษาความเป็นกลางเอาไว้$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10315', '2026', 1, 'B.3.d', $q$How does a policy addressing gifts, rewards, or favors best  support the internal audit function's objectivity?$q$, $q$นโยบายที่เกี่ยวข้องกับของขวัญ รางวัล หรือความช่วยเหลือสนับสนุนความเที่ยงธรรมของหน่วยงานตรวจสอบภายในได้ดีที่สุดอย่างไร$q$, $q$["A policy that requires internal auditors to decline and immediately report all gifts, rewards, or favors upholds objectivity.", "A policy that permits acceptance of items below a specified value while mandating disclosure supports objectivity.", "A policy that advises auditors to consult with their supervisor prior to accepting any gift contributes to maintaining objectivity.", "A policy that recommends documenting any received gifts without immediate reporting can help preserve objectivity."]$q$::jsonb, $q$["นโยบายที่กำหนดให้ผู้ตรวจสอบภายในปฏิเสธและรายงานของขวัญ รางวัล หรือความช่วยเหลือทั้งหมดโดยทันทีถือเป็นการรักษาความเป็นกลาง", "นโยบายที่อนุญาตให้ยอมรับรายการต่ำกว่าค่าที่ระบุในขณะที่บังคับให้เปิดเผยข้อมูลสนับสนุนความเป็นกลาง", "นโยบายที่แนะนำให้ผู้ตรวจสอบปรึกษากับหัวหน้างานก่อนที่จะรับของขวัญใดๆ จะมีส่วนช่วยในการรักษาความเป็นกลาง", "นโยบายที่แนะนำให้บันทึกของขวัญที่ได้รับโดยไม่ต้องรายงานทันทีสามารถช่วยรักษาความเป็นกลางได้"]$q$::jsonb, 0, $q$Correct. A clear policy that mandates declining and reporting all such items reinforces  the internal auditor’s independence and objectivity.$q$, $q$ถูกต้อง. นโยบายที่ชัดเจนที่กำหนดให้ปฏิเสธและรายงานรายการดังกล่าวทั้งหมดเป็นการเสริมความเป็นอิสระและความเที่ยงธรรมของผู้ตรวจสอบภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10316', '2026', 1, 'B.4.a', $q$A mid-sized company seeks to improve its internal audit reporting.  How can effective written communication skills be applied to  enhance audit reports?$q$, $q$บริษัทขนาดกลางพยายามที่จะปรับปรุงการรายงานการตรวจสอบภายในของตน  ทักษะการสื่อสารที่เป็นลายลักษณ์อักษรที่มีประสิทธิภาพสามารถนำไปใช้เพื่อปรับปรุงรายงานการตรวจสอบได้อย่างไร?$q$, $q$["By incorporating specialized technical jargon and extensive details to demonstrate comprehensive expertise.", "By using clear, concise language with well-organized sections that highlight key findings and recommendations.", "By providing lengthy narrative explanations that cover all background information.", "By emphasizing data presentation without summarizing the core insights for the intended audience."]$q$::jsonb, $q$["โดยผสมผสานศัพท์แสงทางเทคนิคเฉพาะทางและรายละเอียดที่กว้างขวางเพื่อแสดงให้เห็นถึงความเชี่ยวชาญที่ครอบคลุม", "โดยใช้ภาษาที่ชัดเจน กระชับ โดยมีส่วนที่มีการจัดระเบียบอย่างดีซึ่งเน้นประเด็นสำคัญและข้อเสนอแนะ", "โดยให้คำอธิบายแบบเล่าเรื่องยาวครอบคลุมข้อมูลเบื้องหลังทั้งหมด", "โดยเน้นการนำเสนอข้อมูลโดยไม่สรุปข้อมูลเชิงลึกหลักให้กับกลุ่มเป้าหมาย"]$q$::jsonb, 1, $q$Correct. Clear, concise language with structured sections enables audit reports to  effectively communicate key findings and actionable recommendations.$q$, $q$ถูกต้อง. ภาษาที่ชัดเจนและกระชับพร้อมส่วนที่มีโครงสร้างทำให้รายงานการตรวจสอบสามารถสื่อสารข้อค้นพบที่สำคัญและคำแนะนำที่สามารถนำไปปฏิบัติได้อย่างมีประสิทธิภาพ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10317', '2026', 1, 'B.4.a', $q$In preparation for an audit committee meeting, an internal auditor  is tasked with delivering a persuasive presentation. Which  approach best applies effective presentation skills?$q$, $q$ในการเตรียมการประชุมคณะกรรมการตรวจสอบ ผู้ตรวจสอบภายในมีหน้าที่นำเสนอข้อมูลเชิงโน้มน้าวใจ วิธีใดที่ใช้ทักษะการนำเสนอที่มีประสิทธิภาพได้ดีที่สุด$q$, $q$["Focusing on reading through report slides.", "Creating a detailed presentation that covers all aspects of the audit engagement.", "Relying primarily on verbal explanations with minimal use of visual aids, which may disengage the audience.", "Developing a well-organized slide deck that emphasizes major risk areas and includes actionable recommendations."]$q$::jsonb, $q$["เน้นการอ่านผ่านสไลด์รายงาน", "การสร้างการนำเสนอโดยละเอียดที่ครอบคลุมทุกด้านของงานตรวจสอบ", "อาศัยการอธิบายด้วยวาจาเป็นหลักโดยใช้อุปกรณ์ช่วยการมองเห็นให้น้อยที่สุด ซึ่งอาจจะทำให้ผู้ฟังรู้สึกไม่มีส่วนร่วม", "การพัฒนาชุดสไลด์ที่มีการจัดระเบียบอย่างดีซึ่งเน้นพื้นที่เสี่ยงหลักและรวมถึงคำแนะนำที่สามารถนำไปปฏิบัติได้"]$q$::jsonb, 3, $q$Correct. A well-organized presentation that underscores key risk areas and actionable  steps is most effective for engaging the audit committee.$q$, $q$ถูกต้อง. การนำเสนอที่มีการจัดการอย่างดีซึ่งเน้นย้ำประเด็นความเสี่ยงหลักและขั้นตอนการปฏิบัติจะมีประสิทธิภาพสูงสุดในการดึงดูดคณะกรรมการตรวจสอบ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10318', '2026', 1, 'B.4.a', $q$An internal auditor must write a summary report for senior  management. How can effective written communication be  applied to ensure the report is both informative and accessible?$q$, $q$ผู้ตรวจสอบภายในจะต้องเขียนรายงานสรุปให้กับผู้บริหารระดับสูง การสื่อสารที่เป็นลายลักษณ์อักษรที่มีประสิทธิภาพสามารถนำไปใช้ได้อย่างไรเพื่อให้แน่ใจว่ารายงานมีทั้งข้อมูลและเข้าถึงได้$q$, $q$["By including technical details and comprehensive background information for the reader.", "By composing a concise summary that clearly states the objectives, key findings, and actionable recommendations in plain language.", "By providing a broad overview with minimal focus on critical findings and recommendations.", "By using formal language and long sentence structures to ensure clarity."]$q$::jsonb, $q$["โดยรวมรายละเอียดทางเทคนิคและข้อมูลความเป็นมาที่ครอบคลุมสำหรับผู้อ่าน", "โดยเขียนสรุปโดยย่อโดยระบุวัตถุประสงค์ ข้อค้นพบที่สำคัญ และคำแนะนำที่สามารถนำไปปฏิบัติได้อย่างชัดเจนด้วยภาษาธรรมดา", "โดยการให้ภาพรวมกว้างๆ โดยเน้นที่ข้อค้นพบและคำแนะนำที่สำคัญน้อยที่สุด", "โดยใช้ภาษาที่เป็นทางการและโครงสร้างประโยคที่ยาวเพื่อให้เกิดความชัดเจน"]$q$::jsonb, 1, $q$Correct. A concise, clearly written summary that outlines objectives, findings, and  recommendations in plain language is most effective for senior management.$q$, $q$ถูกต้อง. การสรุปที่กระชับและเขียนอย่างชัดเจนซึ่งสรุปวัตถุประสงค์ ข้อค้นพบ และคำแนะนำในภาษาธรรมดาจะมีประสิทธิภาพมากที่สุดสำหรับผู้บริหารระดับสูง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10319', '2026', 1, 'B.4.b', $q$An internal auditor is preparing a written executive summary of an  audit engagement. How should the auditor apply communication  skills to ensure the summary is effective?$q$, $q$ผู้ตรวจสอบภายในกำลังจัดทำบทสรุปผู้บริหารที่เป็นลายลักษณ์อักษรเกี่ยวกับงานตรวจสอบ ผู้ตรวจสอบควรใช้ทักษะในการสื่อสารอย่างไรเพื่อให้แน่ใจว่าการสรุปมีประสิทธิผล$q$, $q$["By providing a narrative that focuses on the audit methodology and avoids conclusions and recommendations.", "By detailing every aspect of the audit process to ensure all information is covered.", "By including technical details and data without other insights for executives.", "By writing a succinct summary that presents audit objectives, key findings, and actionable recommendations in a straightforward manner."]$q$::jsonb, $q$["โดยจัดให้มีการเล่าเรื่องที่เน้นวิธีการตรวจสอบและหลีกเลี่ยงข้อสรุปและข้อเสนอแนะ", "โดยให้รายละเอียดทุกแง่มุมของกระบวนการตรวจสอบเพื่อให้แน่ใจว่าข้อมูลทั้งหมดได้รับการคุ้มครอง", "โดยรวมรายละเอียดทางเทคนิคและข้อมูลโดยไม่มีข้อมูลเชิงลึกอื่น ๆ สำหรับผู้บริหาร", "โดยการเขียนสรุปสั้นๆ ที่นำเสนอวัตถุประสงค์การตรวจสอบ ข้อค้นพบที่สำคัญ และคำแนะนำที่สามารถนำไปปฏิบัติได้ในลักษณะตรงไปตรงมา"]$q$::jsonb, 3, $q$Correct. A succinct executive summary that focuses on audit objectives, key findings,  and recommendations facilitates clear and effective communication.$q$, $q$ถูกต้อง. บทสรุปผู้บริหารโดยกระชับซึ่งมุ่งเน้นไปที่วัตถุประสงค์การตรวจสอบ ข้อค้นพบที่สำคัญ และคำแนะนำ ช่วยให้การสื่อสารมีความชัดเจนและมีประสิทธิภาพ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10320', '2026', 1, 'B.5.e', $q$How should an internal auditor demonstrate professional  skepticism when evaluating internal controls?$q$, $q$ผู้ตรวจสอบภายในควรแสดงความสงสัยอย่างมืออาชีพเมื่อประเมินการควบคุมภายในอย่างไร$q$, $q$["By assuming that established controls remain effective based on their historical performance records.", "By assessing control evidence objectively, seeking additional validation, and questioning any discrepancies in the data.", "By relying on standard procedures to review controls to detect any discrepancies.", "By conducting routine checks and utilizing evidence provided."]$q$::jsonb, $q$["โดยสมมติว่าการควบคุมที่จัดตั้งขึ้นยังคงมีผลใช้บังคับตามบันทึกผลการปฏิบัติงานในอดีต", "โดยการประเมินหลักฐานการควบคุมอย่างเป็นกลาง แสวงหาการตรวจสอบเพิ่มเติม และตั้งคำถามถึงความคลาดเคลื่อนในข้อมูล", "โดยอาศัยขั้นตอนมาตรฐานในการตรวจสอบการควบคุมเพื่อตรวจจับความคลาดเคลื่อนใดๆ", "โดยดำเนินการตรวจสอบเป็นประจำและใช้หลักฐานที่จัดให้"]$q$::jsonb, 1, $q$Correct. Objectively assessing control evidence and seeking further validation when  discrepancies arise is key to ensuring independent evaluations.$q$, $q$ถูกต้อง. การประเมินหลักฐานการควบคุมอย่างเป็นกลางและการแสวงหาการตรวจสอบเพิ่มเติมเมื่อเกิดความคลาดเคลื่อนถือเป็นกุญแจสำคัญในการรับรองการประเมินที่เป็นอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10321', '2026', 1, 'B.5.e', $q$How can an internal auditor maintain professional skepticism  when facing potential bias during a self-review process?$q$, $q$ผู้ตรวจสอบภายในจะรักษาความสงสัยทางวิชาชีพเมื่อเผชิญกับอคติที่อาจเกิดขึ้นในระหว่างกระบวนการตรวจสอบตนเองได้อย่างไร$q$, $q$["How can an internal auditor maintain professional skepticism when facing potential bias during a self- review process? By comparing previous work with independent audit findings to identify signs of bias.", "By reviewing previous work based on standard practices.", "By relying on historical data and internal reviews to verify past work.", "By critically evaluating prior work with a fresh perspective and seeking external confirmation to offset inherent biases."]$q$::jsonb, $q$["ผู้ตรวจสอบภายในจะรักษาความสงสัยทางวิชาชีพเมื่อเผชิญกับอคติที่อาจเกิดขึ้นในระหว่างกระบวนการตรวจสอบตนเองได้อย่างไร โดยการเปรียบเทียบงานก่อนหน้ากับผลการตรวจสอบที่เป็นอิสระเพื่อระบุสัญญาณของอคติ", "โดยทบทวนงานที่ผ่านมาตามหลักปฏิบัติมาตรฐาน", "โดยอาศัยข้อมูลประวัติและการตรวจสอบภายในเพื่อตรวจสอบการทำงานที่ผ่านมา", "โดยการประเมินงานก่อนหน้านี้อย่างมีวิจารณญาณด้วยมุมมองที่สดใหม่ และแสวงหาการยืนยันจากภายนอกเพื่อชดเชยอคติโดยธรรมชาติ"]$q$::jsonb, 3, $q$Correct. Critically re-evaluating one’s own work and obtaining external confirmation are  key practices for mitigating self-review bias.$q$, $q$ถูกต้อง. การประเมินงานของตัวเองอย่างมีวิจารณญาณและการได้รับการยืนยันจากภายนอกเป็นแนวทางปฏิบัติหลักในการบรรเทาอคติในการทบทวนตนเอง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10322', '2026', 1, 'B.6.a', $q$When storing digital audit records that contain sensitive  information, which measure best promotes confidentiality?$q$, $q$เมื่อจัดเก็บบันทึกการตรวจสอบดิจิทัลที่มีข้อมูลที่ละเอียดอ่อน มาตรการใดที่ส่งเสริมการรักษาความลับได้ดีที่สุด$q$, $q$["Archiving data on secure servers and periodically reviewing access logs to ensure proper use.", "Using password-protected storage solutions and limiting access through departmental controls.", "Encrypting the data, restricting access to authorized users, and ensuring compliance with organizational security policies and legal standards.", "Implementing digital access controls and training staff on confidentiality practices during audit engagements."]$q$::jsonb, $q$["เก็บข้อมูลบนเซิร์ฟเวอร์ที่ปลอดภัยและตรวจสอบบันทึกการเข้าถึงเป็นระยะเพื่อให้แน่ใจว่ามีการใช้งานที่เหมาะสม", "การใช้โซลูชันการจัดเก็บข้อมูลที่มีการป้องกันด้วยรหัสผ่านและการจำกัดการเข้าถึงผ่านการควบคุมของแผนก", "การเข้ารหัสข้อมูล จำกัดการเข้าถึงเฉพาะผู้ใช้ที่ได้รับอนุญาต และรับรองการปฏิบัติตามนโยบายความปลอดภัยขององค์กรและมาตรฐานทางกฎหมาย", "การใช้การควบคุมการเข้าถึงแบบดิจิทัลและการฝึกอบรมพนักงานเกี่ยวกับแนวทางปฏิบัติในการรักษาความลับระหว่างการตรวจสอบ"]$q$::jsonb, 2, $q$Correct. Encrypting data and restricting access to authorized users according to policies  and legal standards is essential to protecting sensitive digital records.$q$, $q$ถูกต้อง. การเข้ารหัสข้อมูลและการจำกัดการเข้าถึงของผู้ใช้ที่ได้รับอนุญาตตามนโยบายและมาตรฐานทางกฎหมายถือเป็นสิ่งสำคัญในการปกป้องบันทึกดิจิทัลที่ละเอียดอ่อน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10323', '2026', 1, 'B.6.b', $q$In an internal audit engagement reviewing sensitive financial data,  how can an auditor apply internal audit methodologies to maintain  confidentiality and appropriate use of information?$q$, $q$ในการปฏิบัติงานตรวจสอบภายในที่ตรวจสอบข้อมูลทางการเงินที่ละเอียดอ่อน ผู้ตรวจสอบจะใช้วิธีการตรวจสอบภายในเพื่อรักษาความลับและการใช้ข้อมูลอย่างเหมาะสมได้อย่างไร$q$, $q$["By relying on standard procedures and including a confidentiality clause.", "By following secure data handling procedures, encrypting records, and limiting access to authorized personnel in accordance with organizational policies.", "By using the organization's standard data storage solutions.", "By summarizing key findings in reports to avoid internal protocols for handling sensitive data."]$q$::jsonb, $q$["โดยอาศัยขั้นตอนมาตรฐานและรวมถึงข้อกำหนดการรักษาความลับ", "โดยปฏิบัติตามขั้นตอนการจัดการข้อมูลที่ปลอดภัย การเข้ารหัสบันทึก และการจำกัดการเข้าถึงบุคลากรที่ได้รับอนุญาตตามนโยบายองค์กร", "โดยใช้โซลูชั่นการจัดเก็บข้อมูลมาตรฐานขององค์กร", "โดยการสรุปการค้นพบที่สำคัญในรายงานเพื่อหลีกเลี่ยงโปรโตคอลภายในสำหรับการจัดการข้อมูลที่ละเอียดอ่อน"]$q$::jsonb, 1, $q$Correct. Adhering to secure data handling, encryption, and controlled access per  internal audit methodologies is essential to maintaining confidentiality.$q$, $q$ถูกต้อง. การยึดมั่นในการจัดการข้อมูลที่ปลอดภัย การเข้ารหัส และการควบคุมการเข้าถึงตามวิธีการตรวจสอบภายในถือเป็นสิ่งสำคัญในการรักษาความลับ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10324', '2026', 1, 'B.6.b', $q$During an audit engagement of a sensitive business unit, how can  an auditor apply internal audit methodologies to ensure  confidential information is handled appropriately?$q$, $q$ในระหว่างการตรวจสอบของหน่วยธุรกิจที่มีความละเอียดอ่อน ผู้ตรวจสอบจะใช้วิธีการตรวจสอบภายในเพื่อให้มั่นใจว่าข้อมูลที่เป็นความลับได้รับการจัดการอย่างเหมาะสมได้อย่างไร$q$, $q$["By storing all audit information in a standard shared drive to promote ready access.", "By enforcing strict internal controls on data storage, limiting access, and documenting information flows in compliance with security policies.", "By using standard methods for data sharing to promote accessibility.", "By relying on unique ad hoc data storage methods instead of the usual organizational storage measures."]$q$::jsonb, $q$["โดยจัดเก็บข้อมูลการตรวจสอบทั้งหมดไว้ในไดรฟ์ที่ใช้ร่วมกันแบบมาตรฐานเพื่อส่งเสริมการเข้าถึงที่พร้อมใช้งาน", "โดยการบังคับใช้การควบคุมภายในที่เข้มงวดในการจัดเก็บข้อมูล การจำกัดการเข้าถึง และการบันทึกการไหลของข้อมูลตามนโยบายความปลอดภัย", "โดยใช้วิธีมาตรฐานในการแบ่งปันข้อมูลเพื่อส่งเสริมการเข้าถึง", "โดยอาศัยวิธีการจัดเก็บข้อมูลเฉพาะกิจเฉพาะกิจแทนมาตรการจัดเก็บข้อมูลขององค์กรตามปกติ"]$q$::jsonb, 1, $q$Correct. Enforcing strict internal controls, limiting access, and documenting data flows  per internal audit methodologies is key to maintaining confidentiality.$q$, $q$ถูกต้อง. การบังคับใช้การควบคุมภายในที่เข้มงวด การจำกัดการเข้าถึง และการบันทึกกระแสข้อมูลตามวิธีการตรวจสอบภายในเป็นกุญแจสำคัญในการรักษาความลับ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10325', '2026', 1, 'B.6.c', $q$When collecting financial data from various sources during an  audit engagement, which practice best reflects respect for  privacy and ownership of information?$q$, $q$เมื่อรวบรวมข้อมูลทางการเงินจากแหล่งต่างๆ ในระหว่างงานตรวจสอบ แนวทางปฏิบัติใดสะท้อนถึงความเคารพต่อความเป็นส่วนตัวและความเป็นเจ้าของข้อมูลได้ดีที่สุด$q$, $q$["Combining data from multiple sources into one central file to promote audit efficiency.", "Verifying that all data is obtained and stored in accordance with relevant laws and organizational policies that safeguard sensitive information.", "Requesting data from departments be emailed directly to the engagement supervisor.", "Accepting all financial data provided, if not indicated whether associated with privacy guidelines."]$q$::jsonb, $q$["การรวมข้อมูลจากหลายแหล่งเป็นไฟล์กลางเดียวเพื่อส่งเสริมประสิทธิภาพการตรวจสอบ", "การตรวจสอบว่าข้อมูลทั้งหมดได้รับและจัดเก็บตามกฎหมายที่เกี่ยวข้องและนโยบายองค์กรที่ปกป้องข้อมูลที่ละเอียดอ่อน", "การร้องขอข้อมูลจากแผนกต่างๆ จะถูกส่งทางอีเมลโดยตรงไปยังหัวหน้างานการมีส่วนร่วม", "ยอมรับข้อมูลทางการเงินทั้งหมดที่ให้ไว้ หากไม่ได้ระบุว่าเกี่ยวข้องกับหลักเกณฑ์ความเป็นส่วนตัวหรือไม่"]$q$::jsonb, 1, $q$Correct. Ensuring data collection complies with legal and policy requirements safeguards  the privacy and ownership of sensitive financial information.$q$, $q$ถูกต้อง. การตรวจสอบให้แน่ใจว่าการรวบรวมข้อมูลเป็นไปตามข้อกำหนดทางกฎหมายและนโยบายจะปกป้องความเป็นส่วนตัวและความเป็นเจ้าของข้อมูลทางการเงินที่ละเอียดอ่อน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10326', '2026', 1, 'B.6.c', $q$When drafting an audit report that includes sensitive operational  data, which practice best ensures appropriate use and  confidentiality?$q$, $q$เมื่อร่างรายงานการตรวจสอบที่มีข้อมูลการปฏิบัติงานที่ละเอียดอ่อน แนวทางปฏิบัติใดดีที่สุดที่จะรับประกันการใช้งานที่เหมาะสมและการรักษาความลับ$q$, $q$["Distributing the draft report to management of the activity under review for comments before finalizing.", "Including sensitive data in the report to provide transparency to management.", "Clearly marking confidential sections, redacting sensitive details, and distributing the report only to authorized recipients.", "Publishing the report on an standard internal share drive."]$q$::jsonb, $q$["จัดส่งร่างรายงานให้ฝ่ายบริหารของกิจกรรมที่อยู่ระหว่างการตรวจสอบแสดงความคิดเห็นก่อนสรุปผล", "รวมถึงข้อมูลที่ละเอียดอ่อนในรายงานเพื่อให้เกิดความโปร่งใสแก่ฝ่ายบริหาร", "ทำเครื่องหมายส่วนที่เป็นความลับอย่างชัดเจน แก้ไขรายละเอียดที่ละเอียดอ่อน และแจกจ่ายรายงานเฉพาะผู้รับที่ได้รับอนุญาตเท่านั้น", "การเผยแพร่รายงานบนไดรฟ์แชร์ภายในมาตรฐาน"]$q$::jsonb, 2, $q$Correct. Clearly marking and redacting sensitive sections, along with controlled  distribution, maintains confidentiality and respects data ownership.$q$, $q$ถูกต้อง. การทำเครื่องหมายและการแก้ไขส่วนที่ละเอียดอ่อนอย่างชัดเจน พร้อมด้วยการควบคุมการเผยแพร่ จะรักษาความลับและเคารพความเป็นเจ้าของข้อมูล$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10327', '2026', 1, 'B.6.d', $q$During digital communications in an audit engagement, which  technique best safeguards sensitive information?$q$, $q$ในระหว่างการสื่อสารแบบดิจิทัลในงานตรวจสอบ เทคนิคใดจะปกป้องข้อมูลที่ละเอียดอ่อนได้ดีที่สุด$q$, $q$["Using standard email services combined with secure file attachments and regular password updates.", "Employing encrypted messaging applications and secure video conferencing with stringent access controls throughout the discussion.", "Utilizing proprietary communication platforms with enhanced security features and monitored access logs during audit discussions.", "Utilizing digital tools with periodic security checks with basic encryption features during discussions."]$q$::jsonb, $q$["การใช้บริการอีเมลมาตรฐานรวมกับไฟล์แนบที่ปลอดภัยและการอัปเดตรหัสผ่านเป็นประจำ", "การใช้แอปพลิเคชันการรับส่งข้อความที่เข้ารหัสและการประชุมทางวิดีโอที่ปลอดภัยพร้อมการควบคุมการเข้าถึงที่เข้มงวดตลอดการสนทนา", "การใช้แพลตฟอร์มการสื่อสารที่เป็นกรรมสิทธิ์พร้อมคุณสมบัติความปลอดภัยที่ได้รับการปรับปรุงและบันทึกการเข้าถึงที่ได้รับการตรวจสอบในระหว่างการอภิปรายการตรวจสอบ", "การใช้เครื่องมือดิจิทัลพร้อมการตรวจสอบความปลอดภัยเป็นระยะพร้อมคุณสมบัติการเข้ารหัสพื้นฐานระหว่างการสนทนา"]$q$::jsonb, 1, $q$Correct. Encrypted messaging and secure video conferencing with strict access controls  provide the highest level of protection for sensitive communications.$q$, $q$ถูกต้อง. การส่งข้อความที่เข้ารหัสและการประชุมทางวิดีโอที่ปลอดภัยพร้อมการควบคุมการเข้าถึงที่เข้มงวดมอบการปกป้องระดับสูงสุดสำหรับการสื่อสารที่ละเอียดอ่อน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10328', '2026', 1, 'C.1.a', $q$How do the board, senior management, and the internal audit  function collectively contribute to robust organizational  governance?$q$, $q$คณะกรรมการ ผู้บริหารระดับสูง และหน่วยงานตรวจสอบภายในมีส่วนร่วมในการกำกับดูแลองค์กรที่แข็งแกร่งอย่างไร$q$, $q$["The board approves strategic policies, senior management executes operational plans, and internal auditing independently assesses risk management and control effectiveness.", "The board and senior management jointly manage operations while internal auditing focuses on compliance monitoring.", "The board directs daily management, while senior management and internal auditing share responsibilities for operational execution.", "The board oversees financial planning, senior management manages risk assessments, and the internal audit function performs routine evaluations."]$q$::jsonb, $q$["คณะกรรมการอนุมัตินโยบายเชิงกลยุทธ์ ผู้บริหารระดับสูงดำเนินการตามแผนการปฏิบัติงาน และการตรวจสอบภายในประเมินการบริหารความเสี่ยงและประสิทธิผลการควบคุมอย่างเป็นอิสระ", "คณะกรรมการและผู้บริหารระดับสูงร่วมกันบริหารจัดการการปฏิบัติงาน ในขณะที่การตรวจสอบภายในมุ่งเน้นไปที่การติดตามการปฏิบัติตามกฎระเบียบ", "คณะกรรมการกำกับดูแลฝ่ายบริหารรายวัน ในขณะที่ฝ่ายบริหารระดับสูงและฝ่ายตรวจสอบภายในแบ่งหน้าที่รับผิดชอบในการปฏิบัติงาน", "คณะกรรมการกำกับดูแลการวางแผนทางการเงิน ผู้บริหารระดับสูงจัดการการประเมินความเสี่ยง และหน่วยงานตรวจสอบภายในทำการประเมินตามปกติ"]$q$::jsonb, 0, $q$Correct. Robust governance is achieved when the board provides strategic oversight,  senior management implements policies, and the internal audit function offers  independent assurance.$q$, $q$ถูกต้อง. การกำกับดูแลที่แข็งแกร่งจะเกิดขึ้นได้ก็ต่อเมื่อคณะกรรมการจัดให้มีการกำกับดูแลเชิงกลยุทธ์ ฝ่ายบริหารระดับสูงนำนโยบายไปใช้ และหน่วยงานตรวจสอบภายในให้การรับรองที่เป็นอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10329', '2026', 1, 'C.1.b', $q$Which framework is most commonly used to structure roles and  responsibilities in organizational governance?$q$, $q$กรอบการทำงานใดที่ใช้กันมากที่สุดในการจัดโครงสร้างบทบาทและความรับผิดชอบในการกำกับดูแลองค์กร?$q$, $q$["The flat organization model, which streamlines decision- making and increases collaboration.", "The three lines framework, which clearly delineates responsibilities among the board, management, and independent assurance.", "The matrix structure, which distributes responsibilities horizontally across management and internal auditing.", "The centralized control model, which consolidates decision‑making among leadership."]$q$::jsonb, $q$["รูปแบบองค์กรแบบเรียบซึ่งเพิ่มความคล่องตัวในการตัดสินใจและเพิ่มการทำงานร่วมกัน", "กรอบ 3 บรรทัด ซึ่งแบ่งแยกความรับผิดชอบระหว่างคณะกรรมการ ฝ่ายบริหาร และฝ่ายประกันอิสระอย่างชัดเจน", "โครงสร้างเมทริกซ์ซึ่งกระจายความรับผิดชอบในแนวนอนระหว่างฝ่ายบริหารและการตรวจสอบภายใน", "รูปแบบการควบคุมแบบรวมศูนย์ ซึ่งรวบรวมการตัดสินใจของผู้นำเข้าด้วยกัน"]$q$::jsonb, 1, $q$Correct. The three lines of defense framework is widely used because it clearly separates  governance roles and responsibilities.$q$, $q$ถูกต้อง. กรอบการป้องกันสามบรรทัดมีการใช้กันอย่างแพร่หลายเนื่องจากแยกบทบาทและความรับผิดชอบด้านการกำกับดูแลอย่างชัดเจน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10330', '2026', 1, 'C.2.a', $q$In what way does a robust organizational culture impact the  overall control environment and risk management processes?$q$, $q$วัฒนธรรมองค์กรที่แข็งแกร่งส่งผลกระทบต่อสภาพแวดล้อมการควบคุมโดยรวมและกระบวนการบริหารความเสี่ยงในทางใด$q$, $q$["A robust culture mainly improves public relations and employee satisfaction without significantly influencing internal controls.", "A robust culture, characterized by strong ethical values and accountability, promotes effective implementation and monitoring of internal controls and risk management practices.", "A robust culture emphasizes innovation and operational speed, with limited impact on formal control systems.", "A robust culture drives competitive strategy but is less influential in shaping the internal control environment."]$q$::jsonb, $q$["วัฒนธรรมที่แข็งแกร่งส่วนใหญ่จะปรับปรุงการประชาสัมพันธ์และความพึงพอใจของพนักงาน โดยไม่ส่งผลกระทบอย่างมีนัยสำคัญต่อการควบคุมภายใน", "วัฒนธรรมที่แข็งแกร่งซึ่งโดดเด่นด้วยค่านิยมทางจริยธรรมและความรับผิดชอบที่แข็งแกร่ง ส่งเสริมการดำเนินการและการติดตามการควบคุมภายในและแนวทางปฏิบัติในการบริหารความเสี่ยงอย่างมีประสิทธิผล", "วัฒนธรรมที่แข็งแกร่งเน้นที่นวัตกรรมและความรวดเร็วในการปฏิบัติงาน โดยมีผลกระทบอย่างจำกัดต่อระบบควบคุมอย่างเป็นทางการ", "วัฒนธรรมที่แข็งแกร่งขับเคลื่อนกลยุทธ์การแข่งขัน แต่มีอิทธิพลน้อยกว่าในการกำหนดสภาพแวดล้อมการควบคุมภายใน"]$q$::jsonb, 1, $q$Correct. A robust culture underpins internal controls by promoting ethical behavior,  accountability, and effective risk management throughout the organization.$q$, $q$ถูกต้อง. วัฒนธรรมที่แข็งแกร่งเป็นรากฐานของการควบคุมภายในโดยการส่งเสริมพฤติกรรมที่มีจริยธรรม ความรับผิดชอบ และการบริหารความเสี่ยงที่มีประสิทธิผลทั่วทั้งองค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10331', '2026', 1, 'C.2.c', $q$Which statement best describes the positive impact of  decision‑making processes on an organization’s governance,  risk management, and control systems?$q$, $q$ข้อความใดอธิบายผลกระทบเชิงบวกของกระบวนการตัดสินใจที่มีต่อการกำกับดูแล การบริหารความเสี่ยง และระบบควบคุมขององค์กรได้ดีที่สุด$q$, $q$["Centralized decision‑making relying on top management input may promote faster decision making.", "Inclusive decision‑making that uses diverse input and clear criteria strengthens governance, risk management, and controls.", "Rapid decision‑making focused on short‑term results can weaken risk management.", "Rigid decision‑making that excludes stakeholder input may produce ineffective results."]$q$::jsonb, $q$["การตัดสินใจแบบรวมศูนย์โดยอาศัยข้อมูลจากผู้บริหารระดับสูงอาจส่งเสริมการตัดสินใจที่รวดเร็วยิ่งขึ้น", "การตัดสินใจแบบครอบคลุมซึ่งใช้ข้อมูลที่หลากหลายและเกณฑ์ที่ชัดเจนจะเสริมสร้างการกำกับดูแล การบริหารความเสี่ยง และการควบคุม", "การตัดสินใจอย่างรวดเร็วโดยเน้นไปที่ผลลัพธ์ในระยะสั้นอาจทำให้การบริหารความเสี่ยงอ่อนแอลง", "การตัดสินใจที่เข้มงวดซึ่งไม่รวมข้อมูลจากผู้มีส่วนได้ส่วนเสียอาจให้ผลลัพธ์ที่ไม่มีประสิทธิภาพ"]$q$::jsonb, 1, $q$Correct. Inclusive decision‑making enhances governance by incorporating diverse  perspectives and clear criteria that strengthen risk management and controls.$q$, $q$ถูกต้อง. การตัดสินใจแบบครอบคลุมช่วยเพิ่มการกำกับดูแลโดยผสมผสานมุมมองที่หลากหลายและเกณฑ์ที่ชัดเจนซึ่งเสริมสร้างการจัดการและการควบคุมความเสี่ยง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10332', '2026', 1, 'C.2.c', $q$How does the decision‑making process improve individual  engagement risks and the robustness of control measures within  an organization?$q$, $q$กระบวนการตัดสินใจปรับปรุงความเสี่ยงในการมีส่วนร่วมของแต่ละบุคคลและความเข้มแข็งของมาตรการควบคุมภายในองค์กรได้อย่างไร$q$, $q$["Centralized decision‑making with limited review can produce inconsistent risk assessments and suboptimal controls.", "Focusing mainly on operational efficiency may result in incomplete risk assessments and weaker control measures.", "Relying on historical trends without current input can lead to outdated risk controls and increased engagement risks.", "A process that emphasizes thorough review and diverse stakeholder input minimizes engagement risks and enhances control robustness."]$q$::jsonb, $q$["การตัดสินใจแบบรวมศูนย์พร้อมการตรวจสอบอย่างจำกัดอาจทำให้เกิดการประเมินความเสี่ยงที่ไม่สอดคล้องกันและการควบคุมที่ต่ำกว่ามาตรฐาน", "การมุ่งเน้นไปที่ประสิทธิภาพการดำเนินงานเป็นหลักอาจส่งผลให้การประเมินความเสี่ยงไม่สมบูรณ์และมาตรการควบคุมที่อ่อนแอลง", "การใช้แนวโน้มในอดีตโดยไม่มีข้อมูลปัจจุบันอาจนำไปสู่การควบคุมความเสี่ยงที่ล้าสมัยและความเสี่ยงในการมีส่วนร่วมที่เพิ่มขึ้น", "กระบวนการที่เน้นการตรวจสอบอย่างละเอียดและข้อมูลจากผู้มีส่วนได้ส่วนเสียที่หลากหลายจะช่วยลดความเสี่ยงในการมีส่วนร่วมและเพิ่มความแข็งแกร่งในการควบคุม"]$q$::jsonb, 3, $q$Correct. Thorough decision‑making with diverse input is essential to minimizing  engagement risks and strengthening internal controls.$q$, $q$ถูกต้อง. การตัดสินใจอย่างละเอียดด้วยข้อมูลที่หลากหลายถือเป็นสิ่งสำคัญในการลดความเสี่ยงในการปฏิบัติงานและเสริมสร้างการควบคุมภายในให้แข็งแกร่งขึ้น$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10333', '2026', 1, 'C.3.a', $q$Which option best explains the role of ethical, legal, and  compliance requirements in organizational governance?$q$, $q$ตัวเลือกใดอธิบายบทบาทของข้อกำหนดด้านจริยธรรม กฎหมาย และการปฏิบัติตามข้อกำหนดในการกำกับดูแลองค์กรได้ดีที่สุด$q$, $q$["They primarily focus on financial targets and operational efficiency without emphasizing ethical conduct.", "They serve only as a reference for external audit engagements and have little impact on internal governance practices.", "They form a framework that guides decision‑making, ensures accountability, and underpins the design of internal controls and risk management processes.", "They act as optional guidelines that managers may choose to follow based on situational factors."]$q$::jsonb, $q$["พวกเขามุ่งเน้นไปที่เป้าหมายทางการเงินและประสิทธิภาพการดำเนินงานเป็นหลักโดยไม่เน้นหลักจริยธรรม", "สิ่งเหล่านี้ทำหน้าที่เป็นข้อมูลอ้างอิงสำหรับงานตรวจสอบภายนอกเท่านั้น และมีผลกระทบเพียงเล็กน้อยต่อการกำกับดูแลภายใน", "โดยสร้างกรอบการทำงานที่เป็นแนวทางในการตัดสินใจ รับประกันความรับผิดชอบ และสนับสนุนการออกแบบการควบคุมภายในและกระบวนการบริหารความเสี่ยง", "ทำหน้าที่เป็นแนวทางเสริมที่ผู้จัดการอาจเลือกที่จะปฏิบัติตามโดยพิจารณาจากปัจจัยสถานการณ์"]$q$::jsonb, 2, $q$Correct. These requirements create a framework that guides decisions and ensures that  governance and control processes are aligned with legal and ethical standards.$q$, $q$ถูกต้อง. ข้อกำหนดเหล่านี้สร้างกรอบการทำงานที่เป็นแนวทางในการตัดสินใจและรับรองว่ากระบวนการกำกับดูแลและการควบคุมสอดคล้องกับมาตรฐานทางกฎหมายและจริยธรรม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10334', '2026', 1, 'C.3.a', $q$How do ethical, legal, and compliance requirements influence an  organization's risk management process?$q$, $q$ข้อกำหนดด้านจริยธรรม กฎหมาย และการปฏิบัติตามกฎระเบียบมีอิทธิพลต่อกระบวนการบริหารความเสี่ยงขององค์กรอย่างไร$q$, $q$["They affect risk management in highly regulated industries and not in general business operations.", "They serve mainly as theoretical guidelines with minimal practical impact on day‑to‑day risk management.", "They provide the foundational framework for identifying, evaluating, and mitigating risks in a structured and consistent manner.", "They primarily focus on compliance and have little influence on the overall risk assessment process."]$q$::jsonb, $q$["สิ่งเหล่านี้ส่งผลกระทบต่อการบริหารความเสี่ยงในอุตสาหกรรมที่มีการควบคุมอย่างเข้มงวด ไม่ใช่ในการดำเนินธุรกิจทั่วไป", "โดยส่วนใหญ่จะทำหน้าที่เป็นแนวทางทางทฤษฎีโดยมีผลกระทบในทางปฏิบัติน้อยที่สุดต่อการบริหารความเสี่ยงในแต่ละวัน", "โดยจัดทำกรอบการทำงานพื้นฐานสำหรับการระบุ การประเมิน และการลดความเสี่ยงในลักษณะที่มีโครงสร้างและสอดคล้องกัน", "พวกเขามุ่งเน้นไปที่การปฏิบัติตามกฎระเบียบเป็นหลักและมีอิทธิพลเพียงเล็กน้อยต่อกระบวนการประเมินความเสี่ยงโดยรวม"]$q$::jsonb, 2, $q$Correct. These requirements underpin a structured risk management process by guiding  risk identification and mitigation strategies.$q$, $q$ถูกต้อง. ข้อกำหนดเหล่านี้สนับสนุนกระบวนการบริหารความเสี่ยงที่มีโครงสร้างโดยการชี้แนะกลยุทธ์การระบุความเสี่ยงและการลดผลกระทบ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10335', '2026', 1, 'C.3.b', $q$Which factor best illustrates the influence of organizational  decision‑making on its ethical framework?$q$, $q$ปัจจัยใดที่แสดงให้เห็นถึงอิทธิพลของการตัดสินใจขององค์กรที่มีต่อกรอบจริยธรรมได้ดีที่สุด$q$, $q$["Quick decision‑making focused on short‑term gains can lead to compromised ethical standards and diminished control quality.", "Centralized decision‑making that relies solely on top management input tends to limit openness and may weaken ethical oversight.", "Inclusive and transparent decision‑making that involves diverse stakeholder input strengthens ethical governance and enhances internal controls.", "Rigid decision‑making processes that exclude external input often result in standardized controls with limited adaptability."]$q$::jsonb, $q$["การตัดสินใจอย่างรวดเร็วโดยเน้นไปที่ผลกำไรในระยะสั้นสามารถนำไปสู่มาตรฐานทางจริยธรรมที่ถูกละเมิดและคุณภาพการควบคุมลดลง", "การตัดสินใจแบบรวมศูนย์ซึ่งอาศัยข้อมูลจากผู้บริหารระดับสูงเพียงอย่างเดียวมีแนวโน้มที่จะจำกัดการเปิดกว้างและอาจบั่นทอนการกำกับดูแลด้านจริยธรรม", "การตัดสินใจที่ครอบคลุมและโปร่งใสซึ่งเกี่ยวข้องกับความคิดเห็นของผู้มีส่วนได้ส่วนเสียที่หลากหลายจะเสริมสร้างการกำกับดูแลด้านจริยธรรมและปรับปรุงการควบคุมภายใน", "กระบวนการตัดสินใจที่เข้มงวดซึ่งไม่รวมอินพุตจากภายนอก มักส่งผลให้มีการควบคุมที่เป็นมาตรฐานและมีความสามารถในการปรับตัวที่จำกัด"]$q$::jsonb, 2, $q$Correct. Inclusive and transparent decision‑making fosters robust ethical governance by  incorporating diverse perspectives and reinforcing control effectiveness.$q$, $q$ถูกต้อง. การตัดสินใจที่ครอบคลุมและโปร่งใสส่งเสริมการกำกับดูแลด้านจริยธรรมที่แข็งแกร่งโดยการผสมผสานมุมมองที่หลากหลายและเสริมสร้างประสิทธิผลในการควบคุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10336', '2026', 1, 'C.4.b', $q$Which concept best illustrates the difference between inherent  risk and residual risk in risk management?$q$, $q$แนวคิดใดที่แสดงให้เห็นถึงความแตกต่างระหว่างความเสี่ยงโดยธรรมชาติและความเสี่ยงคงเหลือในการบริหารความเสี่ยงได้ดีที่สุด$q$, $q$["Inherent risk is the natural risk level present without mitigation, while residual risk is the risk remaining after controls are applied.", "Inherent risk is always the highest possible risk, and residual risk is a fraction of that risk estimated by historical trends.", "Inherent risk reflects potential exposures irrespective of controls, and residual risk is calculated by subtracting control efficiency from inherent risk.", "Inherent risk is determined independently of internal controls, and residual risk is defined solely by external auditors."]$q$::jsonb, $q$["ความเสี่ยงโดยธรรมชาติคือระดับความเสี่ยงตามธรรมชาติที่มีอยู่โดยไม่มีการบรรเทา ในขณะที่ความเสี่ยงที่เหลือคือความเสี่ยงที่เหลืออยู่หลังจากใช้การควบคุมแล้ว", "ความเสี่ยงโดยธรรมชาติคือความเสี่ยงสูงสุดที่เป็นไปได้เสมอ และความเสี่ยงที่เหลืออยู่คือเศษเสี้ยวของความเสี่ยงที่ประเมินโดยแนวโน้มในอดีต", "ความเสี่ยงโดยธรรมชาติสะท้อนถึงความเสี่ยงที่อาจเกิดขึ้นโดยไม่คำนึงถึงการควบคุม และความเสี่ยงที่เหลืออยู่คำนวณโดยการลบประสิทธิภาพการควบคุมออกจากความเสี่ยงโดยธรรมชาติ", "ความเสี่ยงโดยธรรมชาติจะถูกกำหนดโดยอิสระจากการควบคุมภายใน และความเสี่ยงที่เหลือจะถูกกำหนดโดยผู้ตรวจสอบภายนอกแต่เพียงผู้เดียว"]$q$::jsonb, 0, $q$Correct. Inherent risk is the unmitigated risk present before controls, and residual risk is  the remaining risk after mitigation measures are implemented.$q$, $q$ถูกต้อง. ความเสี่ยงโดยธรรมชาติคือความเสี่ยงที่ไม่ได้รับการบรรเทาซึ่งปรากฏอยู่ก่อนการควบคุม และความเสี่ยงที่เหลืออยู่คือความเสี่ยงที่เหลืออยู่หลังจากใช้มาตรการบรรเทาผลกระทบแล้ว$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10337', '2026', 1, 'C.5.a', $q$How is risk management aligned with organizational objectives?$q$, $q$การบริหารความเสี่ยงสอดคล้องกับวัตถุประสงค์ขององค์กรอย่างไร$q$, $q$["Risk management operates independently of strategic goals by addressing risks only when they are deemed critical.", "Risk management aligns risk identification and mitigation with strategic goals to promote sustained performance and resilience.", "Risk management focuses on short-term financial results and disregards alignment with long-term objectives.", "Risk management is applied in isolation from organizational objectives."]$q$::jsonb, $q$["การบริหารความเสี่ยงดำเนินการอย่างเป็นอิสระจากเป้าหมายเชิงกลยุทธ์โดยจัดการกับความเสี่ยงเมื่อถือว่ามีความสำคัญเท่านั้น", "การจัดการความเสี่ยงทำให้การระบุความเสี่ยงและการลดความเสี่ยงสอดคล้องกับเป้าหมายเชิงกลยุทธ์เพื่อส่งเสริมประสิทธิภาพและความยืดหยุ่นที่ยั่งยืน", "การบริหารความเสี่ยงมุ่งเน้นไปที่ผลลัพธ์ทางการเงินในระยะสั้นและไม่คำนึงถึงความสอดคล้องกับวัตถุประสงค์ระยะยาว", "การบริหารความเสี่ยงถูกนำไปใช้แยกจากวัตถุประสงค์ขององค์กร"]$q$::jsonb, 1, $q$Correct. Effective risk management ensures that risks are managed in a way that  supports the organization’s strategic goals and resilience.$q$, $q$ถูกต้อง. การบริหารความเสี่ยงที่มีประสิทธิผลช่วยให้แน่ใจว่าความเสี่ยงได้รับการจัดการในลักษณะที่สนับสนุนเป้าหมายเชิงกลยุทธ์และความยืดหยุ่นขององค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10338', '2026', 1, 'C.5.a', $q$What is the primary objective of risk management within an  organization?$q$, $q$วัตถุประสงค์หลักของการบริหารความเสี่ยงภายในองค์กรคืออะไร?$q$, $q$["To respond to risks after they have materialized.", "To eliminate all risks.", "To focus on minimizing financial losses without considering potential benefits.", "To reduce potential adverse impacts while leveraging opportunities to achieve strategic goals."]$q$::jsonb, $q$["เพื่อตอบสนองต่อความเสี่ยงภายหลังที่ได้เกิดขึ้นจริงแล้ว", "เพื่อกำจัดความเสี่ยงทั้งหมด", "มุ่งเน้นไปที่การลดความสูญเสียทางการเงินโดยไม่คำนึงถึงผลประโยชน์ที่อาจเกิดขึ้น", "เพื่อลดผลกระทบด้านลบที่อาจเกิดขึ้นพร้อมทั้งใช้ประโยชน์จากโอกาสในการบรรลุเป้าหมายเชิงกลยุทธ์"]$q$::jsonb, 3, $q$Correct. Risk management aims to minimize negative impacts and capture opportunities  that support the organization's strategic goals.$q$, $q$ถูกต้อง. การบริหารความเสี่ยงมีจุดมุ่งหมายเพื่อลดผลกระทบด้านลบและคว้าโอกาสที่สนับสนุนเป้าหมายเชิงกลยุทธ์ขององค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10339', '2026', 1, 'C.5.b', $q$Which factor best illustrates the role of risk tolerance in an  organization’s risk management process?$q$, $q$ปัจจัยใดที่แสดงให้เห็นถึงบทบาทของการยอมรับความเสี่ยงในกระบวนการบริหารความเสี่ยงขององค์กรได้ดีที่สุด$q$, $q$["Risk tolerance provides measurable limits that guide decision‑making by specifying acceptable deviations from the established risk appetite.", "Risk tolerance serves as a fixed numerical value regardless of internal risk assessments.", "Risk tolerance is a subjective measure used primarily for qualitative risk evaluations without specific benchmarks.", "Risk tolerance defines external risk exposures without linking them to the organization’s strategic risk levels."]$q$::jsonb, $q$["การยอมรับความเสี่ยงให้ขีดจำกัดที่วัดได้เพื่อเป็นแนวทางในการตัดสินใจโดยระบุความเบี่ยงเบนที่ยอมรับได้จากระดับความเสี่ยงที่ยอมรับได้", "การยอมรับความเสี่ยงทำหน้าที่เป็นค่าตัวเลขคงที่ โดยไม่คำนึงถึงการประเมินความเสี่ยงภายใน", "การยอมรับความเสี่ยงเป็นการวัดเชิงอัตนัยที่ใช้เป็นหลักสำหรับการประเมินความเสี่ยงเชิงคุณภาพโดยไม่มีเกณฑ์มาตรฐานเฉพาะ", "การยอมรับความเสี่ยงจะกำหนดความเสี่ยงภายนอกโดยไม่เชื่อมโยงกับระดับความเสี่ยงเชิงกลยุทธ์ขององค์กร"]$q$::jsonb, 0, $q$Correct. Risk tolerance sets quantifiable limits that help guide decision-making by  indicating acceptable variations from the risk appetite.$q$, $q$ถูกต้อง. การยอมรับความเสี่ยงจะกำหนดขีดจำกัดเชิงปริมาณที่ช่วยเป็นแนวทางในการตัดสินใจโดยระบุความแปรผันที่ยอมรับได้จากระดับความเสี่ยงที่ยอมรับได้$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10340', '2026', 1, 'C.5.b', $q$How does a clearly defined risk appetite influence an  organization’s decision‑making processes?$q$, $q$ความเสี่ยงที่ยอมรับได้ที่กำหนดไว้อย่างชัดเจนมีอิทธิพลต่อกระบวนการตัดสินใจขององค์กรอย่างไร$q$, $q$["A clear risk appetite sets fixed thresholds for risk without allowing adjustments for evolving market conditions.", "A clear risk appetite serves as an operational checklist without influencing higher- level strategic choices.", "A clear risk appetite is used for reporting purposes and does not impact internal decision‑making.", "A clear risk appetite guides strategic decisions by establishing the overall level of risk that can be accepted in pursuit of objectives."]$q$::jsonb, $q$["การยอมรับความเสี่ยงที่ชัดเจนจะกำหนดเกณฑ์คงที่สำหรับความเสี่ยงโดยไม่อนุญาตให้มีการปรับเปลี่ยนสภาวะตลาดที่เปลี่ยนแปลงไป", "การยอมรับความเสี่ยงที่ชัดเจนทำหน้าที่เป็นรายการตรวจสอบการปฏิบัติงาน โดยไม่ส่งผลต่อทางเลือกเชิงกลยุทธ์ในระดับที่สูงกว่า", "การยอมรับความเสี่ยงที่ชัดเจนใช้เพื่อวัตถุประสงค์ในการรายงาน และไม่ส่งผลกระทบต่อการตัดสินใจภายใน", "การยอมรับความเสี่ยงที่ชัดเจนจะเป็นแนวทางในการตัดสินใจเชิงกลยุทธ์โดยการกำหนดระดับความเสี่ยงโดยรวมที่สามารถยอมรับได้ในการบรรลุวัตถุประสงค์"]$q$::jsonb, 3, $q$Correct. A well-defined risk appetite directs strategic decision-making by setting the  overall acceptable risk level for the organization.$q$, $q$ถูกต้อง. ความเสี่ยงที่ยอมรับได้ที่กำหนดไว้อย่างดีจะกำหนดทิศทางการตัดสินใจเชิงกลยุทธ์โดยการกำหนดระดับความเสี่ยงโดยรวมที่ยอมรับได้สำหรับองค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10341', '2026', 1, 'C.5.b', $q$Which approach best integrates risk appetite and risk tolerance  into an effective risk management process?$q$, $q$แนวทางใดผสมผสานการยอมรับความเสี่ยงและการยอมรับความเสี่ยงเข้ากับกระบวนการบริหารความเสี่ยงที่มีประสิทธิผลได้ดีที่สุด$q$, $q$["By emphasizing risk tolerance and using a limited risk appetite statement in decision‑making.", "By setting them independently based on historical data, without linking them to current strategic objectives.", "By aligning both with strategic goals, ensuring that overall risk exposure is managed within acceptable limits while supporting informed decisions.", "By applying them strictly as external benchmarks."]$q$::jsonb, $q$["โดยเน้นการยอมรับความเสี่ยงและใช้คำชี้แจงความเสี่ยงที่จำกัดในการตัดสินใจ", "โดยการตั้งค่าให้เป็นอิสระจากข้อมูลในอดีต โดยไม่เชื่อมโยงกับวัตถุประสงค์เชิงกลยุทธ์ในปัจจุบัน", "โดยการปรับทั้งสองอย่างให้สอดคล้องกับเป้าหมายเชิงกลยุทธ์ ทำให้มั่นใจได้ว่าความเสี่ยงโดยรวมจะได้รับการจัดการภายในขอบเขตที่ยอมรับได้ ในขณะเดียวกันก็สนับสนุนการตัดสินใจอย่างมีข้อมูล", "โดยนำมาประยุกต์เป็นเกณฑ์มาตรฐานภายนอกอย่างเคร่งครัด"]$q$::jsonb, 2, $q$Correct. Integrating both risk appetite and risk tolerance with strategic goals helps  manage risk exposure effectively and supports sound decision ‑making.$q$, $q$ถูกต้อง. การบูรณาการทั้งความเสี่ยงที่ยอมรับได้และการยอมรับความเสี่ยงเข้ากับเป้าหมายเชิงกลยุทธ์จะช่วยจัดการความเสี่ยงได้อย่างมีประสิทธิภาพและสนับสนุนการตัดสินใจที่ดี$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10342', '2026', 1, 'C.5.b', $q$How do risk appetite and risk tolerance together shape an  organization’s approach to managing risk?$q$, $q$ความเสี่ยงที่ยอมรับได้และการยอมรับความเสี่ยงร่วมกันกำหนดแนวทางการจัดการความเสี่ยงขององค์กรได้อย่างไร$q$, $q$["They operate separately, with risk appetite governing strategic decisions and risk tolerance managing operational risks independently.", "They work in tandem by setting an overall acceptable risk level and defining the specific limits within which risk exposure can vary during operations.", "They are interchangeable terms that do not distinctly influence risk management practices when applied together.", "They serve only as theoretical concepts that are rarely used to guide actual risk management decisions in practice."]$q$::jsonb, $q$["พวกเขาดำเนินงานแยกกัน โดยยอมรับความเสี่ยงที่ควบคุมการตัดสินใจเชิงกลยุทธ์และการยอมรับความเสี่ยงในการจัดการความเสี่ยงในการดำเนินงานอย่างเป็นอิสระ", "โดยทำงานควบคู่กันโดยการกำหนดระดับความเสี่ยงโดยรวมที่ยอมรับได้ และการกำหนดขีดจำกัดเฉพาะซึ่งความเสี่ยงสามารถเปลี่ยนแปลงได้ในระหว่างการปฏิบัติงาน", "เป็นคำที่ใช้แทนกันได้ซึ่งไม่มีอิทธิพลต่อแนวทางปฏิบัติในการบริหารความเสี่ยงอย่างชัดเจนเมื่อใช้ร่วมกัน", "สิ่งเหล่านี้ทำหน้าที่เป็นแนวคิดทางทฤษฎีเท่านั้นที่ไม่ค่อยได้ใช้เพื่อเป็นแนวทางในการตัดสินใจบริหารความเสี่ยงในทางปฏิบัติ"]$q$::jsonb, 1, $q$Correct. Together, risk appetite and risk tolerance define both the overall acceptable risk  level and the allowable variations, shaping effective risk management strategies.$q$, $q$ถูกต้อง. ความเสี่ยงที่ยอมรับได้และความสามารถในการยอมรับความเสี่ยงจะกำหนดทั้งระดับความเสี่ยงที่ยอมรับได้โดยรวมและความแปรผันที่อนุญาต ซึ่งกำหนดกลยุทธ์การบริหารความเสี่ยงที่มีประสิทธิผล$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10343', '2026', 1, 'C.5.c', $q$Which combined stages in the risk management cycle are  essential for establishing a baseline of risk exposure before  mitigation efforts are applied?$q$, $q$ขั้นตอนรวมใดในวงจรการบริหารความเสี่ยงที่จำเป็นสำหรับการสร้างพื้นฐานของความเสี่ยงก่อนที่จะใช้มาตรการบรรเทาผลกระทบ$q$, $q$["Risk assessment and risk review are combined to form a baseline by evaluating risks both before and after mitigation measures.", "Risk mitigation and risk monitoring are used to set the baseline by reducing risks and tracking outcomes after controls are applied.", "Risk identification and risk assessment work together to establish an initial baseline by recognizing and analyzing potential risks.", "Risk identification and risk monitoring create a baseline by listing potential risks and then tracking their occurrence over time."]$q$::jsonb, $q$["การประเมินความเสี่ยงและการทบทวนความเสี่ยงจะรวมกันเพื่อสร้างพื้นฐานโดยการประเมินความเสี่ยงทั้งก่อนและหลังมาตรการบรรเทาผลกระทบ", "การลดความเสี่ยงและการติดตามความเสี่ยงใช้เพื่อกำหนดพื้นฐานโดยการลดความเสี่ยงและการติดตามผลลัพธ์หลังจากใช้การควบคุม", "การระบุความเสี่ยงและการประเมินความเสี่ยงทำงานร่วมกันเพื่อสร้างพื้นฐานเริ่มต้นโดยการรับรู้และวิเคราะห์ความเสี่ยงที่อาจเกิดขึ้น", "การระบุความเสี่ยงและการติดตามความเสี่ยงจะสร้างพื้นฐานโดยการแสดงรายการความเสี่ยงที่อาจเกิดขึ้น จากนั้นติดตามการเกิดขึ้นเมื่อเวลาผ่านไป"]$q$::jsonb, 2, $q$Correct. Combining risk identification and assessment is essential to establishing a  baseline exposure before any mitigation strategies are implemented.$q$, $q$ถูกต้อง. การรวมการระบุความเสี่ยงและการประเมินเป็นสิ่งสำคัญในการสร้างความเสี่ยงพื้นฐานก่อนที่จะใช้กลยุทธ์การบรรเทาใดๆ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10344', '2026', 1, 'C.6.b', $q$Which statement best explains the purpose of using a risk  management framework?$q$, $q$ข้อความใดอธิบายวัตถุประสงค์ของการใช้กรอบการบริหารความเสี่ยงได้ดีที่สุด$q$, $q$["It is more useful for financial risk analysis than strategic risk management.", "It functions as a reporting mechanism for past risk events.", "It structures risk identification, evaluation, and mitigation efforts to ensure risks are managed proactively and consistently across all functions.", "It serves as a compliance tool that ensures external regulatory adherence."]$q$::jsonb, $q$["มีประโยชน์สำหรับการวิเคราะห์ความเสี่ยงทางการเงินมากกว่าการบริหารความเสี่ยงเชิงกลยุทธ์", "ทำหน้าที่เป็นกลไกในการรายงานเหตุการณ์ความเสี่ยงในอดีต", "โดยจัดโครงสร้างการระบุความเสี่ยง การประเมิน และการลดความเสี่ยงเพื่อให้แน่ใจว่าความเสี่ยงได้รับการจัดการในเชิงรุกและสม่ำเสมอในทุกสายงาน", "มันทำหน้าที่เป็นเครื่องมือในการปฏิบัติตามกฎระเบียบที่ช่วยให้มั่นใจถึงการปฏิบัติตามกฎระเบียบภายนอก"]$q$::jsonb, 2, $q$Correct. A risk management framework is designed to systematically manage risks,  supporting proactive and consistent mitigation efforts throughout the organization.$q$, $q$ถูกต้อง. กรอบการบริหารความเสี่ยงได้รับการออกแบบเพื่อจัดการความเสี่ยงอย่างเป็นระบบ สนับสนุนความพยายามในการบรรเทาผลกระทบเชิงรุกและสม่ำเสมอทั่วทั้งองค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10345', '2026', 1, 'C.6.b', $q$What is the primary benefit of integrating a risk management  framework within an organization’s operational processes?$q$, $q$ประโยชน์หลักของการบูรณาการกรอบการบริหารความเสี่ยงภายในกระบวนการดำเนินงานขององค์กรคืออะไร?$q$, $q$["It concentrates on strategic- level risks and overlooks the risks present in day‑to‑day operations.", "It mainly acts as a historical record for past incidents without influencing future operational enhancements.", "It enables proactive risk identification and management, fostering continuous improvement and aligning operations with strategic goals.", "It functions as a checklist that meets compliance requirements without facilitating a dynamic response to emerging risks."]$q$::jsonb, $q$["โดยมุ่งเน้นที่ความเสี่ยงระดับกลยุทธ์และมองข้ามความเสี่ยงที่มีอยู่ในการดำเนินงานในแต่ละวัน", "โดยส่วนใหญ่จะทำหน้าที่เป็นบันทึกทางประวัติศาสตร์สำหรับเหตุการณ์ในอดีต โดยไม่ส่งผลกระทบต่อการปรับปรุงการปฏิบัติงานในอนาคต", "ช่วยให้สามารถระบุและจัดการความเสี่ยงเชิงรุก ส่งเสริมการปรับปรุงอย่างต่อเนื่องและปรับการดำเนินงานให้สอดคล้องกับเป้าหมายเชิงกลยุทธ์", "โดยทำหน้าที่เป็นรายการตรวจสอบที่ตรงตามข้อกำหนดในการปฏิบัติตามข้อกำหนด โดยไม่อำนวยความสะดวกในการตอบสนองต่อความเสี่ยงที่เกิดขึ้นใหม่"]$q$::jsonb, 2, $q$Correct. Integration of a risk management framework supports proactive risk  management and continuous improvement by aligning operational processes with  strategic objectives.$q$, $q$ถูกต้อง. การบูรณาการกรอบการบริหารความเสี่ยงสนับสนุนการบริหารความเสี่ยงเชิงรุกและการปรับปรุงอย่างต่อเนื่องโดยทำให้กระบวนการปฏิบัติงานสอดคล้องกับวัตถุประสงค์เชิงกลยุทธ์$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10346', '2026', 1, 'C.6.b', $q$How can a risk management framework best contribute to the  alignment of organizational strategy and operational processes?$q$, $q$กรอบการบริหารความเสี่ยงสามารถช่วยปรับกลยุทธ์องค์กรและกระบวนการปฏิบัติงานได้ดีที่สุดได้อย่างไร$q$, $q$["It focuses on documenting risks and integrating them into strategic planning efforts.", "It facilitates the identification and mitigation of risks that may hinder strategic objectives, ensuring that operational processes are aligned with overall goals.", "It emphasizes quantitative risk measures instead of strategic objectives.", "It serves primarily as a regulatory reporting tool that ensures effective compliance."]$q$::jsonb, $q$["โดยมุ่งเน้นไปที่การบันทึกความเสี่ยงและบูรณาการเข้ากับความพยายามในการวางแผนเชิงกลยุทธ์", "ช่วยอำนวยความสะดวกในการระบุและการลดความเสี่ยงที่อาจขัดขวางวัตถุประสงค์เชิงกลยุทธ์ ทำให้มั่นใจได้ว่ากระบวนการปฏิบัติงานสอดคล้องกับเป้าหมายโดยรวม", "โดยเน้นมาตรการความเสี่ยงเชิงปริมาณแทนวัตถุประสงค์เชิงกลยุทธ์", "โดยทำหน้าที่เป็นเครื่องมือการรายงานตามกฎระเบียบเป็นหลักเพื่อให้มั่นใจว่ามีการปฏิบัติตามกฎระเบียบอย่างมีประสิทธิผล"]$q$::jsonb, 1, $q$Correct. A risk management framework aligns operations with strategic objectives by  identifying and mitigating risks that could impede the achievement of those goals.$q$, $q$ถูกต้อง. กรอบการบริหารความเสี่ยงปรับการดำเนินงานให้สอดคล้องกับวัตถุประสงค์เชิงกลยุทธ์โดยการระบุและลดความเสี่ยงที่อาจขัดขวางการบรรลุเป้าหมายเหล่านั้น$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10347', '2026', 1, 'C.6.b', $q$How do the components of a risk management framework work  together to best support organizational decision‑making?$q$, $q$องค์ประกอบของกรอบการบริหารความเสี่ยงทำงานร่วมกันเพื่อสนับสนุนการตัดสินใจขององค์กรได้ดีที่สุดอย่างไร$q$, $q$["They address different risk aspects and potential risk responses for management.", "They integrate risk identification, assessment, mitigation, and monitoring into a cohesive process that informs and guides strategic decisions.", "They emphasize risk documentation and risk analysis for management.", "They operate primarily as compliance tools, ensuring regulatory adherence and facilitating transparent reporting."]$q$::jsonb, $q$["กล่าวถึงประเด็นความเสี่ยงที่แตกต่างกันและการตอบสนองต่อความเสี่ยงที่อาจเกิดขึ้นสำหรับฝ่ายบริหาร", "โดยจะรวมการระบุความเสี่ยง การประเมิน การบรรเทา และการติดตามไว้ในกระบวนการที่สอดคล้องกันซึ่งจะแจ้งและเป็นแนวทางในการตัดสินใจเชิงกลยุทธ์", "พวกเขาเน้นเอกสารความเสี่ยงและการวิเคราะห์ความเสี่ยงสำหรับการจัดการ", "โดยดำเนินการเป็นเครื่องมือในการปฏิบัติตามกฎระเบียบเป็นหลัก เพื่อให้มั่นใจว่ามีการปฏิบัติตามกฎระเบียบและอำนวยความสะดวกในการรายงานที่โปร่งใส"]$q$::jsonb, 1, $q$Correct. Integrating various components of the framework into a cohesive process helps  inform and guide strategic decisions by addressing risks comprehensively.$q$, $q$ถูกต้อง. การรวมองค์ประกอบต่างๆ ของกรอบการทำงานเข้ากับกระบวนการที่สอดคล้องกันจะช่วยแจ้งและเป็นแนวทางในการตัดสินใจเชิงกลยุทธ์โดยการจัดการความเสี่ยงอย่างครอบคลุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10348', '2026', 1, 'C.7.a', $q$How do internal controls help an organization manage risk?$q$, $q$การควบคุมภายในช่วยให้องค์กรบริหารความเสี่ยงได้อย่างไร?$q$, $q$["They prevent and detect errors and fraud, thereby reducing risk and supporting the achievement of organizational objectives.", "They focus primarily on documenting previous errors for management review.", "They are primarily used to ensure accurate financial reporting.", "They act as standalone systems that record risk data for managerial review and correction."]$q$::jsonb, $q$["ป้องกันและตรวจจับข้อผิดพลาดและการฉ้อโกง ซึ่งช่วยลดความเสี่ยงและสนับสนุนการบรรลุวัตถุประสงค์ขององค์กร", "โดยมุ่งเน้นที่การบันทึกข้อผิดพลาดก่อนหน้านี้เป็นหลักเพื่อการตรวจสอบของฝ่ายบริหาร", "ส่วนใหญ่จะใช้เพื่อรับรองการรายงานทางการเงินที่ถูกต้อง", "โดยทำหน้าที่เป็นระบบสแตนด์อโลนที่บันทึกข้อมูลความเสี่ยงเพื่อการตรวจสอบและแก้ไขของฝ่ายบริหาร"]$q$::jsonb, 0, $q$Correct. Internal controls are implemented to prevent and detect issues that could impair  risk management, thus supporting overall organizational objectives.$q$, $q$ถูกต้อง. มีการนำการควบคุมภายในมาใช้เพื่อป้องกันและตรวจจับปัญหาที่อาจส่งผลกระทบต่อการบริหารความเสี่ยง ซึ่งสนับสนุนวัตถุประสงค์โดยรวมขององค์กร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10349', '2026', 1, 'C.7.a', $q$In what way do internal controls best contribute to the reliability of  financial reporting?$q$, $q$การควบคุมภายในมีส่วนสนับสนุนความน่าเชื่อถือของการรายงานทางการเงินได้ดีที่สุดในทางใด$q$, $q$["They primarily focus on the organization's strategic objectives.", "They focus on producing periodic reports for external auditors.", "They ensure accuracy and completeness in financial records by preventing errors and fraud.", "They are used to ensure regulatory compliance."]$q$::jsonb, $q$["พวกเขามุ่งเน้นไปที่วัตถุประสงค์เชิงกลยุทธ์ขององค์กรเป็นหลัก", "พวกเขามุ่งเน้นไปที่การจัดทำรายงานเป็นระยะสำหรับผู้ตรวจสอบภายนอก", "พวกเขารับประกันความถูกต้องและครบถ้วนในบันทึกทางการเงินโดยการป้องกันข้อผิดพลาดและการฉ้อโกง", "ใช้เพื่อรับรองการปฏิบัติตามกฎระเบียบ"]$q$::jsonb, 2, $q$Correct. By preventing errors and fraud, internal controls play a crucial role in ensuring  that financial reporting is accurate and complete.$q$, $q$ถูกต้อง. การป้องกันข้อผิดพลาดและการฉ้อโกง การควบคุมภายในมีบทบาทสำคัญในการทำให้แน่ใจว่าการรายงานทางการเงินมีความถูกต้องและครบถ้วน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10350', '2026', 1, 'C.7.a', $q$What is a key benefit of implementing robust internal controls in an  organization?$q$, $q$ประโยชน์หลักของการใช้การควบคุมภายในที่มีประสิทธิภาพในองค์กรคืออะไร?$q$, $q$["They allow the company to reduce oversight by external regulators by documenting performance.", "They mainly improve the organization’s public image without affecting internal processes.", "They provide assurance that assets are protected, financial information is reliable, and compliance requirements are met.", "They serve as a primary tool for comparison to competitive benchmarking."]$q$::jsonb, $q$["ช่วยให้บริษัทลดการกำกับดูแลโดยหน่วยงานกำกับดูแลภายนอกโดยการบันทึกผลการปฏิบัติงาน", "พวกเขาปรับปรุงภาพลักษณ์สาธารณะขององค์กรเป็นหลักโดยไม่ส่งผลกระทบต่อกระบวนการภายใน", "โดยให้การรับประกันว่าสินทรัพย์ได้รับการคุ้มครอง ข้อมูลทางการเงินมีความน่าเชื่อถือ และปฏิบัติตามข้อกำหนด", "พวกเขาทำหน้าที่เป็นเครื่องมือหลักในการเปรียบเทียบกับการเปรียบเทียบการแข่งขัน"]$q$::jsonb, 2, $q$Correct. Robust internal controls offer multiple benefits, including asset protection,  reliable financial reporting, and adherence to compliance standards.$q$, $q$ถูกต้อง. การควบคุมภายในที่แข็งแกร่งให้ประโยชน์หลายประการ รวมถึงการปกป้องทรัพย์สิน การรายงานทางการเงินที่เชื่อถือได้ และการยึดมั่นในมาตรฐานการปฏิบัติตามข้อกำหนด$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10351', '2026', 1, 'C.7.a', $q$How can the purpose of internal controls best be summarized in  terms of their overall benefit to an organization?$q$, $q$วัตถุประสงค์ของการควบคุมภายในสามารถสรุปได้ดีที่สุดในแง่ของผลประโยชน์โดยรวมต่อองค์กรได้อย่างไร$q$, $q$["They function as a set of informal procedures to guide managerial decision‑making.", "They serve primarily as an internal checklist for external audit preparation and regulatory compliance.", "They integrate asset protection, risk mitigation, compliance, and operational efficiency, which supports organizational objectives.", "They ensure effective compliance and assist the external auditors."]$q$::jsonb, $q$["ทำหน้าที่เป็นชุดของขั้นตอนที่ไม่เป็นทางการเพื่อเป็นแนวทางในการตัดสินใจของฝ่ายบริหาร", "โดยทำหน้าที่เป็นรายการตรวจสอบภายในสำหรับการเตรียมการตรวจสอบภายนอกและการปฏิบัติตามกฎระเบียบเป็นหลัก", "โดยผสานรวมการปกป้องทรัพย์สิน การลดความเสี่ยง การปฏิบัติตามกฎระเบียบ และประสิทธิภาพการดำเนินงาน ซึ่งสนับสนุนวัตถุประสงค์ขององค์กร", "พวกเขารับประกันการปฏิบัติตามกฎระเบียบอย่างมีประสิทธิผลและช่วยเหลือผู้ตรวจสอบภายนอก"]$q$::jsonb, 2, $q$Correct. Internal controls protect assets, mitigate risk, ensure compliance, and improve  efficiency, all of which support long‑term organizational success.$q$, $q$ถูกต้อง. การควบคุมภายในช่วยปกป้องทรัพย์สิน ลดความเสี่ยง รับประกันการปฏิบัติตามกฎระเบียบ และปรับปรุงประสิทธิภาพ ซึ่งทั้งหมดนี้สนับสนุนความสำเร็จขององค์กรในระยะยาว$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10352', '2026', 1, 'D.2.b', $q$In an audit engagement of revenue recognition processes, how  should an internal auditor assess potential fraud risks requiring  special attention?$q$, $q$ในการตรวจสอบกระบวนการรับรู้รายได้ ผู้ตรวจสอบภายในควรประเมินความเสี่ยงจากการฉ้อโกงที่อาจเกิดขึ้นซึ่งต้องได้รับการดูแลเป็นพิเศษอย่างไร$q$, $q$["By applying standard audit procedures and trend analysis-related anomalies in revenue.", "By relying only on routine testing of revenue transactions and performing analytical review procedures.", "By examining revenue recording controls, reviewing unusual transactions, and testing for misstatements to gauge fraud exposure.", "By relying upon the external auditors to have fully addressed fraud risks and interviewing key operating personnel."]$q$::jsonb, $q$["โดยใช้ขั้นตอนการตรวจสอบมาตรฐานและความผิดปกติที่เกี่ยวข้องกับการวิเคราะห์แนวโน้มในรายได้", "โดยอาศัยเพียงการทดสอบธุรกรรมรายได้เป็นประจำและดำเนินการตามขั้นตอนการตรวจสอบเชิงวิเคราะห์", "โดยการตรวจสอบการควบคุมการบันทึกรายได้ ตรวจสอบธุรกรรมที่ผิดปกติ และทดสอบการแสดงข้อมูลที่ขัดต่อข้อเท็จจริงเพื่อวัดความเสี่ยงจากการฉ้อโกง", "โดยอาศัยผู้ตรวจสอบภายนอกในการแก้ไขปัญหาความเสี่ยงจากการทุจริตและสัมภาษณ์บุคลากรหลักในการปฏิบัติงาน"]$q$::jsonb, 2, $q$Correct. Evaluating controls, unusual transactions, and misstatement testing are key to  identifying fraud risks in revenue recognition.$q$, $q$ถูกต้อง. การประเมินการควบคุม ธุรกรรมที่ผิดปกติ และการทดสอบการแสดงข้อมูลที่ขัดต่อข้อเท็จจริงเป็นกุญแจสำคัญในการระบุความเสี่ยงในการฉ้อโกงในการรับรู้รายได้$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10353', '2026', 1, 'D.2.b', $q$When assessing procurement processes, which indicators should  most prompt special fraud risk evaluation?$q$, $q$เมื่อประเมินกระบวนการจัดซื้อจัดจ้าง ตัวชี้วัดใดควรกระตุ้นให้เกิดการประเมินความเสี่ยงการฉ้อโกงเป็นพิเศษมากที่สุด$q$, $q$["When there is a lack of competitive bidding, inadequate segregation of duties, and frequent control overrides, indicating increased fraud risk.", "When procurement processes consistently do not follow policies or competitive bidding.", "When the process involves informal or sole source vendor selection.", "When historical records indicate spending fluctuations and increased procurement turnover."]$q$::jsonb, $q$["เมื่อขาดการประมูลที่แข่งขันได้ การแบ่งแยกหน้าที่ไม่เพียงพอ และการควบคุมซ้ำซ้อนบ่อยครั้ง บ่งชี้ถึงความเสี่ยงในการฉ้อโกงที่เพิ่มขึ้น", "เมื่อกระบวนการจัดซื้อจัดจ้างไม่เป็นไปตามนโยบายหรือการเสนอราคาแข่งขันกันอย่างสม่ำเสมอ", "เมื่อกระบวนการเกี่ยวข้องกับการเลือกผู้จำหน่ายที่ไม่เป็นทางการหรือจากแหล่งเดียว", "เมื่อบันทึกในอดีตบ่งชี้ถึงความผันผวนของการใช้จ่ายและการหมุนเวียนในการจัดซื้อที่เพิ่มขึ้น"]$q$::jsonb, 0, $q$Correct. The absence of competitive bidding and weak controls in procurement are clear  indicators that fraud risk may be elevated.$q$, $q$ถูกต้อง. การไม่มีการเสนอราคาแข่งขันและการควบคุมการจัดซื้อที่อ่อนแอเป็นตัวบ่งชี้ที่ชัดเจนว่าความเสี่ยงในการฉ้อโกงอาจเพิ่มขึ้น$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10354', '2026', 1, 'D.3.a', $q$Which scenario best illustrates a gap in an organization's fraud  risk management process?$q$, $q$สถานการณ์ใดแสดงให้เห็นถึงช่องว่างในกระบวนการบริหารความเสี่ยงจากการฉ้อโกงขององค์กรได้ดีที่สุด$q$, $q$["A comprehensive process that employs quantitative and qualitative measures to monitor fraud risks.", "Implementation of a strong internal control environment but no fraud risk assessment.", "A lack of integration between fraud risk assessments and the implementation of corrective controls indicates a significant gap.", "An active role by the internal audit function in overseeing fraud controls."]$q$::jsonb, $q$["กระบวนการที่ครอบคลุมซึ่งใช้มาตรการเชิงปริมาณและคุณภาพเพื่อติดตามความเสี่ยงในการฉ้อโกง", "การดำเนินการตามสภาพแวดล้อมการควบคุมภายในที่เข้มงวด แต่ไม่มีการประเมินความเสี่ยงในการทุจริต", "การขาดการบูรณาการระหว่างการประเมินความเสี่ยงจากการฉ้อโกงและการดำเนินการควบคุมแก้ไข บ่งชี้ถึงช่องว่างที่สำคัญ", "บทบาทเชิงรุกของหน่วยงานตรวจสอบภายในในการกำกับดูแลการควบคุมการฉ้อโกง"]$q$::jsonb, 2, $q$Correct. Failing to link risk assessments with corrective controls is a key gap in the fraud  risk management process.$q$, $q$ถูกต้อง. ความล้มเหลวในการเชื่อมโยงการประเมินความเสี่ยงกับการควบคุมแก้ไขถือเป็นช่องว่างสำคัญในกระบวนการบริหารความเสี่ยงจากการฉ้อโกง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10355', '2026', 1, 'D.4.a', $q$How can internal auditors best evaluate the impact of the tone at  the top on fraud risk within an organization?$q$, $q$ผู้ตรวจสอบภายในสามารถประเมินผลกระทบของน้ำเสียงที่อยู่ด้านบนต่อความเสี่ยงในการฉ้อโกงภายในองค์กรได้ดีที่สุดได้อย่างไร$q$, $q$["By assessing how senior management’s ethical behavior and communication practices influence the design and execution of fraud prevention controls.", "By measuring the quantitative outcomes of previous fraud incidents, and evaluating internal controls over cash receipts and disbursements.", "By reviewing external audit results and communications, and testing of financial controls.", "By focusing on the internal control assessments and testing cash receipts and disbursements."]$q$::jsonb, $q$["โดยการประเมินว่าพฤติกรรมทางจริยธรรมและการสื่อสารของผู้บริหารระดับสูงมีอิทธิพลต่อการออกแบบและการดำเนินการควบคุมการป้องกันการฉ้อโกงอย่างไร", "โดยการวัดผลลัพธ์เชิงปริมาณของเหตุการณ์การฉ้อโกงครั้งก่อน และประเมินการควบคุมภายในเกี่ยวกับการรับและจ่ายเงินสด", "โดยการสอบทานผลการตรวจสอบและการสื่อสารภายนอก และการทดสอบการควบคุมทางการเงิน", "โดยเน้นการประเมินการควบคุมภายในและการทดสอบการรับจ่ายเงิน"]$q$::jsonb, 0, $q$Correct. Evaluating the influence of ethical behavior and communication from senior  management provides insights into how the tone at the top strengthens fraud prevention  controls.$q$, $q$ถูกต้อง. การประเมินอิทธิพลของพฤติกรรมที่มีจริยธรรมและการสื่อสารจากผู้บริหารระดับสูงจะให้ข้อมูลเชิงลึกว่าน้ำเสียงที่อยู่ด้านบนจะเสริมสร้างการควบคุมป้องกันการฉ้อโกงได้อย่างไร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10356', '2026', 1, 'D.4.a', $q$How does senior management's tone at the top affect individual  engagement risks related to fraud?$q$, $q$น้ำเสียงของผู้บริหารระดับสูงในระดับสูงสุดส่งผลต่อความเสี่ยงในการมีส่วนร่วมของแต่ละบุคคลที่เกี่ยวข้องกับการฉ้อโกงอย่างไร$q$, $q$["It influences employee behavior by promoting ethical conduct and reducing opportunities for fraudulent activities in day‑to‑day operations.", "It primarily impacts financial reporting misstatement risk and budget monitoring.", "It helps ensure the effectiveness of the system of internal controls.", "It emphasizes strategic decision-making and the monitoring of operational budgets."]$q$::jsonb, $q$["โดยมีอิทธิพลต่อพฤติกรรมของพนักงานโดยการส่งเสริมการปฏิบัติอย่างมีจริยธรรมและลดโอกาสในการฉ้อโกงในการดำเนินงานในแต่ละวัน", "โดยส่วนใหญ่จะส่งผลกระทบต่อความเสี่ยงจากการแสดงข้อมูลที่ขัดต่อข้อเท็จจริงของการรายงานทางการเงินและการติดตามงบประมาณ", "ช่วยให้มั่นใจในประสิทธิผลของระบบการควบคุมภายใน", "เน้นการตัดสินใจเชิงกลยุทธ์และการติดตามงบประมาณการดำเนินงาน"]$q$::jsonb, 0, $q$Correct. Senior management's ethical tone influences employee behavior positively,  reducing individual engagement risks related to fraud.$q$, $q$ถูกต้อง. น้ำเสียงทางจริยธรรมของผู้บริหารระดับสูงมีอิทธิพลต่อพฤติกรรมของพนักงานในทางบวก ซึ่งช่วยลดความเสี่ยงในการมีส่วนร่วมของแต่ละบุคคลที่เกี่ยวข้องกับการฉ้อโกง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10357', '2026', 1, 'D.4.b', $q$How can segregation of duties best reduce fraud risk in inventory  management?$q$, $q$การแบ่งแยกหน้าที่จะช่วยลดความเสี่ยงจากการฉ้อโกงในการจัดการสินค้าคงคลังได้ดีที่สุดได้อย่างไร$q$, $q$["Assigning separate roles for inventory ordering, receiving, and record-keeping to ensure independent performance of transactions.", "Consolidating inventory ordering and receiving under one team and conducting periodic inventory counts to control fraud risk.", "Using an automated inventory system along with periodic inventory counts to control fraud risk.", "Centralizing inventory management in one department and conducting inventory fluctuation trend analysis by another department to control fraud risk."]$q$::jsonb, $q$["การกำหนดบทบาทแยกต่างหากสำหรับการสั่งซื้อ การรับ และการเก็บบันทึกสินค้าคงคลัง เพื่อให้มั่นใจถึงประสิทธิภาพในการทำธุรกรรมที่เป็นอิสระ", "การรวมการสั่งซื้อและรับสินค้าคงคลังไว้ภายใต้ทีมเดียว และดำเนินการนับสินค้าคงคลังเป็นระยะเพื่อควบคุมความเสี่ยงในการฉ้อโกง", "การใช้ระบบสินค้าคงคลังอัตโนมัติพร้อมกับการนับสินค้าคงคลังเป็นระยะเพื่อควบคุมความเสี่ยงจากการฉ้อโกง", "รวมศูนย์การจัดการสินค้าคงคลังในแผนกหนึ่งและดำเนินการวิเคราะห์แนวโน้มความผันผวนของสินค้าคงคลังโดยแผนกอื่นเพื่อควบคุมความเสี่ยงในการฉ้อโกง"]$q$::jsonb, 0, $q$Correct. Segregating inventory functions ensures that no single individual has complete  control, thereby reducing fraud risk.$q$, $q$ถูกต้อง. การแยกฟังก์ชันสินค้าคงคลังทำให้มั่นใจได้ว่าไม่มีบุคคลใดสามารถควบคุมได้อย่างสมบูรณ์ ซึ่งจะช่วยลดความเสี่ยงในการฉ้อโกง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10358', '2026', 1, 'D.4.b', $q$How does the principle of segregation of duties best serve as an  effective control to prevent and detect fraudulent activities?$q$, $q$หลักการแบ่งแยกหน้าที่ทำหน้าที่เป็นการควบคุมที่มีประสิทธิภาพในการป้องกันและตรวจจับกิจกรรมการฉ้อโกงได้ดีที่สุดอย่างไร$q$, $q$["By centralizing responsibilities to increase administrative efficiency and relying on periodic external reviews for fraud detection.", "By designing controls so that no individual is responsible for all aspects of a transaction, ensuring independent verification at each step.", "By automating processes to the extent that human intervention is minimized, and conducting annual internal audit engagements.", "By placing similar tasks within the same department and having the accounting department provide routine transaction monitoring."]$q$::jsonb, $q$["โดยการรวมศูนย์ความรับผิดชอบเพื่อเพิ่มประสิทธิภาพการบริหารและอาศัยการตรวจสอบจากภายนอกเป็นระยะเพื่อการตรวจจับการฉ้อโกง", "ด้วยการออกแบบการควบคุมเพื่อไม่ให้บุคคลใดต้องรับผิดชอบในทุกด้านของธุรกรรม ทำให้มั่นใจได้ถึงการตรวจสอบที่เป็นอิสระในแต่ละขั้นตอน", "โดยทำให้กระบวนการเป็นอัตโนมัติในขอบเขตที่การแทรกแซงของมนุษย์ลดลง และดำเนินการตรวจสอบภายในประจำปี", "โดยวางงานที่คล้ายกันไว้ภายในแผนกเดียวกันและมีแผนกบัญชีคอยติดตามธุรกรรมตามปกติ"]$q$::jsonb, 1, $q$Correct. Ensuring that no one person controls an entire process is a fundamental means  to prevent and detect fraud.$q$, $q$ถูกต้อง. การตรวจสอบให้แน่ใจว่าไม่มีใครควบคุมกระบวนการทั้งหมดเป็นวิธีการพื้นฐานในการป้องกันและตรวจจับการฉ้อโกง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10359', '2026', 1, 'D.4.c', $q$How do well-defined authority levels best contribute to fraud  prevention within an organization?$q$, $q$ระดับอำนาจหน้าที่ที่กำหนดไว้อย่างดีมีส่วนช่วยในการป้องกันการฉ้อโกงภายในองค์กรได้ดีที่สุดอย่างไร$q$, $q$["By allowing flexible authority that adapts to operational needs.", "By consolidating power at the top level to ensure accountability and uniform decision-making.", "By ensuring decision-making responsibilities are clearly distributed, limiting any one individual’s ability to override controls.", "By delegating approval authority to multiple operating staff to enhance efficiency."]$q$::jsonb, $q$["โดยให้อำนาจที่ยืดหยุ่นซึ่งปรับให้เข้ากับความต้องการในการปฏิบัติงาน", "ด้วยการรวมอำนาจในระดับสูงสุดเพื่อให้เกิดความรับผิดชอบและการตัดสินใจที่สม่ำเสมอ", "โดยตรวจสอบให้แน่ใจว่ามีการกระจายความรับผิดชอบในการตัดสินใจอย่างชัดเจน โดยจำกัดความสามารถของบุคคลใดบุคคลหนึ่งในการแทนที่การควบคุม", "โดยมอบหมายอำนาจอนุมัติให้กับเจ้าหน้าที่ปฏิบัติการหลายรายเพื่อเพิ่มประสิทธิภาพ"]$q$::jsonb, 2, $q$Correct. Clearly distributed authority limits any single person’s control, thereby reducing  the risk of fraudulent activities.$q$, $q$ถูกต้อง. การกระจายอำนาจอย่างชัดเจนจะจำกัดการควบคุมของบุคคลใดบุคคลหนึ่ง ซึ่งจะช่วยลดความเสี่ยงของการฉ้อโกง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10360', '2026', 1, 'D.5.a', $q$When investigating suspected fraud, what is the primary role of  the internal audit function?$q$, $q$ในการสืบสวนการฉ้อโกง หน่วยงานตรวจสอบภายในมีหน้าที่หลักอะไรบ้าง?$q$, $q$["To assist legal counsel in directly interrogating staff accused of committing fraud.", "To conduct independent investigations by gathering evidence, analyzing data, and reporting findings to management and the board.", "To rely on management inquiries to address fraud incidents and question the suspected perpetrator.", "To oversee fraud investigations by enforcing corrective actions and recommending internal disciplinary measures."]$q$::jsonb, $q$["เพื่อช่วยที่ปรึกษากฎหมายในการสอบสวนพนักงานที่ถูกกล่าวหาว่ากระทำการฉ้อโกงโดยตรง", "ดำเนินการสอบสวนโดยอิสระโดยรวบรวมหลักฐาน วิเคราะห์ข้อมูล และรายงานผลต่อฝ่ายบริหารและคณะกรรมการ", "อาศัยการสอบถามของฝ่ายบริหารเพื่อจัดการกับเหตุการณ์การฉ้อโกงและซักถามผู้ต้องสงสัย", "เพื่อกำกับดูแลการสืบสวนการฉ้อโกงโดยบังคับใช้มาตรการแก้ไขและแนะนำมาตรการทางวินัยภายใน"]$q$::jsonb, 1, $q$Correct. The internal audit function is tasked with conducting independent investigations  and reporting findings to ensure objectivity.$q$, $q$ถูกต้อง. หน่วยงานตรวจสอบภายในได้รับมอบหมายให้ดำเนินการสอบสวนอย่างอิสระและรายงานผลการตรวจสอบเพื่อให้เกิดความเที่ยงธรรม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10361', '2026', 1, 'D.5.a', $q$Which option best defines how the internal audit function  contributes to fraud investigations through evidence gathering?$q$, $q$ตัวเลือกใดกำหนดวิธีที่หน่วยงานตรวจสอบภายในมีส่วนช่วยในการสืบสวนการฉ้อโกงผ่านการรวบรวมหลักฐานได้ดีที่สุด$q$, $q$["It coordinates with external agencies to evaluate evidence and assist the authorities.", "It relies on reports prepared by the affected departments to compile evidence and questioning staff suspected of wrongdoing.", "It gathers evidence based on historical data and assists the legal department by interviewing those suspected of fraud.", "It independently collects, analyzes, and verifies evidence related to fraud, ensuring that the investigation remains unbiased."]$q$::jsonb, $q$["ประสานงานกับหน่วยงานภายนอกเพื่อประเมินหลักฐานและช่วยเหลือเจ้าหน้าที่", "โดยอาศัยรายงานที่จัดทำโดยหน่วยงานที่ได้รับผลกระทบเพื่อรวบรวมหลักฐานและซักถามเจ้าหน้าที่ที่ต้องสงสัยว่ากระทำความผิด", "รวบรวมหลักฐานตามข้อมูลในอดีตและช่วยเหลือฝ่ายกฎหมายโดยการสัมภาษณ์ผู้ต้องสงสัยว่ามีการฉ้อโกง", "รวบรวม วิเคราะห์ และตรวจสอบหลักฐานที่เกี่ยวข้องกับการฉ้อโกงอย่างเป็นอิสระ เพื่อให้มั่นใจว่าการสอบสวนยังคงเป็นกลาง"]$q$::jsonb, 3, $q$Correct. The internal audit function contributes by independently gathering and verifying  evidence, which is key to maintaining objectivity in fraud investigations.$q$, $q$ถูกต้อง. หน่วยงานตรวจสอบภายในมีส่วนร่วมในการรวบรวมและตรวจสอบหลักฐานอย่างเป็นอิสระ ซึ่งเป็นกุญแจสำคัญในการรักษาความเป็นกลางในการสืบสวนการฉ้อโกง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10362', '2026', 1, 'D.5.a', $q$In fraud investigations, how is the internal audit function expected  to maintain independence and objectivity?$q$, $q$ในการสืบสวนการฉ้อโกง หน่วยงานตรวจสอบภายในคาดหวังให้รักษาความเป็นอิสระและความเป็นกลางอย่างไร$q$, $q$["By relying on management- provided data to complete the investigation.", "By working in close collaboration with the department under review to expedite a timely resolution.", "By conducting investigations without bias, ensuring that evidence is independently verified and results are communicated impartially.", "By referring the fraud allegation to the external auditors, thereby avoiding direct involvement by internal auditing."]$q$::jsonb, $q$["โดยอาศัยข้อมูลที่ได้รับจากฝ่ายบริหารเพื่อทำการตรวจสอบให้เสร็จสิ้น", "โดยทำงานร่วมกับหน่วยงานที่อยู่ระหว่างการตรวจสอบอย่างใกล้ชิดเพื่อเร่งรัดการแก้ไขให้ทันท่วงที", "โดยดำเนินการสืบสวนโดยไม่มีอคติ เพื่อให้มั่นใจว่าหลักฐานได้รับการตรวจสอบอย่างเป็นอิสระและมีการสื่อสารผลลัพธ์อย่างเป็นกลาง", "โดยส่งข้อกล่าวหาเรื่องการฉ้อโกงไปยังผู้ตรวจสอบภายนอก เพื่อหลีกเลี่ยงไม่ให้ผู้ตรวจสอบภายในเข้าไปเกี่ยวข้องโดยตรง"]$q$::jsonb, 2, $q$Correct. Maintaining independence through unbiased evidence verification and impartial  reporting is critical for effective fraud investigations.$q$, $q$ถูกต้อง. การรักษาความเป็นอิสระผ่านการตรวจสอบหลักฐานที่เป็นกลางและการรายงานที่เป็นกลางถือเป็นสิ่งสำคัญสำหรับการสืบสวนการฉ้อโกงที่มีประสิทธิภาพ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10363', '2026', 1, 'D.5.b', $q$In the context of a fraud investigation, how should internal auditors  conduct interviews to maintain objectivity and uncover  inconsistencies?$q$, $q$ในบริบทของการสืบสวนการฉ้อโกง ผู้ตรวจสอบภายในควรสัมภาษณ์อย่างไรเพื่อรักษาความเป็นกลางและเปิดเผยความไม่สอดคล้องกัน$q$, $q$["Adopt an aggressive questioning approach to force contradictions from interviewees.", "Use neutral, non‑leading questions that encourage interviewees to explain events without bias.", "Utilize written responses to questions to gain a confession.", "Use a fixed script that directs the conversation toward the suspected violation."]$q$::jsonb, $q$["ใช้วิธีตั้งคำถามเชิงรุกเพื่อบังคับความขัดแย้งจากผู้ให้สัมภาษณ์", "ใช้คำถามที่เป็นกลางและไม่นำซึ่งสนับสนุนให้ผู้ให้สัมภาษณ์อธิบายเหตุการณ์โดยไม่มีอคติ", "ใช้การเขียนตอบคำถามเพื่อรับคำสารภาพ", "ใช้สคริปต์คงที่ซึ่งนำการสนทนาไปสู่การละเมิดที่ต้องสงสัย"]$q$::jsonb, 1, $q$Correct. Neutral, non‑leading questions help maintain objectivity and enable auditors to  identify inconsistencies in the interviewee’s account.$q$, $q$ถูกต้อง. คำถามที่เป็นกลางและไม่มีคำถามนำช่วยรักษาความเป็นกลางและทำให้ผู้ตรวจสอบสามารถระบุความไม่สอดคล้องกันในบัญชีของผู้ให้สัมภาษณ์ได้$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10364', '2026', 1, 'D.5.b', $q$How can internal auditors verify the reliability of information  obtained during fraud investigation interviews?$q$, $q$ผู้ตรวจสอบภายในสามารถตรวจสอบความน่าเชื่อถือของข้อมูลที่ได้รับระหว่างการสัมภาษณ์เพื่อสอบสวนการฉ้อโกงได้อย่างไร$q$, $q$["By cross‑checking responses with independent evidence and corroborating statements with additional data sources.", "By accepting interview responses to the extent that they align with the auditors’ expectations.", "By relying on the interview transcript to avoid the need for additional investigation.", "By using standardized questions that have proven effective in prior investigations."]$q$::jsonb, $q$["โดยการตรวจสอบคำตอบด้วยหลักฐานที่เป็นอิสระและข้อความยืนยันพร้อมแหล่งข้อมูลเพิ่มเติม", "โดยการยอมรับคำตอบการสัมภาษณ์ในขอบเขตที่สอดคล้องกับความคาดหวังของผู้ตรวจสอบบัญชี", "โดยอาศัยสำเนาการสัมภาษณ์เพื่อหลีกเลี่ยงความจำเป็นในการสอบสวนเพิ่มเติม", "โดยใช้คำถามมาตรฐานที่ได้รับการพิสูจน์แล้วว่ามีประสิทธิภาพในการสืบสวนก่อนหน้านี้"]$q$::jsonb, 0, $q$Correct. Verifying responses through cross‑checking and corroboration ensures that the  information obtained is reliable and accurate.$q$, $q$ถูกต้อง. การตรวจสอบการตอบสนองผ่านการตรวจสอบและยืนยันช่วยให้มั่นใจได้ว่าข้อมูลที่ได้รับมีความน่าเชื่อถือและถูกต้อง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10365', '2026', 1, 'D.5.b', $q$During fraud investigations, which interviewing approach best  minimizes bias while obtaining critical insights?$q$, $q$ในระหว่างการสืบสวนการฉ้อโกง วิธีการสัมภาษณ์แบบใดที่ช่วยลดอคติได้ดีที่สุดพร้อมทั้งได้รับข้อมูลเชิงลึกที่สำคัญ$q$, $q$["Conducting interviews in an informal setting to encourage relaxed, unstructured conversation.", "Using leading questions designed to confirm the internal auditor’s initial suspicions regarding the fraud.", "Following a strict, pre‑written script that leaves little room for missing anything.", "Employing a neutral tone and asking open‑ended questions to allow interviewees to share their accounts freely."]$q$::jsonb, $q$["การสัมภาษณ์ในสภาพแวดล้อมที่ไม่เป็นทางการเพื่อส่งเสริมการสนทนาที่ผ่อนคลายและไม่มีโครงสร้าง", "การใช้คำถามนำที่ออกแบบมาเพื่อยืนยันข้อสงสัยเบื้องต้นของผู้ตรวจสอบภายในเกี่ยวกับการฉ้อโกง", "เป็นไปตามสคริปต์ที่เขียนไว้ล่วงหน้าอย่างเข้มงวด ซึ่งทำให้เหลือโอกาสไม่มากที่จะพลาดสิ่งใดไป", "ใช้น้ำเสียงที่เป็นกลางและถามคำถามปลายเปิดเพื่อให้ผู้ให้สัมภาษณ์แบ่งปันเรื่องราวของตนเองได้อย่างอิสระ"]$q$::jsonb, 3, $q$Correct. A neutral tone combined with open‑ended questions minimizes bias and  encourages interviewees to provide comprehensive insights.$q$, $q$ถูกต้อง. การใช้น้ำเสียงที่เป็นกลางร่วมกับคำถามปลายเปิดจะช่วยลดอคติและส่งเสริมให้ผู้ให้สัมภาษณ์ให้ข้อมูลเชิงลึกที่ครอบคลุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10366', '2026', 1, 'D.5.b', $q$How can an internal auditor use interviewing techniques to  support fraud investigations while upholding objectivity?$q$, $q$ผู้ตรวจสอบภายในจะใช้เทคนิคการสัมภาษณ์เพื่อสนับสนุนการสืบสวนการฉ้อโกงโดยยังคงรักษาความเป็นกลางได้อย่างไร$q$, $q$["By adhering to a rigid script that limits the opportunity for the conversation to go off course.", "By allowing the conversation to flow informally without a structured interview plan, relying on spontaneity.", "By adopting a structured approach that combines open‑ended questions, thorough documentation, and independent verification of responses.", "By focusing on confirming management's suspicions to provide an efficient and effective interview."]$q$::jsonb, $q$["โดยยึดมั่นในสคริปต์ที่เข้มงวดซึ่งจำกัดโอกาสที่การสนทนาจะดำเนินไปอย่างผิดปรกติ", "โดยปล่อยให้การสนทนาดำเนินไปอย่างไม่เป็นทางการโดยไม่มีการวางแผนการสัมภาษณ์แบบมีโครงสร้างและอาศัยความเป็นธรรมชาติ", "โดยการนำแนวทางที่มีโครงสร้างมาใช้ซึ่งรวมเอาคำถามปลายเปิด เอกสารประกอบอย่างละเอียด และการตรวจสอบคำตอบที่เป็นอิสระ", "โดยเน้นการยืนยันข้อสงสัยของฝ่ายบริหารเพื่อให้การสัมภาษณ์มีประสิทธิภาพและประสิทธิผล"]$q$::jsonb, 2, $q$Correct. A structured approach that encourages detailed responses and includes  verification processes supports effective fraud investigations and maintains objectivity.$q$, $q$ถูกต้อง. แนวทางที่มีโครงสร้างซึ่งสนับสนุนการตอบสนองโดยละเอียดและรวมถึงกระบวนการตรวจสอบที่สนับสนุนการสืบสวนการฉ้อโกงที่มีประสิทธิผลและรักษาความเป็นกลาง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10367', '2026', 1, 'D.5.e', $q$How should whistleblower complaints best be integrated into  fraud risk assessments by internal auditors?$q$, $q$การร้องเรียนของผู้แจ้งเบาะแสควรบูรณาการเข้ากับการประเมินความเสี่ยงจากการฉ้อโกงโดยผู้ตรวจสอบภายในได้ดีที่สุดอย่างไร$q$, $q$["By treating whistleblower complaints as isolated events and relying upon the external auditors’ written opinion.", "By incorporating whistleblower complaints as key data points to uncover hidden fraud risks and refine risk assessments.", "By ensuring that whistleblower data is reported to the board.", "By deferring the review of whistleblower complaints unless a significant fraud event occurs."]$q$::jsonb, $q$["โดยถือว่าข้อร้องเรียนของผู้แจ้งเบาะแสเป็นเหตุการณ์เดี่ยวและอาศัยความเห็นเป็นลายลักษณ์อักษรของผู้สอบบัญชีภายนอก", "ด้วยการรวมข้อร้องเรียนของผู้แจ้งเบาะแสเป็นจุดข้อมูลสำคัญในการเปิดเผยความเสี่ยงในการฉ้อโกงที่ซ่อนอยู่ และปรับปรุงการประเมินความเสี่ยง", "โดยจัดให้มีการรายงานข้อมูลผู้แจ้งเบาะแสต่อคณะกรรมการ", "โดยเลื่อนการพิจารณาข้อร้องเรียนของผู้แจ้งเบาะแส เว้นแต่จะมีเหตุการณ์ทุจริตร้ายแรงเกิดขึ้น"]$q$::jsonb, 1, $q$Correct. Integrating whistleblower complaints enhances risk assessments by revealing  issues that might otherwise remain hidden.$q$, $q$ถูกต้อง. การบูรณาการการร้องเรียนของผู้แจ้งเบาะแสจะช่วยเพิ่มการประเมินความเสี่ยงโดยการเปิดเผยปัญหาที่อาจซ่อนเร้นอยู่$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10368', '2026', 1, 'D.5.e', $q$Which practice best supports the identification of emerging fraud  risks through coordination with fraud investigators?$q$, $q$แนวปฏิบัติใดสนับสนุนการระบุความเสี่ยงจากการฉ้อโกงที่เกิดขึ้นได้ดีที่สุดผ่านการประสานงานกับผู้ตรวจสอบการฉ้อโกง$q$, $q$["Combining insights from fraud investigations with internal risk assessments to detect emerging fraud patterns proactively.", "Conducting independent risk assessments with input from the external auditors.", "Relying on prior internal audit results to identify fraud risks, and input from external parties.", "Deferring the identification of emerging fraud risks until external audit engagements are conducted."]$q$::jsonb, $q$["ผสมผสานข้อมูลเชิงลึกจากการสืบสวนการฉ้อโกงกับการประเมินความเสี่ยงภายในเพื่อตรวจจับรูปแบบการฉ้อโกงที่เกิดขึ้นในเชิงรุก", "ดำเนินการประเมินความเสี่ยงโดยอิสระด้วยข้อมูลจากผู้ตรวจสอบภายนอก", "อาศัยผลการตรวจสอบภายในก่อนหน้าเพื่อระบุความเสี่ยงในการทุจริตและข้อมูลจากบุคคลภายนอก", "เลื่อนการระบุความเสี่ยงจากการฉ้อโกงที่เกิดขึ้นออกไปจนกว่าจะมีการดำเนินการตรวจสอบจากภายนอก"]$q$::jsonb, 0, $q$Correct. Combining internal assessments with fraud investigation insights enables  proactive identification of emerging risks.$q$, $q$ถูกต้อง. การรวมการประเมินภายในเข้ากับข้อมูลเชิงลึกในการตรวจสอบการฉ้อโกงทำให้สามารถระบุความเสี่ยงที่เกิดขึ้นได้ในเชิงรุก$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10369', '2026', 1, 'D.5.e', $q$How can internal auditors best benefit from reviewing risk  assessments conducted by fraud investigators?$q$, $q$ผู้ตรวจสอบภายในจะได้รับประโยชน์สูงสุดจากการสอบทานการประเมินความเสี่ยงที่ดำเนินการโดยผู้ตรวจสอบการฉ้อโกงได้อย่างไร$q$, $q$["By using fraud investigators’ risk assessments as the expert analysis of the organization’s fraud risks.", "By relying on their internal assessments and input from the external auditors.", "By comparing their own assessments with those of fraud investigators to identify gaps and improve the overall fraud risk management process.", "By reviewing and updating risk assessments after each fraud incident occurs."]$q$::jsonb, $q$["โดยใช้การประเมินความเสี่ยงของผู้ตรวจสอบการฉ้อโกงเป็นการวิเคราะห์โดยผู้เชี่ยวชาญเกี่ยวกับความเสี่ยงในการฉ้อโกงขององค์กร", "โดยอาศัยการประเมินภายในและข้อมูลจากผู้ตรวจสอบภายนอก", "โดยการเปรียบเทียบการประเมินของตนเองกับผู้ตรวจสอบการฉ้อโกงเพื่อระบุช่องว่างและปรับปรุงกระบวนการจัดการความเสี่ยงในการฉ้อโกงโดยรวม", "โดยทบทวนและปรับปรุงการประเมินความเสี่ยงภายหลังเหตุการณ์ทุจริตแต่ละครั้งเกิดขึ้น"]$q$::jsonb, 2, $q$Correct. Comparing risk assessments helps identify discrepancies and enhances the  overall fraud risk management process.$q$, $q$ถูกต้อง. การเปรียบเทียบการประเมินความเสี่ยงจะช่วยระบุความคลาดเคลื่อนและปรับปรุงกระบวนการจัดการความเสี่ยงจากการฉ้อโกงโดยรวม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10175', '2026', 1, 'A.1.a', $q$During a financial reporting review, management invites the  internal audit function to assess process efficiency. Which  objective of internal auditing best supports this scenario?$q$, $q$ในระหว่างการตรวจสอบรายงานทางการเงิน ฝ่ายบริหารจะเชิญหน่วยงานตรวจสอบภายในมาประเมินประสิทธิภาพของกระบวนการ วัตถุประสงค์ของการตรวจสอบภายในข้อใดสนับสนุนสถานการณ์นี้ได้ดีที่สุด$q$, $q$["It evaluates routine operational activities to ensure that daily processes meet the organization’s performance standards.", "It offers independent and objective advisory services that enhances risk management, internal controls, and governance frameworks.", "It suggests improvements to streamline operational efficiency.", "It streamlines the financial reporting process to ensure timely and accurate monthly closing of the books."]$q$::jsonb, $q$["ประเมินกิจกรรมการปฏิบัติงานตามปกติเพื่อให้แน่ใจว่ากระบวนการรายวันเป็นไปตามมาตรฐานการปฏิบัติงานขององค์กร", "ให้บริการที่ปรึกษาที่เป็นอิสระและเป็นกลาง ซึ่งจะช่วยเพิ่มประสิทธิภาพการบริหารความเสี่ยง การควบคุมภายใน และกรอบการกำกับดูแล", "แนะนำการปรับปรุงเพื่อปรับปรุงประสิทธิภาพการดำเนินงาน", "ช่วยเพิ่มความคล่องตัวให้กับกระบวนการรายงานทางการเงินเพื่อให้แน่ใจว่าการปิดบัญชีทุกเดือนจะตรงเวลาและถูกต้อง"]$q$::jsonb, 1, $q$Correct. The internal audit function can provide independent advisory services to  improve risk management, controls, and governance processes.$q$, $q$ถูกต้อง. หน่วยงานตรวจสอบภายในสามารถให้บริการที่ปรึกษาอิสระเพื่อปรับปรุงกระบวนการบริหารความเสี่ยง การควบคุม และการกำกับดูแล$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10176', '2026', 1, 'A.1.a', $q$During an organizational restructuring, leadership requests an  internal audit engagement to support strategic decision-making.  What is the primary benefit of the internal audit function in this  context?$q$, $q$ในระหว่างการปรับโครงสร้างองค์กร ผู้นำร้องขอให้มีการตรวจสอบภายในเพื่อสนับสนุนการตัดสินใจเชิงกลยุทธ์  ประโยชน์หลักของหน่วยงานตรวจสอบภายในในบริบทนี้คืออะไร?$q$, $q$["It offers independent assurance services to verify information being utilized by leadership for the restructuring.", "It offers either agreement or disagreement with strategic decisions related to the restructuring.", "It monitors leadership's strategic decision-making process.", "It updates the internal audit strategic plan related to the restructuring."]$q$::jsonb, $q$["ให้บริการประกันอิสระเพื่อตรวจสอบข้อมูลที่ผู้นำนำไปใช้ในการปรับโครงสร้างใหม่", "มีข้อตกลงหรือไม่เห็นด้วยกับการตัดสินใจเชิงกลยุทธ์ที่เกี่ยวข้องกับการปรับโครงสร้างใหม่", "ติดตามกระบวนการตัดสินใจเชิงกลยุทธ์ของผู้นำ", "ปรับปรุงแผนกลยุทธ์การตรวจสอบภายในที่เกี่ยวข้องกับการปรับโครงสร้าง"]$q$::jsonb, 0, $q$Correct. The internal audit function can add value to organizational restructuring by  verifying information utilized in decision-making.$q$, $q$ถูกต้อง. หน่วยงานตรวจสอบภายในสามารถเพิ่มมูลค่าให้กับการปรับโครงสร้างองค์กรด้วยการตรวจสอบข้อมูลที่ใช้ในการตัดสินใจ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10177', '2026', 1, 'A.1.b', $q$An organization seeking to improve its internal audit performance  is examining key supporting factors. Which condition is crucial in  empowering internal auditors to deliver quality results?$q$, $q$องค์กรที่ต้องการปรับปรุงประสิทธิภาพการตรวจสอบภายในกำลังตรวจสอบปัจจัยสนับสนุนที่สำคัญ เงื่อนไขใดเป็นสิ่งสำคัญในการเพิ่มขีดความสามารถของผู้ตรวจสอบภายในเพื่อให้ได้ผลลัพธ์ที่มีคุณภาพ$q$, $q$["The provision of adequate resources and relevant professional development opportunities.", "The allocation of resources focused on meeting routine operational targets.", "The emphasis on resource allocation that supports immediate tactical objectives.", "The establishment of policies that center on traditional audit practices."]$q$::jsonb, $q$["การจัดหาทรัพยากรที่เพียงพอและโอกาสในการพัฒนาวิชาชีพที่เกี่ยวข้อง", "การจัดสรรทรัพยากรที่เน้นการบรรลุเป้าหมายการปฏิบัติงานตามปกติ", "การเน้นการจัดสรรทรัพยากรที่สนับสนุนวัตถุประสงค์ทางยุทธวิธีเร่งด่วน", "การจัดทำนโยบายที่เน้นแนวปฏิบัติการตรวจสอบแบบดั้งเดิม"]$q$::jsonb, 0, $q$Correct. Adequate resources combined with ongoing professional development are vital  for internal auditors to perform effectively.$q$, $q$ถูกต้อง. ทรัพยากรที่เพียงพอรวมกับการพัฒนาทางวิชาชีพอย่างต่อเนื่องถือเป็นสิ่งสำคัญสำหรับผู้ตรวจสอบภายในในการปฏิบัติงานอย่างมีประสิทธิผล$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10178', '2026', 1, 'A.2.a', $q$A nonprofit organization is reviewing its internal audit practices.  How does the internal audit mandate typically delineate the  responsibilities of the board and the chief audit executive?$q$, $q$องค์กรไม่แสวงหาผลกำไรกำลังทบทวนแนวทางปฏิบัติในการตรวจสอบภายใน  โดยทั่วไปอำนาจการตรวจสอบภายในจะแบ่งแยกความรับผิดชอบของคณะกรรมการและหัวหน้าฝ่ายตรวจสอบภายในอย่างไร?$q$, $q$["It indicates that management approves the mandate contained in the internal audit charter, which is shared with the board.", "It requires that the board engage directly in audit tasks and that the chief audit executive focus on daily operational details.", "It outlines that the board should set detailed audit procedures and that the chief audit executive should implement these procedures across departments.", "It specifies that the board provides overall governance and strategic oversight, while the chief audit executive administers the internal audit function in alignment with the mandate."]$q$::jsonb, $q$["เป็นการบ่งชี้ว่าฝ่ายบริหารอนุมัติอาณัติที่มีอยู่ในกฎบัตรการตรวจสอบภายในซึ่งแบ่งปันกับคณะกรรมการ", "กำหนดให้คณะกรรมการมีส่วนร่วมในงานตรวจสอบโดยตรงและหัวหน้าผู้บริหารตรวจสอบให้ความสำคัญกับรายละเอียดการปฏิบัติงานประจำวัน", "โดยสรุปว่าคณะกรรมการควรกำหนดขั้นตอนการตรวจสอบโดยละเอียด และหัวหน้าฝ่ายตรวจสอบบัญชีควรใช้ขั้นตอนเหล่านี้ทั่วทั้งแผนก", "โดยระบุว่าคณะกรรมการจัดให้มีการกำกับดูแลโดยรวมและการกำกับดูแลเชิงกลยุทธ์ ในขณะที่หัวหน้าผู้บริหารฝ่ายตรวจสอบบัญชีดูแลงานการตรวจสอบภายในให้สอดคล้องกับอาณัติ"]$q$::jsonb, 3, $q$Correct. The internal audit mandate clearly assigns overall governance and strategic  oversight to the board, while entrusting the management of audit operations to the chief  audit executive.$q$, $q$ถูกต้อง. อำนาจการตรวจสอบภายในมอบหมายการกำกับดูแลโดยรวมและการกำกับดูแลเชิงกลยุทธ์ให้กับคณะกรรมการอย่างชัดเจน ขณะเดียวกันก็มอบหมายให้หัวหน้าฝ่ายตรวจสอบภายในจัดการการปฏิบัติงานตรวจสอบ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10179', '2026', 1, 'A.2.a', $q$A multinational corporation is reviewing its internal audit structure.  In light of the internal audit mandate, what is the typical  responsibility of the board regarding the internal audit function?$q$, $q$บริษัทข้ามชาติแห่งหนึ่งกำลังทบทวนโครงสร้างการตรวจสอบภายในของตน  ในแง่ของอำนาจการตรวจสอบภายใน ความรับผิดชอบโดยทั่วไปของคณะกรรมการเกี่ยวกับงานตรวจสอบภายในคืออะไร?$q$, $q$["It assigns the board to participate in designing audit methodologies and establishing a framework that supports continuous audit improvement.", "It directs the board to engage in setting internal audit policies, while the chief audit executive manages daily audit operations and reports progress.", "It provides strategic guidance and oversight to ensure the internal audit function remains independent and effective in its evaluations.", "It charges the board with setting the internal audit agenda and ensuring proper alignment with regulatory standards and organizational objectives."]$q$::jsonb, $q$["โดยมอบหมายให้คณะกรรมการมีส่วนร่วมในการออกแบบวิธีการตรวจสอบและสร้างกรอบการทำงานที่สนับสนุนการปรับปรุงการตรวจสอบอย่างต่อเนื่อง", "โดยกำกับดูแลให้คณะกรรมการมีส่วนร่วมในการกำหนดนโยบายการตรวจสอบภายใน ในขณะที่หัวหน้าฝ่ายตรวจสอบภายในทำหน้าที่จัดการการปฏิบัติงานตรวจสอบรายวันและรายงานความคืบหน้า", "โดยให้คำแนะนำเชิงกลยุทธ์และการกำกับดูแลเพื่อให้แน่ใจว่าหน่วยงานตรวจสอบภายในยังคงความเป็นอิสระและมีประสิทธิภาพในการประเมิน", "มอบหมายให้คณะกรรมการกำหนดวาระการตรวจสอบภายในและดูแลให้สอดคล้องกับมาตรฐานการกำกับดูแลและวัตถุประสงค์ขององค์กร"]$q$::jsonb, 2, $q$Correct. The board’s role is to offer strategic guidance and maintain oversight to  safeguard the independence and effectiveness of the internal audit function.$q$, $q$ถูกต้อง. บทบาทของคณะกรรมการคือการให้คำแนะนำเชิงกลยุทธ์และดูแลรักษาการกำกับดูแลเพื่อรักษาความเป็นอิสระและประสิทธิผลของหน่วยงานตรวจสอบภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10180', '2026', 1, 'A.2.a', $q$A government agency is evaluating its internal audit charter.  Which statement best describes the responsibilities shared by the  board and the chief audit executive under the internal audit  mandate?$q$, $q$หน่วยงานของรัฐกำลังประเมินกฎบัตรการตรวจสอบภายใน  ข้อความใดอธิบายความรับผิดชอบร่วมกันของคณะกรรมการและหัวหน้าฝ่ายตรวจสอบภายในภายใต้อำนาจการตรวจสอบภายในได้ดีที่สุด$q$, $q$["The board establishes audit policies and maintains oversight, while the chief audit executive implements, monitors, and refines audit processes systematically.", "The chief audit executive sets the strategic framework and monitors overall performance, and the board is apprised of audit results.", "The board offers high-level internal audit oversight, while the chief audit executive executes audit plans and reviews outcomes across the organization.", "The board supports the internal audit function's unrestricted access to information and personnel. The chief audit executive supports the board by keeping them informed of the internal audit function's progress."]$q$::jsonb, $q$["คณะกรรมการกำหนดนโยบายการตรวจสอบและกำกับดูแล ในขณะที่หัวหน้าผู้บริหารตรวจสอบดำเนินการ ติดตาม และปรับปรุงกระบวนการตรวจสอบอย่างเป็นระบบ", "หัวหน้าฝ่ายตรวจสอบบัญชีเป็นผู้กำหนดกรอบกลยุทธ์และติดตามผลการปฏิบัติงานโดยรวม และคณะกรรมการจะได้รับการประเมินผลการตรวจสอบ", "คณะกรรมการเสนอการกำกับดูแลการตรวจสอบภายในระดับสูง ในขณะที่หัวหน้าผู้บริหารฝ่ายตรวจสอบดำเนินการตามแผนการตรวจสอบและทบทวนผลลัพธ์ทั่วทั้งองค์กร", "คณะกรรมการสนับสนุนให้หน่วยงานตรวจสอบภายในสามารถเข้าถึงข้อมูลและบุคลากรได้อย่างไม่จำกัด หัวหน้าฝ่ายตรวจสอบภายในสนับสนุนคณะกรรมการโดยแจ้งความคืบหน้าของหน่วยงานตรวจสอบภายใน"]$q$::jsonb, 3, $q$Correct. There are shared responsibilities between the board and chief audit executive.  The board supports the internal audit function's unrestricted access to information and  personnel. The chief audit executive supports the board by keeping them informed of the  internal audit function's progress.$q$, $q$ถูกต้อง. มีความรับผิดชอบร่วมกันระหว่างคณะกรรมการและหัวหน้าฝ่ายตรวจสอบบัญชี  คณะกรรมการสนับสนุนให้หน่วยงานตรวจสอบภายในสามารถเข้าถึงข้อมูลและบุคลากรได้อย่างไม่จำกัด หัวหน้าฝ่ายตรวจสอบภายในสนับสนุนคณะกรรมการโดยแจ้งความคืบหน้าของหน่วยงานตรวจสอบภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10181', '2026', 1, 'A.2.a', $q$A company is reviewing its internal audit function to clarify its  responsibilities. Which statement best describes the internal audit  function's role?$q$, $q$บริษัทแห่งหนึ่งกำลังทบทวนหน่วยงานตรวจสอบภายในเพื่อชี้แจงความรับผิดชอบของตน ข้อความใดอธิบายบทบาทของหน่วยงานตรวจสอบภายในได้ดีที่สุด$q$, $q$["It focuses on implementing any assigned tasks as requested by the chief financial officer.", "It provides independent assurance by evaluating governance, risk management, and control processes.", "It is responsible for implementing any external audit recommendations.", "It coordinates processes by following a routine checklist provided by management."]$q$::jsonb, $q$["โดยมุ่งเน้นที่การปฏิบัติงานที่ได้รับมอบหมายตามที่ประธานเจ้าหน้าที่ฝ่ายการเงินร้องขอ", "ให้การรับประกันที่เป็นอิสระโดยการประเมินการกำกับดูแล การบริหารความเสี่ยง และกระบวนการควบคุม", "มีหน้าที่รับผิดชอบในการดำเนินการตามคำแนะนำการตรวจสอบภายนอก", "ประสานกระบวนการต่างๆ โดยปฏิบัติตามรายการตรวจสอบตามปกติที่ฝ่ายบริหารจัดเตรียมไว้ให้"]$q$::jsonb, 1, $q$Correct. The internal audit function’s role is to deliver independent assurance through the  evaluation of governance, risk management, and controls.$q$, $q$ถูกต้อง. บทบาทของหน่วยงานตรวจสอบภายในคือการให้ความเชื่อมั่นที่เป็นอิสระผ่านการประเมินการกำกับดูแล การบริหารความเสี่ยง และการควบคุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10182', '2026', 1, 'A.2.a', $q$A nonprofit organization seeks to enhance its internal audit  function. Which aspect of the function’s responsibilities is most  crucial for ensuring effectiveness?$q$, $q$องค์กรที่ไม่แสวงหากำไรพยายามที่จะปรับปรุงหน่วยงานตรวจสอบภายใน ความรับผิดชอบของหน่วยงานด้านใดที่สำคัญที่สุดในการประกันประสิทธิผล$q$, $q$["Implementing audit recommendations on a predetermined schedule set by senior management.", "Focusing on operational efficiency by monitoring daily tasks and administrative procedures.", "Providing advisory support to management on process improvements as needs arise.", "Conducting independent assessments of governance, risk management, and control processes to guide decisions."]$q$::jsonb, $q$["การดำเนินการตามคำแนะนำการตรวจสอบตามกำหนดเวลาที่กำหนดไว้โดยผู้บริหารระดับสูง", "มุ่งเน้นประสิทธิภาพการดำเนินงานโดยติดตามงานประจำวันและขั้นตอนการบริหาร", "ให้การสนับสนุนที่ปรึกษาแก่ฝ่ายบริหารในการปรับปรุงกระบวนการตามความจำเป็น", "ดำเนินการประเมินการกำกับดูแล การบริหารความเสี่ยง และกระบวนการควบคุมอย่างเป็นอิสระเพื่อเป็นแนวทางในการตัดสินใจ"]$q$::jsonb, 3, $q$Correct. Independent assessments of governance, risk management, and controls are  central to guiding effective strategic decisions.$q$, $q$ถูกต้อง. การประเมินการกำกับดูแล การบริหารความเสี่ยง และการควบคุมอย่างเป็นอิสระถือเป็นหัวใจสำคัญในการชี้แนะการตัดสินใจเชิงกลยุทธ์ที่มีประสิทธิผล$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10183', '2026', 1, 'A.2.b', $q$When revising the internal audit mandate, which essential  contribution does the chief audit executive (CAE) make?$q$, $q$ในการแก้ไขอำนาจการตรวจสอบภายใน หัวหน้าฝ่ายตรวจสอบภายใน (CAE) มีส่วนสำคัญอะไรบ้าง?$q$, $q$["The CAE informs the board of the characteristics of an effective internal audit function by sharing knowledge about the Standards.", "The CAE revises the mandate unilaterally without board consultation.", "The CAE focuses primarily on administrative updates rather than strategic risk areas.", "The CAE maintains the existing mandate seeking approval of the board."]$q$::jsonb, $q$["CAE แจ้งให้คณะกรรมการทราบถึงคุณลักษณะของหน่วยงานตรวจสอบภายในที่มีประสิทธิผลโดยการแบ่งปันความรู้เกี่ยวกับมาตรฐาน", "CAE แก้ไขอาณัติฝ่ายเดียวโดยไม่ต้องปรึกษาหารือกับคณะกรรมการ", "CAE มุ่งเน้นไปที่การปรับปรุงด้านการบริหารเป็นหลักมากกว่าพื้นที่ความเสี่ยงเชิงกลยุทธ์", "CAE รักษาอำนาจที่มีอยู่เพื่อขออนุมัติจากคณะกรรมการ"]$q$::jsonb, 0, $q$Correct. The Global Internal Audit Standards help to ensure an effective internal audit  function, so it is important for the CAE to inform the board about the Standards.$q$, $q$ถูกต้อง. มาตรฐานการตรวจสอบภายในสากลช่วยให้มั่นใจว่าหน่วยงานตรวจสอบภายในมีประสิทธิผล ดังนั้น CAE จึงเป็นสิ่งสำคัญที่จะต้องแจ้งให้คณะกรรมการทราบเกี่ยวกับมาตรฐานดังกล่าว$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10184', '2026', 1, 'A.2.b', $q$How does the chief audit executive (CAE) ensure that the board’s  fiduciary responsibility is reflected in the internal audit mandate?$q$, $q$หัวหน้าฝ่ายตรวจสอบภายใน (CAE) มั่นใจได้อย่างไรว่าความรับผิดชอบที่ได้รับมอบหมายของคณะกรรมการสะท้อนให้เห็นในอำนาจการตรวจสอบภายใน$q$, $q$["The CAE focuses on compliance and regulatory requirements instead of responsibilities.", "The CAE defers to management’s requirements when updating the mandate.", "The CAE retains the existing mandate to help avoid delays in the board's agenda.", "The CAE provides the audit committee charter along with the internal audit charter to ensure that appropriate joint responsibilities are included, consistent with the internal audit mandate."]$q$::jsonb, $q$["CAE มุ่งเน้นไปที่การปฏิบัติตามข้อกำหนดและกฎระเบียบแทนความรับผิดชอบ", "CAE ปฏิบัติตามข้อกำหนดของฝ่ายบริหารเมื่อมีการปรับปรุงอาณัติ", "CAE ยังคงอำนาจหน้าที่ที่มีอยู่เพื่อช่วยหลีกเลี่ยงความล่าช้าในวาระการประชุมของคณะกรรมการ", "CAE จัดให้มีกฎบัตรคณะกรรมการตรวจสอบควบคู่กับกฎบัตรการตรวจสอบภายใน เพื่อให้มั่นใจว่าความรับผิดชอบร่วมกันที่เหมาะสมถูกรวมไว้ และสอดคล้องกับอำนาจการตรวจสอบภายใน"]$q$::jsonb, 3, $q$Correct. By providing both charters, the CAE helps ensure that the mandate clearly  articulates the roles, responsibilities, and expectations of internal audit in a way that  supports and reflects the governance and oversight role of the board. This alignment is  crucial for reinforcing the board’s fiduciary duties related to risk management, control,  and governance processes.$q$, $q$ถูกต้อง. ด้วยการจัดทำกฎบัตรทั้งสองฉบับ CAE ช่วยให้มั่นใจว่าอาณัติดังกล่าวระบุบทบาท ความรับผิดชอบ และความคาดหวังของการตรวจสอบภายในอย่างชัดเจน ในลักษณะที่สนับสนุนและสะท้อนถึงบทบาทการกำกับดูแลและการกำกับดูแลของคณะกรรมการ การจัดตำแหน่งนี้มีความสำคัญอย่างยิ่งในการเสริมสร้างหน้าที่ที่ได้รับความไว้วางใจของคณะกรรมการที่เกี่ยวข้องกับการบริหารความเสี่ยง การควบคุม และการกำกับดูแลกระบวนการ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10185', '2026', 1, 'A.2.b', $q$During a board review of the internal audit mandate, how does the  chief audit executive (CAE) facilitate understanding of complex  audit issues?$q$, $q$ในระหว่างการทบทวนอำนาจการตรวจสอบภายในของคณะกรรมการ หัวหน้าฝ่ายตรวจสอบภายใน (CAE) ช่วยให้เข้าใจประเด็นการตรวจสอบที่ซับซ้อนได้อย่างไร$q$, $q$["The CAE summarizes audit reports briefly without discussing underlying risks.", "The CAE presents technical details using specialized jargon without simplification.", "The CAE focuses on routine data instead of addressing complex audit issues.", "The CAE explains audit findings and risk implications in clear, concise terms to aid board decision-making."]$q$::jsonb, $q$["CAE จะสรุปรายงานการตรวจสอบโดยย่อโดยไม่ต้องพูดถึงความเสี่ยงที่ซ่อนอยู่", "CAE นำเสนอรายละเอียดทางเทคนิคโดยใช้ศัพท์เฉพาะโดยไม่ทำให้เข้าใจง่าย", "CAE มุ่งเน้นไปที่ข้อมูลประจำแทนที่จะจัดการกับปัญหาการตรวจสอบที่ซับซ้อน", "CAE อธิบายผลการตรวจสอบและผลกระทบต่อความเสี่ยงด้วยเงื่อนไขที่ชัดเจนและรัดกุมเพื่อช่วยในการตัดสินใจของคณะกรรมการ"]$q$::jsonb, 3, $q$Correct. Explaining audit findings in clear, concise terms helps the board grasp complex  issues and make informed decisions.$q$, $q$ถูกต้อง. การอธิบายผลการตรวจสอบด้วยเงื่อนไขที่ชัดเจนและรัดกุมช่วยให้คณะกรรมการเข้าใจประเด็นที่ซับซ้อนและตัดสินใจได้อย่างมีข้อมูลครบถ้วน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10186', '2026', 1, 'A.2.c', $q$In a risk-aware organization, how do the board and senior  management jointly influence the internal audit function's authority?$q$, $q$ในองค์กรที่ตระหนักถึงความเสี่ยง คณะกรรมการและผู้บริหารระดับสูงจะร่วมกันมีอิทธิพลต่ออำนาจการตรวจสอบภายในได้อย่างไร?$q$, $q$["The board and senior management work together to enable the internal audit function's unrestricted access to information, personnel, and property needed to fulfill the internal audit mandate.", "The board maintains high- level oversight, while senior management adheres strictly to traditional operational tasks.", "Management determines the internal audit function's access to information and personnel, and the board is kept informed.", "The board solely defines authority, and senior management determines internal audit responsibilities."]$q$::jsonb, $q$["คณะกรรมการและผู้บริหารระดับสูงทำงานร่วมกันเพื่อให้หน่วยงานตรวจสอบภายในสามารถเข้าถึงข้อมูล บุคลากร และทรัพย์สินที่จำเป็นต่อการปฏิบัติตามคำสั่งตรวจสอบภายในได้อย่างไม่จำกัด", "คณะกรรมการมีการกำกับดูแลในระดับสูง ในขณะที่ผู้บริหารระดับสูงยึดมั่นในการปฏิบัติงานแบบเดิมๆ อย่างเคร่งครัด", "ฝ่ายบริหารเป็นผู้กำหนดการเข้าถึงข้อมูลและบุคลากรของหน่วยงานตรวจสอบภายใน และคณะกรรมการจะได้รับแจ้งอยู่เสมอ", "คณะกรรมการเป็นผู้กำหนดอำนาจหน้าที่แต่เพียงผู้เดียว และผู้บริหารระดับสูงเป็นผู้กำหนดความรับผิดชอบด้านการตรวจสอบภายใน"]$q$::jsonb, 0, $q$Correct. The board and senior management are both responsible for enabling the internal  audit function’s unrestricted access to information, personnel, and property needed to  fulfill the mandate.$q$, $q$ถูกต้อง. คณะกรรมการและผู้บริหารระดับสูงมีหน้าที่รับผิดชอบในการทำให้หน่วยงานตรวจสอบภายในสามารถเข้าถึงข้อมูล บุคลากร และทรัพย์สินที่จำเป็นต่อการปฏิบัติตามคำสั่งได้อย่างไม่จำกัด$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10187', '2026', 1, 'A.2.c', $q$When defining the internal audit function's authority, what role do  the board and senior management play?$q$, $q$ในการกำหนดอำนาจหน้าที่ของหน่วยงานตรวจสอบภายใน คณะกรรมการและผู้บริหารระดับสูงมีบทบาทอย่างไร?$q$, $q$["The board meets with the chief audit executive privately, without senior management present, to inquire on any restrictions on the internal audit function.", "The board meets with the chief audit executive, with senior management present, to inquire on any restrictions on the internal audit function.", "Senior management meets with the chief audit executive, without the board present, to inquire on any restrictions on the internal audit function.", "Senior management can limit the authority of the internal audit function without informing the board."]$q$::jsonb, $q$["คณะกรรมการจะพบปะกับหัวหน้าฝ่ายตรวจสอบภายในเป็นการส่วนตัว โดยไม่มีฝ่ายบริหารอาวุโสเข้าร่วมประชุม เพื่อสอบถามเกี่ยวกับข้อจำกัดใดๆ เกี่ยวกับหน่วยงานตรวจสอบภายใน", "คณะกรรมการจะพบปะกับหัวหน้าผู้บริหารฝ่ายตรวจสอบภายใน โดยมีผู้บริหารระดับสูงเข้าร่วมประชุม เพื่อสอบถามเกี่ยวกับข้อจำกัดใดๆ เกี่ยวกับหน่วยงานตรวจสอบภายใน", "ผู้บริหารระดับสูงจะพบปะกับหัวหน้าฝ่ายตรวจสอบภายใน โดยไม่มีคณะกรรมการเข้าร่วม เพื่อสอบถามเกี่ยวกับข้อจำกัดใดๆ เกี่ยวกับหน่วยงานตรวจสอบภายใน", "ผู้บริหารระดับสูงสามารถจำกัดอำนาจของหน่วยงานตรวจสอบภายในได้โดยไม่ต้องแจ้งให้คณะกรรมการทราบ"]$q$::jsonb, 0, $q$Correct. The board must meet with the chief audit executive privately, without senior  management present, to inquire on any restrictions on the internal audit function in order  to evaluate any restrictions on their authority.$q$, $q$ถูกต้อง. คณะกรรมการจะต้องพบปะกับหัวหน้าฝ่ายตรวจสอบภายในเป็นการส่วนตัว โดยไม่มีฝ่ายบริหารอาวุโสอยู่ด้วย เพื่อสอบถามเกี่ยวกับข้อจำกัดใดๆ เกี่ยวกับหน่วยงานตรวจสอบภายใน เพื่อประเมินข้อจำกัดใดๆ เกี่ยวกับอำนาจหน้าที่ของตน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10188', '2026', 1, 'A.3.a', $q$At a recent meeting, the audit committee reviews the internal audit  charter. Which requirement is essential to the charter’s  effectiveness?$q$, $q$ในการประชุมครั้งล่าสุด คณะกรรมการตรวจสอบได้ทบทวนกฎบัตรการตรวจสอบภายใน ข้อกำหนดใดที่จำเป็นต่อประสิทธิผลของกฎบัตร?$q$, $q$["It should state the objective of providing independent assurance on governance, risk management, and control processes.", "It should include any operational tasks assigned by the chief financial officer for the internal audit function to perform.", "It must include a detailed breakdown of audit budgets and resource allocations.", "It is expected to specify the process for selecting external auditors for compliance checks."]$q$::jsonb, $q$["ควรระบุวัตถุประสงค์ของการให้การรับรองที่เป็นอิสระเกี่ยวกับการกำกับดูแล การบริหารความเสี่ยง และกระบวนการควบคุม", "ควรรวมถึงงานปฏิบัติการใด ๆ ที่ได้รับมอบหมายจากประธานเจ้าหน้าที่ฝ่ายการเงินเพื่อให้หน่วยงานตรวจสอบภายในดำเนินการ", "จะต้องมีรายละเอียดงบประมาณการตรวจสอบและการจัดสรรทรัพยากร", "คาดว่าจะระบุขั้นตอนการคัดเลือกผู้ตรวจสอบภายนอกเพื่อตรวจสอบการปฏิบัติตามข้อกำหนด"]$q$::jsonb, 0, $q$Correct. The charter must state the objective of offering independent assurance on key  areas such as governance, risk management, and controls.$q$, $q$ถูกต้อง. กฎบัตรต้องระบุวัตถุประสงค์ของการเสนอการรับรองที่เป็นอิสระในประเด็นสำคัญ เช่น การกำกับดูแล การบริหารความเสี่ยง และการควบคุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10189', '2026', 1, 'A.3.a', $q$Which structural requirement mandated by the Global Internal  Audit Standards helps maintain the independence of the internal  audit function?$q$, $q$ข้อกำหนดเชิงโครงสร้างใดที่ได้รับคำสั่งจากมาตรฐานการตรวจสอบภายในระดับโลกที่ช่วยรักษาความเป็นอิสระของหน่วยงานตรวจสอบภายใน$q$, $q$["A framework that integrates audit findings with the external auditors.", "A structure where the internal audit function reports directly to the CEO of the organization.", "A reporting structure that enables direct communication with the board or audit committee.", "A system that rotates audit responsibilities among various management departments."]$q$::jsonb, $q$["กรอบการทำงานที่รวมผลการตรวจสอบเข้ากับผู้ตรวจสอบภายนอก", "โครงสร้างที่หน่วยงานตรวจสอบภายในรายงานตรงต่อประธานเจ้าหน้าที่บริหารขององค์กร", "โครงสร้างการรายงานที่ช่วยให้สามารถสื่อสารโดยตรงกับคณะกรรมการหรือคณะกรรมการตรวจสอบ", "ระบบที่หมุนเวียนความรับผิดชอบด้านการตรวจสอบระหว่างฝ่ายจัดการต่างๆ"]$q$::jsonb, 2, $q$Correct. Direct reporting to the board or audit committee is essential for preserving the  independence of the internal audit function.$q$, $q$ถูกต้อง. การรายงานตรงต่อคณะกรรมการหรือคณะกรรมการตรวจสอบถือเป็นสิ่งสำคัญในการรักษาความเป็นอิสระของหน่วยงานตรวจสอบภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10190', '2026', 1, 'A.3.b', $q$During an audit committee meeting, a company discusses its  internal audit charter with board members and senior  management. What is the main benefit of this discussion?$q$, $q$ในระหว่างการประชุมคณะกรรมการตรวจสอบ บริษัทจะหารือเกี่ยวกับกฎบัตรการตรวจสอบภายในกับสมาชิกคณะกรรมการและผู้บริหารระดับสูง ประโยชน์หลักของการสนทนานี้คืออะไร?$q$, $q$["It permits the board to make decisions without input from management.", "It permits management to direct decisions on the function of internal auditing.", "It supports the internal audit mandate and promotes the internal audit function's responsibilities.", "It shifts responsibility for the charter primarily to the internal auditors."]$q$::jsonb, $q$["อนุญาตให้คณะกรรมการตัดสินใจได้โดยไม่ต้องได้รับข้อมูลจากฝ่ายบริหาร", "ช่วยให้ฝ่ายบริหารสามารถกำหนดทิศทางการตัดสินใจเกี่ยวกับหน้าที่การตรวจสอบภายในได้", "สนับสนุนอำนาจการตรวจสอบภายในและส่งเสริมความรับผิดชอบของหน่วยงานตรวจสอบภายใน", "โดยจะเปลี่ยนความรับผิดชอบสำหรับกฎบัตรไปที่ผู้ตรวจสอบภายในเป็นหลัก"]$q$::jsonb, 2, $q$Correct. Such discussions promote shared understanding and accountability, ensuring  that the internal audit charter effectively supports the internal audit mandate.$q$, $q$ถูกต้อง. การอภิปรายดังกล่าวส่งเสริมความเข้าใจและความรับผิดชอบร่วมกัน เพื่อให้มั่นใจว่ากฎบัตรการตรวจสอบภายในสนับสนุนอำนาจการตรวจสอบภายในอย่างมีประสิทธิผล$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10191', '2026', 1, 'A.4', $q$A financial institution is reviewing its internal audit function. How  can the differences between assurance and advisory services be  interpreted?$q$, $q$สถาบันการเงินแห่งหนึ่งกำลังทบทวนหน่วยงานตรวจสอบภายในของตน สามารถตีความความแตกต่างระหว่างบริการให้ความเชื่อมั่นและบริการให้คำปรึกษาได้อย่างไร?$q$, $q$["Assurance services deliver independent assessments and formal opinions, whereas advisory services advise on enhancing operations.", "Assurance services provide formal evaluations of controls and risks, while advisory services offer consultative guidance without providing assurance.", "Assurance services yield formal opinions through independent reviews, while advisory services provide required recommendations to support improvement.", "Assurance services result in formal evaluations of controls, and advisory services supply consultative suggestions and opinions."]$q$::jsonb, $q$["งานบริการให้ความเชื่อมั่นให้การประเมินที่เป็นอิสระและความคิดเห็นอย่างเป็นทางการ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำในการเพิ่มประสิทธิภาพการดำเนินงาน", "งานบริการให้ความเชื่อมั่นให้การประเมินการควบคุมและความเสี่ยงอย่างเป็นทางการ ในขณะที่บริการให้คำปรึกษาให้คำแนะนำในการให้คำปรึกษาโดยไม่ต้องให้การรับรอง", "งานบริการให้ความเชื่อมั่นจะให้ความคิดเห็นอย่างเป็นทางการผ่านการทบทวนโดยอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำที่จำเป็นเพื่อสนับสนุนการปรับปรุง", "งานบริการให้ความเชื่อมั่นส่งผลให้เกิดการประเมินการควบคุมอย่างเป็นทางการ และบริการให้คำปรึกษาจะให้คำแนะนำและความคิดเห็นเชิงปรึกษา"]$q$::jsonb, 1, $q$Correct. Assurance services produce formal, independent evaluations and opinions,  while advisory services offer consultative guidance without providing assurance.$q$, $q$ถูกต้อง. งานบริการให้ความเชื่อมั่นจะให้การประเมินและความคิดเห็นที่เป็นทางการและเป็นอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำในการให้คำปรึกษาโดยไม่ต้องให้การรับรอง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10192', '2026', 1, 'A.4', $q$During a risk assessment, how can one interpret the distinct roles  of assurance and advisory services provided by internal auditing?$q$, $q$ในระหว่างการประเมินความเสี่ยง เราจะตีความบทบาทที่แตกต่างกันของบริการการให้ความเชื่อมั่นและคำปรึกษาที่ให้บริการโดยการตรวจสอบภายในได้อย่างไร$q$, $q$["Assurance services offer independent, formal assessments of risks and controls, while advisory services give consultative suggestions for improvement.", "Assurance services deliver objective evaluations of processes without formal opinions, whereas advisory services advise on control design.", "Assurance services produce opinions from structured reviews, while advisory services supply consultative guidance and formal conclusions.", "Assurance services conduct formal evaluations focused on process improvement, and advisory services focus on opportunities to improve control effectiveness."]$q$::jsonb, $q$["งานบริการให้ความเชื่อมั่นให้การประเมินความเสี่ยงและการควบคุมอย่างเป็นทางการที่เป็นอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำเชิงปรึกษาเพื่อการปรับปรุง", "งานบริการให้ความเชื่อมั่นให้การประเมินตามวัตถุประสงค์ของกระบวนการโดยไม่ต้องมีความคิดเห็นอย่างเป็นทางการ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำเกี่ยวกับการออกแบบการควบคุม", "บริการให้การรับประกันจะสร้างความคิดเห็นจากการทบทวนที่มีโครงสร้าง ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำในการปรึกษาและการสรุปผลอย่างเป็นทางการ", "งานบริการให้ความเชื่อมั่นดำเนินการประเมินอย่างเป็นทางการโดยเน้นที่การปรับปรุงกระบวนการ และบริการให้คำปรึกษามุ่งเน้นไปที่โอกาสในการปรับปรุงประสิทธิภาพการควบคุม"]$q$::jsonb, 0, $q$Correct. Assurance services are characterized by formal, independent assessments  resulting in opinions, while advisory services provide consultative suggestions without  formal opinions.$q$, $q$ถูกต้อง. งานบริการให้ความเชื่อมั่นมีลักษณะเฉพาะคือการประเมินที่เป็นทางการและเป็นอิสระซึ่งส่งผลให้เกิดความคิดเห็น ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำเชิงปรึกษาโดยไม่มีความคิดเห็นที่เป็นทางการ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10193', '2026', 1, 'A.4', $q$In a external quality assessment, how should internal audit  services be differentiated between assurance and advisory roles?$q$, $q$ในการประเมินคุณภาพภายนอก บริการตรวจสอบภายในควรมีความแตกต่างระหว่างบทบาทการให้ความเชื่อมั่นและที่ปรึกษาอย่างไร$q$, $q$["Assurance services produce formal opinions from structured evaluations, and advisory services deliver objective advice to support management decision- making.", "Assurance services yield formal conclusions through independent assessments, whereas advisory services supply required recommendations for organizational improvement.", "Assurance services lack independence resulting in informal opinions, while advisory services advise on process enhancements through flexible guidance.", "Assurance services provide formal, independent evaluations and opinions on controls, while advisory services offer guidance and suggestions without formal opinions."]$q$::jsonb, $q$["บริการด้านการประกันจะให้ความคิดเห็นอย่างเป็นทางการจากการประเมินแบบมีโครงสร้าง และบริการให้คำปรึกษาจะให้คำแนะนำที่เป็นกลางเพื่อสนับสนุนการตัดสินใจของฝ่ายบริหาร", "งานบริการให้ความเชื่อมั่นให้ข้อสรุปอย่างเป็นทางการผ่านการประเมินที่เป็นอิสระ ในขณะที่บริการให้คำปรึกษาให้คำแนะนำที่จำเป็นสำหรับการปรับปรุงองค์กร", "งานบริการให้ความเชื่อมั่นขาดความเป็นอิสระซึ่งส่งผลให้เกิดความคิดเห็นที่ไม่เป็นทางการ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำเกี่ยวกับการปรับปรุงกระบวนการผ่านคำแนะนำที่ยืดหยุ่น", "งานบริการให้ความเชื่อมั่นให้การประเมินและความคิดเห็นอย่างเป็นทางการและเป็นอิสระเกี่ยวกับการควบคุม ในขณะที่บริการให้คำปรึกษาให้คำแนะนำและข้อเสนอแนะโดยไม่มีความคิดเห็นอย่างเป็นทางการ"]$q$::jsonb, 3, $q$Correct. The key point is that assurance services deliver formal opinions based on  independent evaluations, while advisory services provide consultative guidance without  issuing formal opinions.$q$, $q$ถูกต้อง. ประเด็นสำคัญคือบริการให้ความเชื่อมั่นจะให้ความเห็นอย่างเป็นทางการโดยอิงจากการประเมินที่เป็นอิสระ ในขณะที่บริการให้คำปรึกษาจะให้คำแนะนำในการให้คำปรึกษาโดยไม่ต้องออกความคิดเห็นอย่างเป็นทางการ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10194', '2026', 1, 'A.4.a', $q$In an internal audit training session, how should assurance  services be defined?$q$, $q$ในการฝึกอบรมการตรวจสอบภายใน ควรกำหนดนิยามบริการให้ความเชื่อมั่นอย่างไร$q$, $q$["They are independent assessments that yield formal opinions on the effectiveness of controls and risks.", "They are internal reviews performed to support routine management reports on compliance.", "They are evaluations focused on verifying adherence to external regulations and policies.", "They are consultative reviews that offer suggestions without producing formal conclusions."]$q$::jsonb, $q$["เป็นการประเมินที่เป็นอิสระซึ่งให้ความเห็นอย่างเป็นทางการเกี่ยวกับประสิทธิผลของการควบคุมและความเสี่ยง", "เป็นการตรวจสอบภายในที่ดำเนินการเพื่อสนับสนุนรายงานการจัดการตามปกติเกี่ยวกับการปฏิบัติตามข้อกำหนด", "เป็นการประเมินที่เน้นการตรวจสอบการปฏิบัติตามกฎระเบียบและนโยบายภายนอก", "เป็นบทวิจารณ์เชิงปรึกษาที่เสนอข้อเสนอแนะโดยไม่ต้องให้ข้อสรุปอย่างเป็นทางการ"]$q$::jsonb, 0, $q$Correct. Assurance services are defined as independent assessments that provide  formal opinions on the effectiveness of controls and risks.$q$, $q$ถูกต้อง. งานบริการให้ความเชื่อมั่นหมายถึงการประเมินอิสระที่ให้ความเห็นอย่างเป็นทางการเกี่ยวกับประสิทธิผลของการควบคุมและความเสี่ยง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10195', '2026', 1, 'A.4.a', $q$During a board meeting, how can assurance services be defined  in internal auditing?$q$, $q$ในระหว่างการประชุมคณะกรรมการ จะกำหนดบริการให้ความเชื่อมั่นในการตรวจสอบภายในได้อย่างไร$q$, $q$["They are consultative assessments that offer recommendations without formal opinions.", "They are internal reviews that check compliance with established policies and procedures.", "They are external evaluations aimed at certifying financial data and regulatory adherence.", "They are independent reviews that deliver formal opinions on controls and risk management."]$q$::jsonb, $q$["เป็นการประเมินเชิงปรึกษาที่เสนอคำแนะนำโดยไม่มีความคิดเห็นที่เป็นทางการ", "เป็นการตรวจสอบภายในที่ตรวจสอบการปฏิบัติตามนโยบายและขั้นตอนที่กำหนดไว้", "เป็นการประเมินภายนอกที่มีวัตถุประสงค์เพื่อรับรองข้อมูลทางการเงินและการปฏิบัติตามกฎระเบียบ", "เป็นการทบทวนอิสระที่ให้ความเห็นอย่างเป็นทางการเกี่ยวกับการควบคุมและการบริหารความเสี่ยง"]$q$::jsonb, 3, $q$Correct. Assurance services are independent reviews that provide formal opinions on the  adequacy of controls and risk management.$q$, $q$ถูกต้อง. บริการให้ความเชื่อมั่นเป็นการทบทวนโดยอิสระที่ให้ความเห็นอย่างเป็นทางการเกี่ยวกับความเพียงพอของการควบคุมและการบริหารความเสี่ยง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10196', '2026', 1, 'A.4.a', $q$A governance committee is clarifying audit terminology. How  should assurance services be defined?$q$, $q$คณะกรรมการกำกับดูแลกำลังชี้แจงคำศัพท์ในการตรวจสอบ การบริการให้ความเชื่อมั่นควรกำหนดไว้อย่างไร?$q$, $q$["They are consultative processes that offer nonbinding advice to support process improvements.", "They are internal reviews that focus on monitoring routine compliance and operational metrics.", "They are independent evaluations that yield formal opinions on risk and control effectiveness.", "They are external reviews conducted to verify financial data and regulatory compliance."]$q$::jsonb, $q$["เป็นกระบวนการให้คำปรึกษาที่ให้คำแนะนำที่ไม่มีข้อผูกมัดเพื่อสนับสนุนการปรับปรุงกระบวนการ", "เป็นการทบทวนภายในที่มุ่งเน้นการตรวจสอบการปฏิบัติตามข้อกำหนดตามปกติและตัวชี้วัดการปฏิบัติงาน", "เป็นการประเมินที่เป็นอิสระซึ่งให้ความเห็นอย่างเป็นทางการเกี่ยวกับความเสี่ยงและประสิทธิผลในการควบคุม", "เป็นการตรวจสอบจากภายนอกที่ดำเนินการเพื่อตรวจสอบข้อมูลทางการเงินและการปฏิบัติตามกฎระเบียบ"]$q$::jsonb, 2, $q$Correct. Assurance services are independent evaluations that provide formal opinions on  the effectiveness of risk management and controls.$q$, $q$ถูกต้อง. งานบริการให้ความเชื่อมั่นคือการประเมินโดยอิสระที่ให้ความเห็นอย่างเป็นทางการเกี่ยวกับประสิทธิผลของการบริหารความเสี่ยงและการควบคุม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10197', '2026', 1, 'A.4.c', $q$At an internal audit workshop, a facilitator asks participants to  define advisory services. Which statement best describes them?$q$, $q$ในการประชุมเชิงปฏิบัติการการตรวจสอบภายใน ผู้อำนวยความสะดวกขอให้ผู้เข้าร่วมกำหนดบริการให้คำปรึกษา ข้อความใดอธิบายได้ดีที่สุด?$q$, $q$["Advisory services are routine checks that focus solely on regulatory compliance.", "Advisory services are structured evaluations that produce formal opinions on risk management.", "Advisory services are non- audit, consultative activities that help organizations identify and implement process improvements.", "Advisory services are external audit engagements that assess the accuracy of financial reporting."]$q$::jsonb, $q$["บริการให้คำปรึกษาคือการตรวจสอบเป็นประจำซึ่งมุ่งเน้นที่การปฏิบัติตามกฎระเบียบเท่านั้น", "บริการให้คำปรึกษาคือการประเมินที่มีโครงสร้างซึ่งให้ความเห็นอย่างเป็นทางการเกี่ยวกับการบริหารความเสี่ยง", "บริการให้คำปรึกษาเป็นกิจกรรมการให้คำปรึกษาที่ไม่ใช่การตรวจสอบบัญชีที่ช่วยให้องค์กรระบุและดำเนินการปรับปรุงกระบวนการ", "บริการให้คำปรึกษาเป็นงานตรวจสอบภายนอกที่ประเมินความถูกต้องของการรายงานทางการเงิน"]$q$::jsonb, 2, $q$Correct. Advisory services are non-audit engagements that provide consultative  recommendations for improvement rather than formal assurance.$q$, $q$ถูกต้อง. บริการให้คำปรึกษาเป็นงานที่ไม่ใช่การตรวจสอบที่ให้คำแนะนำเชิงปรึกษาเพื่อการปรับปรุงมากกว่าการรับรองอย่างเป็นทางการ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10198', '2026', 1, 'A.4.d', $q$How do changes in the organizational environment affect the  nature and scope of assurance services?$q$, $q$การเปลี่ยนแปลงในสภาพแวดล้อมขององค์กรส่งผลต่อลักษณะและขอบเขตของบริการให้ความเชื่อมั่นอย่างไร$q$, $q$["They require modifications only when external mandates dictate, without a thorough, proactive review of internal objectives, risks, or stakeholder perspectives.", "They lead to maintaining exactly the same scope, even when current risks and stakeholder inputs suggest that changes are needed.", "They result in adjustments based solely on routine updates that consistently overlook significant changes in risks or evolving stakeholder requirements.", "They prompt a review that updates engagement objectives, integrates emerging risk assessments, and incorporates revised stakeholder feedback into the scope."]$q$::jsonb, $q$["จำเป็นต้องมีการปรับเปลี่ยนเมื่อได้รับคำสั่งจากภายนอกเท่านั้น โดยไม่มีการทบทวนวัตถุประสงค์ภายใน ความเสี่ยง หรือมุมมองของผู้มีส่วนได้ส่วนเสียในเชิงรุกอย่างละเอียดถี่ถ้วน", "สิ่งเหล่านี้นำไปสู่การรักษาขอบเขตเดียวกันทุกประการ แม้ว่าความเสี่ยงในปัจจุบันและข้อมูลของผู้มีส่วนได้ส่วนเสียแนะนำว่าจำเป็นต้องเปลี่ยนแปลงก็ตาม", "ส่งผลให้เกิดการปรับเปลี่ยนตามการอัปเดตตามปกติเท่านั้น ซึ่งมองข้ามการเปลี่ยนแปลงที่สำคัญในความเสี่ยงหรือข้อกำหนดของผู้มีส่วนได้ส่วนเสียที่พัฒนาอย่างต่อเนื่อง", "พวกเขาพร้อมท์ให้มีการทบทวนว่าปรับปรุงวัตถุประสงค์ของการมีส่วนร่วม บูรณาการการประเมินความเสี่ยงที่เกิดขึ้น และรวมความคิดเห็นของผู้มีส่วนได้ส่วนเสียที่แก้ไขแล้วไว้ในขอบเขต"]$q$::jsonb, 3, $q$Correct. Regular reviews that update objectives, integrate emerging risks, and  incorporate revised stakeholder feedback are essential for adjusting the scope.$q$, $q$ถูกต้อง. การทบทวนเป็นประจำที่อัปเดตวัตถุประสงค์ บูรณาการความเสี่ยงที่เกิดขึ้น และรวมเอาคำติชมของผู้มีส่วนได้ส่วนเสียที่แก้ไขแล้ว เป็นสิ่งจำเป็นสำหรับการปรับขอบเขต$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10199', '2026', 1, 'A.4.e', $q$An organization needs to decide on a type of internal audit  engagement to either verify compliance with regulatory standards  or offer guidance for operational improvements. Which service  should be selected when formal validation is required?$q$, $q$องค์กรจำเป็นต้องตัดสินใจเลือกประเภทของงานตรวจสอบภายในเพื่อตรวจสอบการปฏิบัติตามมาตรฐานด้านกฎระเบียบหรือเสนอแนวทางสำหรับการปรับปรุงการปฏิบัติงาน ควรเลือกบริการใดเมื่อต้องมีการตรวจสอบอย่างเป็นทางการ$q$, $q$["Advisory services, because they emphasize the formal documentation of compliance testing along with strategic improvement advice.", "Advisory services, because they focus on delivering consultative guidance that assists in identifying process improvements.", "Assurance services, because they offer tailored recommendations for process improvement.", "Assurance services, because they provide an objective and formal validation of compliance through comprehensive evaluations and documented conclusions."]$q$::jsonb, $q$["บริการให้คำปรึกษา เนื่องจากเน้นเอกสารอย่างเป็นทางการของการทดสอบการปฏิบัติตามข้อกำหนดพร้อมกับคำแนะนำในการปรับปรุงเชิงกลยุทธ์", "บริการให้คำปรึกษา เนื่องจากมุ่งเน้นไปที่การให้คำแนะนำเชิงปรึกษาที่ช่วยในการระบุการปรับปรุงกระบวนการ", "บริการด้านการรับประกัน เนื่องจากจะให้คำแนะนำที่ปรับให้เหมาะสมสำหรับการปรับปรุงกระบวนการ", "งานบริการให้ความเชื่อมั่น เนื่องจากให้บริการตรวจสอบตามวัตถุประสงค์และเป็นทางการผ่านการประเมินที่ครอบคลุมและข้อสรุปที่จัดทำเป็นเอกสาร"]$q$::jsonb, 3, $q$Correct. When formal validation of compliance is required, assurance services are  appropriate due to their objective and documented evaluations.$q$, $q$ถูกต้อง. เมื่อจำเป็นต้องมีการตรวจสอบความถูกต้องอย่างเป็นทางการของการปฏิบัติตามข้อกำหนด บริการให้ความเชื่อมั่นจะมีความเหมาะสมเนื่องจากวัตถุประสงค์และการประเมินที่ได้รับการจัดทำเป็นเอกสาร$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10200', '2026', 1, 'A.4.e', $q$When planning an internal audit engagement, a company must  choose a service type that best meets its need for an objective  evaluation of its operational controls versus a consultative process  for improvement. Which option is most suitable if an objective,  formal assessment is required?$q$, $q$เมื่อวางแผนการตรวจสอบภายใน บริษัทจะต้องเลือกประเภทบริการที่ตรงกับความต้องการของตนมากที่สุดสำหรับการประเมินการควบคุมการปฏิบัติงานตามวัตถุประสงค์ เทียบกับกระบวนการให้คำปรึกษาเพื่อปรับปรุง Which option is most suitable if an objective,  formal assessment is required?$q$, $q$["Assurance services, because they deliver both formal evaluations and strategic improvement recommendations as a combined service.", "Advisory services, because they focus on offering consultative recommendations to improve operational processes based on management discussions.", "Assurance services, because they provide an independent and formal assessment of operational controls through systematic and objective testing.", "Advisory services, because they produce formal reports that document the effectiveness of operational controls along with improvement insights."]$q$::jsonb, $q$["บริการด้านการรับประกัน เนื่องจากให้บริการทั้งการประเมินอย่างเป็นทางการและคำแนะนำในการปรับปรุงเชิงกลยุทธ์เป็นบริการแบบผสมผสาน", "บริการให้คำปรึกษา เนื่องจากมุ่งเน้นการเสนอคำแนะนำเชิงปรึกษาเพื่อปรับปรุงกระบวนการปฏิบัติงานตามการอภิปรายของฝ่ายบริหาร", "งานบริการให้ความเชื่อมั่น เนื่องจากให้การประเมินการควบคุมการปฏิบัติงานที่เป็นอิสระและเป็นทางการผ่านการทดสอบอย่างเป็นระบบและเป็นไปตามวัตถุประสงค์", "บริการให้คำปรึกษา เนื่องจากจัดทำรายงานอย่างเป็นทางการซึ่งบันทึกประสิทธิผลของการควบคุมการปฏิบัติงานควบคู่ไปกับข้อมูลเชิงลึกในการปรับปรุง"]$q$::jsonb, 2, $q$Correct. Assurance services are the most suitable option when an objective, formal  assessment of operational controls is required.$q$, $q$ถูกต้อง. งานบริการให้ความเชื่อมั่นเป็นทางเลือกที่เหมาะสมที่สุดเมื่อจำเป็นต้องมีการประเมินการควบคุมการปฏิบัติงานอย่างเป็นทางการตามวัตถุประสงค์$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10201', '2026', 1, 'A.5.a', $q$A financial institution reviews its internal processes to enhance  operational efficiency. What role do risk and control assessments  play in this improvement initiative?$q$, $q$สถาบันการเงินทบทวนกระบวนการภายในเพื่อเพิ่มประสิทธิภาพการดำเนินงาน การประเมินความเสี่ยงและการควบคุมมีบทบาทอย่างไรในโครงการปรับปรุงนี้$q$, $q$["They act as brief overviews that highlight potential risks without a detailed evaluation of control measures.", "They serve as systematic tools to identify potential internal control gaps in mitigating operational risks.", "They function as routine monitoring activities that record risk events without assessing existence of controls.", "They provide basic checklists that capture risks from an external perspective, omitting internal control evaluation."]$q$::jsonb, $q$["ทำหน้าที่เป็นภาพรวมโดยย่อที่เน้นความเสี่ยงที่อาจเกิดขึ้นโดยไม่ต้องมีการประเมินมาตรการควบคุมโดยละเอียด", "เป็นเครื่องมือที่เป็นระบบในการระบุช่องว่างการควบคุมภายในที่อาจเกิดขึ้นในการลดความเสี่ยงด้านการปฏิบัติงาน", "โดยทำหน้าที่เป็นกิจกรรมการตรวจสอบตามปกติซึ่งบันทึกเหตุการณ์ความเสี่ยงโดยไม่ต้องประเมินการมีอยู่ของการควบคุม", "โดยจัดให้มีรายการตรวจสอบพื้นฐานที่รวบรวมความเสี่ยงจากมุมมองภายนอก โดยไม่ต้องประเมินการควบคุมภายใน"]$q$::jsonb, 1, $q$Correct. Risk and control assessments are tools for identifying potential internal control  gaps to mitigate operational risks.$q$, $q$ถูกต้อง. การประเมินความเสี่ยงและการควบคุมเป็นเครื่องมือในการระบุช่องว่างการควบคุมภายในที่อาจเกิดขึ้นเพื่อลดความเสี่ยงในการปฏิบัติงาน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10202', '2026', 1, 'A.5.a', $q$A corporation integrates risk and control assessments to support  its continuous improvement process. How are these assessments  best described?$q$, $q$องค์กรบูรณาการการประเมินความเสี่ยงและการควบคุมเพื่อสนับสนุนกระบวนการปรับปรุงอย่างต่อเนื่อง การประเมินเหล่านี้อธิบายได้ดีที่สุดอย่างไร?$q$, $q$["They are routine audit engagements that periodically list risks without a detailed assessment of how internal controls address them.", "They are systematic evaluations that identify current and emerging risks and review the design of controls in mitigating these risks.", "They are simple risk reviews that focus on potential threats while disregarding the role of internal controls.", "They are basic assessments that document risks based on past incidents without evaluating current control measures."]$q$::jsonb, $q$["เป็นงานตรวจสอบตามปกติที่แสดงรายการความเสี่ยงเป็นระยะๆ โดยไม่มีการประเมินโดยละเอียดว่าการควบคุมภายในจัดการกับความเสี่ยงเหล่านั้นอย่างไร", "เป็นการประเมินอย่างเป็นระบบที่ระบุความเสี่ยงในปัจจุบันและที่เกิดขึ้นใหม่และทบทวนการออกแบบการควบคุมเพื่อลดความเสี่ยงเหล่านี้", "เป็นการตรวจสอบความเสี่ยงง่ายๆ ที่มุ่งเน้นไปที่ภัยคุกคามที่อาจเกิดขึ้นโดยไม่คำนึงถึงบทบาทของการควบคุมภายใน", "เป็นการประเมินขั้นพื้นฐานที่บันทึกความเสี่ยงตามเหตุการณ์ในอดีต โดยไม่ต้องประเมินมาตรการควบคุมในปัจจุบัน"]$q$::jsonb, 1, $q$Correct. Risk and control assessments are evaluations that address both current and  emerging risks and the design of internal controls.$q$, $q$ถูกต้อง. การประเมินความเสี่ยงและการควบคุมคือการประเมินที่จัดการกับความเสี่ยงทั้งในปัจจุบันและที่เกิดขึ้นใหม่และการออกแบบการควบคุมภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10203', '2026', 1, 'A.6.g', $q$During a continuous improvement initiative, how do internal  auditors contribute to process mapping?$q$, $q$ในระหว่างการริเริ่มการปรับปรุงอย่างต่อเนื่อง ผู้ตรวจสอบภายในมีส่วนช่วยในการจัดทำแผนผังกระบวนการอย่างไร$q$, $q$["They work with teams to draft process maps and ensure key risks are represented accurately.", "They focus on cost reduction by updating process maps without evaluating associated controls.", "They support the mapping initiative by collecting data and documenting process flows for review.", "They prepare process maps to identify potential control gaps and streamline processes."]$q$::jsonb, $q$["พวกเขาทำงานร่วมกับทีมเพื่อร่างแผนที่กระบวนการและรับรองว่าความเสี่ยงหลักจะแสดงอย่างถูกต้อง", "พวกเขามุ่งเน้นไปที่การลดต้นทุนโดยการอัปเดตแผนผังกระบวนการโดยไม่ต้องประเมินการควบคุมที่เกี่ยวข้อง", "พวกเขาสนับสนุนความคิดริเริ่มในการทำแผนที่โดยการรวบรวมข้อมูลและจัดทำเอกสารขั้นตอนกระบวนการเพื่อตรวจสอบ", "พวกเขาจัดเตรียมแผนผังกระบวนการเพื่อระบุช่องว่างการควบคุมที่อาจเกิดขึ้นและปรับปรุงกระบวนการ"]$q$::jsonb, 3, $q$Correct. Internal auditors prepare process maps, which help to identify potential control  gaps and also can help eliminate excessive process steps.$q$, $q$ถูกต้อง. ผู้ตรวจสอบภายในจัดทำแผนผังกระบวนการ ซึ่งช่วยระบุช่องว่างการควบคุมที่อาจเกิดขึ้น และยังช่วยขจัดขั้นตอนกระบวนการที่มากเกินไปอีกด้วย$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10204', '2026', 1, 'A.8.a', $q$When management limits internal auditors’ access to key financial  records, which scenario best demonstrates a potential impairment  of internal audit independence?$q$, $q$เมื่อฝ่ายบริหารจำกัดการเข้าถึงบันทึกทางการเงินที่สำคัญของผู้ตรวจสอบภายใน สถานการณ์ใดที่แสดงให้เห็นถึงความบกพร่องของความเป็นอิสระในการตรวจสอบภายในได้ดีที่สุด$q$, $q$["Auditors gain access to redacted records along with additional documents to maintain objectivity in their assessments.", "Auditors receive summarized data from selected channels that still allow for a reasonably independent review process.", "Restricted access forces auditors to rely on incomplete data, which can compromise their ability to form independent conclusions.", "Auditors are provided with partial information supplemented by scheduled meetings to mitigate the impact on independence."]$q$::jsonb, $q$["ผู้ตรวจสอบจะสามารถเข้าถึงบันทึกที่ปรับปรุงแล้วพร้อมกับเอกสารเพิ่มเติมเพื่อรักษาความเป็นกลางในการประเมินของตน", "ผู้ตรวจสอบจะได้รับข้อมูลสรุปจากช่องทางที่เลือกซึ่งยังคงให้กระบวนการตรวจสอบที่เป็นอิสระอย่างสมเหตุสมผล", "การเข้าถึงแบบจำกัดบังคับให้ผู้ตรวจสอบพึ่งพาข้อมูลที่ไม่สมบูรณ์ ซึ่งอาจส่งผลต่อความสามารถในการสร้างข้อสรุปที่เป็นอิสระได้", "ผู้ตรวจสอบจะได้รับข้อมูลบางส่วนเสริมด้วยการประชุมตามกำหนดเพื่อลดผลกระทบต่อความเป็นอิสระ"]$q$::jsonb, 2, $q$Correct. Limited access to complete financial records may force internal auditors to work  with insufficient data, impairing their ability to evaluate risks objectively.$q$, $q$ถูกต้อง. การเข้าถึงบันทึกทางการเงินที่สมบูรณ์อย่างจำกัดอาจบังคับให้ผู้ตรวจสอบภายในทำงานกับข้อมูลไม่เพียงพอ ส่งผลให้ความสามารถในการประเมินความเสี่ยงอย่างเป็นกลางลดลง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10205', '2026', 1, 'A.8.a', $q$In a situation where management narrows the audit scope by  excluding high‑risk areas, which scenario best reflects a threat to  internal audit independence?$q$, $q$ในสถานการณ์ที่ฝ่ายบริหารจำกัดขอบเขตการตรวจสอบให้แคบลงโดยไม่รวมส่วนที่มีความเสี่ยงสูง สถานการณ์ใดสะท้อนถึงภัยคุกคามต่อความเป็นอิสระของการตรวจสอบภายในได้ดีที่สุด$q$, $q$["A targeted scope that is adjusted based on prior risk analyses helps maintain audit focus without affecting independence.", "A carefully focused scope on preselected areas enables internal auditors to concentrate on critical risks while preserving objectivity.", "Excluding high‑risk areas can lead to biased risk assessments and an incomplete evaluation of internal controls, thereby impairing independence.", "Management's preapproval of audit areas facilitates efficient resource use and still allows for objective risk evaluations."]$q$::jsonb, $q$["ขอบเขตเป้าหมายที่ได้รับการปรับเปลี่ยนตามการวิเคราะห์ความเสี่ยงก่อนหน้าจะช่วยรักษาจุดเน้นในการตรวจสอบโดยไม่ส่งผลกระทบต่อความเป็นอิสระ", "ขอบเขตที่มุ่งเน้นอย่างระมัดระวังในพื้นที่ที่เลือกไว้ล่วงหน้าช่วยให้ผู้ตรวจสอบภายในมุ่งเน้นไปที่ความเสี่ยงที่สำคัญในขณะที่ยังคงรักษาความเป็นกลางไว้ได้", "การยกเว้นพื้นที่ที่มีความเสี่ยงสูงอาจนำไปสู่การประเมินความเสี่ยงที่มีอคติและการประเมินการควบคุมภายในที่ไม่สมบูรณ์ ส่งผลให้ความเป็นอิสระลดลง", "การอนุมัติพื้นที่การตรวจสอบล่วงหน้าของฝ่ายบริหารช่วยอำนวยความสะดวกในการใช้ทรัพยากรอย่างมีประสิทธิภาพ และยังคงช่วยให้สามารถประเมินความเสี่ยงตามวัตถุประสงค์ได้"]$q$::jsonb, 2, $q$Correct. Excluding high‑risk areas results in an incomplete risk assessment that may  compromise the objectivity of internal audit conclusions.$q$, $q$ถูกต้อง. การยกเว้นพื้นที่ที่มีความเสี่ยงสูงส่งผลให้การประเมินความเสี่ยงไม่สมบูรณ์ ซึ่งอาจกระทบต่อความเที่ยงธรรมของข้อสรุปการตรวจสอบภายใน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10206', '2026', 1, 'A.8.a', $q$When geographical limitations prevent internal auditors from on- site reviews of subsidiary operations, which scenario best  demonstrates a risk to audit independence?$q$, $q$เมื่อข้อจำกัดทางภูมิศาสตร์ทำให้ผู้ตรวจสอบภายในไม่สามารถตรวจสอบการปฏิบัติงานย่อย ณ สถานที่ได้ สถานการณ์ใดที่แสดงให้เห็นถึงความเสี่ยงในการตรวจสอบความเป็นอิสระได้ดีที่สุด$q$, $q$["Technological solutions enable auditors to remotely access subsidiary data, preserving the integrity of their independent analysis.", "Remote data collection methods allow auditors to include subsidiary information, thereby supporting independent assessments.", "Auditors incorporate third‑party reports to compensate for limited on- site reviews while still achieving objective evaluations.", "Excluding subsidiary operations may result in incomplete risk assessments that impair the overall objectivity of the internal audit function."]$q$::jsonb, $q$["โซลูชันทางเทคโนโลยีช่วยให้ผู้ตรวจสอบสามารถเข้าถึงข้อมูลย่อยจากระยะไกล โดยรักษาความสมบูรณ์ของการวิเคราะห์ที่เป็นอิสระ", "วิธีการรวบรวมข้อมูลระยะไกลช่วยให้ผู้ตรวจสอบรวมข้อมูลย่อยได้ จึงสนับสนุนการประเมินโดยอิสระ", "ผู้ตรวจสอบรวมรายงานของบุคคลที่สามเพื่อชดเชยการตรวจสอบในสถานที่ที่จำกัด ในขณะที่ยังคงบรรลุการประเมินตามวัตถุประสงค์", "การไม่รวมการดำเนินงานในเครืออาจส่งผลให้การประเมินความเสี่ยงไม่สมบูรณ์ ซึ่งบั่นทอนความเที่ยงธรรมโดยรวมของหน่วยงานตรวจสอบภายใน"]$q$::jsonb, 3, $q$Correct. Excluding subsidiary operations due to geographical restrictions can lead to  incomplete evaluations, which may impair audit independence.$q$, $q$ถูกต้อง. การยกเว้นการดำเนินงานของบริษัทในเครือเนื่องจากข้อจำกัดทางภูมิศาสตร์อาจทำให้การประเมินไม่สมบูรณ์ ซึ่งอาจบั่นทอนความเป็นอิสระในการตรวจสอบ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10207', '2026', 1, 'A.8.b', $q$In a government agency, if internal auditors are denied access to  certain classified documents, which scenario best reflects a  potential impairment of independence?$q$, $q$ในหน่วยงานของรัฐ หากผู้ตรวจสอบภายในถูกปฏิเสธไม่ให้เข้าถึงเอกสารลับบางประเภท สถานการณ์ใดที่สะท้อนถึงความบกพร่องด้านความเป็นอิสระได้ดีที่สุด$q$, $q$["Auditors receive summarized classified data that, when combined with other sources, allows for an independent evaluation process.", "Auditors work with redacted versions of documents, which still provide some detail to support independent reviews.", "Temporary restrictions are managed through periodic briefings from security personnel that help maintain audit objectivity.", "Inability to access classified documents forces auditors to rely on incomplete information, undermining the objectivity of their evaluations."]$q$::jsonb, $q$["ผู้ตรวจสอบจะได้รับข้อมูลสรุปที่จัดประเภทซึ่งเมื่อรวมกับแหล่งข้อมูลอื่น จะช่วยให้สามารถประเมินผลได้โดยอิสระ", "ผู้ตรวจสอบทำงานกับเอกสารเวอร์ชันแก้ไข ซึ่งยังคงให้รายละเอียดบางส่วนเพื่อสนับสนุนการตรวจสอบโดยอิสระ", "ข้อจำกัดชั่วคราวได้รับการจัดการผ่านการบรรยายสรุปเป็นระยะจากเจ้าหน้าที่รักษาความปลอดภัย ซึ่งช่วยรักษาความเที่ยงธรรมในการตรวจสอบ", "การไม่สามารถเข้าถึงเอกสารลับทำให้ผู้ตรวจสอบต้องพึ่งพาข้อมูลที่ไม่สมบูรณ์ ซึ่งบ่อนทำลายความเที่ยงธรรมของการประเมิน"]$q$::jsonb, 3, $q$Correct. Restricted access to classified documents can lead to incomplete information,  thereby reducing the auditors’ capacity to conduct independent assessments.$q$, $q$ถูกต้อง. การเข้าถึงเอกสารลับอย่างจำกัดอาจทำให้ข้อมูลไม่ครบถ้วน ส่งผลให้ความสามารถของผู้ตรวจสอบในการประเมินโดยอิสระลดลง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10208', '2026', 1, 'B.1.a', $q$When management restricts internal auditors’ access to  operational data critical for evaluations, which scenario best  reflects a threat to internal audit independence?$q$, $q$เมื่อฝ่ายบริหารจำกัดการเข้าถึงข้อมูลการปฏิบัติงานของผู้ตรวจสอบภายในซึ่งมีความสำคัญต่อการประเมิน สถานการณ์ใดที่สะท้อนถึงภัยคุกคามต่อความเป็นอิสระของการตรวจสอบภายในได้ดีที่สุด$q$, $q$["Restricted access to essential operational data forces auditors to draw conclusions from incomplete information, thereby compromising independence.", "Auditors supplement limited data with alternative internal sources to ensure that evaluations remain objective and comprehensive.", "Auditors obtain periodic data updates that help maintain a degree of independence despite initial access restrictions.", "Auditors use advanced analytics to integrate available data, thereby mitigating the impact of access limitations on independence."]$q$::jsonb, $q$["การเข้าถึงข้อมูลการปฏิบัติงานที่จำเป็นอย่างจำกัด ทำให้ผู้ตรวจสอบต้องสรุปผลจากข้อมูลที่ไม่สมบูรณ์ ส่งผลให้ความเป็นอิสระลดลง", "ผู้ตรวจสอบจะเสริมข้อมูลที่จำกัดด้วยแหล่งข้อมูลภายในทางเลือกเพื่อให้แน่ใจว่าการประเมินยังคงเป็นไปตามวัตถุประสงค์และครอบคลุม", "ผู้ตรวจสอบจะได้รับการอัปเดตข้อมูลเป็นระยะซึ่งช่วยรักษาระดับความเป็นอิสระแม้จะมีข้อจำกัดในการเข้าถึงในช่วงแรกก็ตาม", "ผู้ตรวจสอบใช้การวิเคราะห์ขั้นสูงเพื่อรวมข้อมูลที่มีอยู่ จึงช่วยลดผลกระทบจากการจำกัดการเข้าถึงต่อความเป็นอิสระ"]$q$::jsonb, 0, $q$Correct. Relying on incomplete operational data due to management restrictions can  undermine the independence of the internal audit function by compromising the  completeness of its assessments.$q$, $q$ถูกต้อง. การใช้ข้อมูลการปฏิบัติงานที่ไม่สมบูรณ์อันเนื่องมาจากข้อจำกัดด้านการจัดการอาจบั่นทอนความเป็นอิสระของหน่วยงานตรวจสอบภายในโดยบั่นทอนความสมบูรณ์ของการประเมิน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10209', '2026', 1, 'B.2.a', $q$Which scenario best illustrates the effect of familiarity bias on an  internal auditor's objectivity during an internal audit engagement?$q$, $q$สถานการณ์ใดแสดงให้เห็นถึงผลกระทบของอคติต่อความคุ้นเคยต่อความเที่ยงธรรมของผู้ตรวจสอบภายในระหว่างการปฏิบัติงานตรวจสอบภายในได้ดีที่สุด$q$, $q$["An auditor who repeatedly audits the same department may develop undue familiarity, limiting objectivity.", "An auditor assigned to similar departments is more likely to maintain an objective perspective.", "An auditor who periodically consults with external experts minimizes the risk of bias from familiarity.", "An auditor following established procedures without prior involvement sustains objective evaluations."]$q$::jsonb, $q$["ผู้ตรวจสอบที่ตรวจสอบแผนกเดียวกันซ้ำๆ อาจเกิดความคุ้นเคยที่ไม่เหมาะสม และจำกัดความเที่ยงธรรม", "ผู้ตรวจสอบบัญชีที่ได้รับมอบหมายให้แผนกที่คล้ายคลึงกันมีแนวโน้มที่จะรักษามุมมองที่เป็นกลางมากกว่า", "ผู้ตรวจสอบบัญชีที่ปรึกษากับผู้เชี่ยวชาญภายนอกเป็นระยะจะช่วยลดความเสี่ยงของอคติจากความคุ้นเคย", "ผู้ตรวจสอบที่ปฏิบัติตามขั้นตอนที่กำหนดไว้โดยไม่มีส่วนร่วมก่อนจะคงไว้ซึ่งการประเมินตามวัตถุประสงค์"]$q$::jsonb, 0, $q$Correct. Familiarity bias can develop from repeated exposure to the same environment,  potentially diminishing an auditor’s critical perspective.$q$, $q$ถูกต้อง. อคติต่อความคุ้นเคยสามารถเกิดขึ้นได้จากการสัมผัสกับสภาพแวดล้อมเดียวกันซ้ำๆ ซึ่งอาจส่งผลให้มุมมองเชิงวิพากษ์วิจารณ์ของผู้ตรวจสอบลดน้อยลง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10210', '2026', 1, 'B.2.a', $q$How might self-review risk and familiarity bias together impair an  internal auditor's objectivity during an internal audit engagement?$q$, $q$การประเมินความเสี่ยงด้วยตนเองและความลำเอียงของความคุ้นเคยร่วมกันอาจบั่นทอนความเที่ยงธรรมของผู้ตรวจสอบภายในในระหว่างการปฏิบัติงานการตรวจสอบภายในได้อย่างไร$q$, $q$["When an auditor follows standard protocols that include external oversight, these biases are controlled.", "When an auditor receives independent verification of their work, the combined bias is effectively reduced.", "When an auditor rotates frequently, the risk of both self-review and familiarity bias is minimized.", "When an auditor both reviews their own work and repeatedly audits the same area, objectivity may be compromised."]$q$::jsonb, $q$["เมื่อผู้ตรวจสอบปฏิบัติตามระเบียบการมาตรฐานที่มีการกำกับดูแลจากภายนอก อคติเหล่านี้จะถูกควบคุม", "เมื่อผู้ตรวจสอบได้รับการตรวจสอบการทำงานโดยอิสระ ความลำเอียงรวมก็จะลดลงอย่างมีประสิทธิภาพ", "เมื่อผู้ตรวจสอบหมุนเวียนบ่อยครั้ง ความเสี่ยงของทั้งการตรวจสอบตนเองและความลำเอียงด้านความคุ้นเคยจะลดลง", "เมื่อผู้ตรวจสอบตรวจสอบทั้งงานของตนเองและตรวจสอบซ้ำๆ ในพื้นที่เดียวกัน ความเที่ยงธรรมอาจถูกกระทบกระเทือน"]$q$::jsonb, 3, $q$Correct. Combining self-review with repeated exposure to the same environment can  undermine an auditor's impartiality.$q$, $q$ถูกต้อง. การรวมการตรวจสอบตนเองเข้ากับการสัมผัสสภาพแวดล้อมเดียวกันซ้ำๆ อาจบ่อนทำลายความเป็นกลางของผู้ตรวจสอบบัญชี$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10211', '2026', 1, 'B.2.a', $q$In evaluating an internal auditor's objectivity, which circumstance  may indicate the presence of self-review bias?$q$, $q$ในการประเมินความเที่ยงธรรมของผู้ตรวจสอบภายใน สถานการณ์ใดที่อาจบ่งชี้ถึงความลำเอียงในการตรวจสอบตนเอง$q$, $q$["An auditor incorporating external feedback into prior analyses demonstrates a reduction in self-review risk.", "An auditor working on new areas with no prior involvement indicates minimal risk of self-review bias.", "An auditor reviewing work they originally authored, potentially showing reluctance to identify errors, suggests self-review bias.", "An auditor utilizing peer review methods along with independent evaluations helps ensure objectivity."]$q$::jsonb, $q$["ผู้ตรวจสอบที่รวมผลตอบรับจากภายนอกไว้ในการวิเคราะห์ก่อนหน้านี้ แสดงให้เห็นว่าการลดความเสี่ยงในการตรวจสอบตนเองลดลง", "ผู้ตรวจสอบที่ทำงานในพื้นที่ใหม่โดยไม่มีส่วนร่วมมาก่อนบ่งชี้ว่ามีความเสี่ยงน้อยที่สุดที่จะเกิดอคติในการตรวจสอบตนเอง", "ผู้ตรวจสอบตรวจสอบงานที่พวกเขาเขียนขึ้นแต่แรก ซึ่งอาจแสดงความไม่เต็มใจที่จะระบุข้อผิดพลาด แสดงให้เห็นอคติในการตรวจสอบตนเอง", "ผู้ตรวจสอบที่ใช้วิธีการทบทวนโดยผู้ทรงคุณวุฒิพร้อมกับการประเมินที่เป็นอิสระช่วยให้มั่นใจในความเป็นกลาง"]$q$::jsonb, 2, $q$Correct. When auditors review their own prior work, it may lead to self-review bias,  reducing the ability to assess findings objectively.$q$, $q$ถูกต้อง. เมื่อผู้ตรวจสอบตรวจสอบงานก่อนหน้าของตนเอง อาจนำไปสู่อคติในการตรวจสอบตนเอง ส่งผลให้ความสามารถในการประเมินผลการค้นพบอย่างเป็นกลางลดลง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10212', '2026', 1, 'B.2.b', $q$In a situation where management narrows the audit scope by  excluding high‑risk areas, which scenario best reflects a threat to  audit independence?$q$, $q$ในสถานการณ์ที่ฝ่ายบริหารจำกัดขอบเขตการตรวจสอบให้แคบลงโดยไม่รวมส่วนที่มีความเสี่ยงสูง สถานการณ์ใดสะท้อนถึงภัยคุกคามต่อความเป็นอิสระของการตรวจสอบได้ดีที่สุด$q$, $q$["Excluding high‑risk areas results in incomplete risk assessments that may significantly bias the auditors’ final conclusions, thus undermining overall audit independence.", "Narrowing the audit scope solely to preapproved areas can limit exposure to significant risks while generally maintaining overall objectivity in evaluations.", "A focused audit scope that emphasizes selected areas can enhance efficiency and does not impair the independence of the audit process.", "Preapproval of audit areas by management may streamline the overall process but risks unintentionally omitting key high‑risk segments, without compromising independence."]$q$::jsonb, $q$["การยกเว้นพื้นที่ที่มีความเสี่ยงสูงส่งผลให้มีการประเมินความเสี่ยงที่ไม่สมบูรณ์ ซึ่งอาจทำให้ข้อสรุปของผู้ตรวจสอบมีอคติอย่างมีนัยสำคัญ ซึ่งบั่นทอนความเป็นอิสระในการตรวจสอบโดยรวม", "การลดขอบเขตการตรวจสอบให้แคบลงเฉพาะในพื้นที่ที่ได้รับการอนุมัติล่วงหน้าสามารถจำกัดความเสี่ยงที่สำคัญได้ ในขณะที่ยังคงรักษาความเที่ยงธรรมโดยรวมในการประเมินไว้", "ขอบเขตการตรวจสอบที่มุ่งเน้นซึ่งเน้นเฉพาะด้านที่เลือกสามารถเพิ่มประสิทธิภาพและไม่ทำให้ความเป็นอิสระของกระบวนการตรวจสอบลดลง", "การอนุมัติขอบเขตการตรวจสอบล่วงหน้าโดยฝ่ายบริหารอาจช่วยปรับปรุงกระบวนการโดยรวมได้ แต่มีความเสี่ยงที่จะละเว้นส่วนที่มีความเสี่ยงสูงที่สำคัญโดยไม่ได้ตั้งใจ โดยไม่กระทบต่อความเป็นอิสระ"]$q$::jsonb, 0, $q$Correct. Excluding high‑risk areas leads to incomplete assessments that may  significantly bias conclusions and impair audit independence.$q$, $q$ถูกต้อง. การยกเว้นพื้นที่ที่มีความเสี่ยงสูงนำไปสู่การประเมินที่ไม่สมบูรณ์ ซึ่งอาจทำให้ข้อสรุปมีอคติอย่างมีนัยสำคัญ และทำให้ความเป็นอิสระในการตรวจสอบลดลง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10213', '2026', 1, 'B.2.b', $q$When internal auditors are denied access to key management  systems for data analysis, which scenario best represents a risk to  audit independence?$q$, $q$เมื่อผู้ตรวจสอบภายในถูกปฏิเสธไม่ให้เข้าถึงระบบการจัดการที่สำคัญสำหรับการวิเคราะห์ข้อมูล สถานการณ์ใดที่แสดงถึงความเสี่ยงต่อความเป็นอิสระของการตรวจสอบได้ดีที่สุด$q$, $q$["Denied access forces auditors to rely on partial system data, reducing their ability to perform fully independent evaluations of internal controls.", "Auditors may use multiple reliable alternative data sources to supplement system information, thereby preserving their overall independence during the evaluation process.", "Auditors receive periodic updates from critical key systems that partly mitigate the effects of restricted access while still allowing independent analysis.", "Auditors routinely use external independent verification to obtain missing system data, which helps them achieve a largely independent evaluation of controls."]$q$::jsonb, $q$["การเข้าถึงที่ถูกปฏิเสธบังคับให้ผู้ตรวจสอบต้องพึ่งพาข้อมูลระบบบางส่วน ส่งผลให้ความสามารถในการประเมินการควบคุมภายในโดยอิสระอย่างเต็มที่ลดลง", "ผู้ตรวจสอบอาจใช้แหล่งข้อมูลทางเลือกที่เชื่อถือได้หลายแหล่งเพื่อเสริมข้อมูลระบบ ดังนั้นจึงรักษาความเป็นอิสระโดยรวมในระหว่างกระบวนการประเมิน", "ผู้ตรวจสอบจะได้รับการอัปเดตเป็นระยะจากระบบคีย์ที่สำคัญซึ่งช่วยลดผลกระทบบางส่วนจากการเข้าถึงแบบจำกัด ในขณะที่ยังคงให้การวิเคราะห์ที่เป็นอิสระ", "ผู้ตรวจสอบใช้การตรวจสอบอิสระจากภายนอกเป็นประจำเพื่อให้ได้ข้อมูลระบบที่ขาดหายไป ซึ่งช่วยให้พวกเขาบรรลุการประเมินการควบคุมที่เป็นอิสระส่วนใหญ่"]$q$::jsonb, 0, $q$Correct. Limited access to key management systems compels reliance on partial data,  which undermines the independence of evaluations.$q$, $q$ถูกต้อง. การเข้าถึงระบบการจัดการหลักอย่างจำกัดส่งผลให้ต้องพึ่งพาข้อมูลบางส่วน ซึ่งบ่อนทำลายความเป็นอิสระของการประเมิน$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10214', '2026', 1, 'B.2.b', $q$When management restricts internal auditors from interviewing key  personnel, which scenario best illustrates a potential threat to  independence?$q$, $q$เมื่อฝ่ายบริหารจำกัดผู้ตรวจสอบภายในไม่ให้สัมภาษณ์บุคลากรสำคัญ เหตุการณ์ใดที่แสดงให้เห็นถึงภัยคุกคามต่อความเป็นอิสระได้ดีที่สุด$q$, $q$["Limiting direct interviews with key personnel severely restricts access to essential insights, thereby reducing the auditors’ ability to conduct independent evaluations.", "Auditors effectively substitute restricted interviews with thorough, comprehensive document reviews to gather required information while maintaining their independence throughout the process.", "Auditors routinely obtain indirect input from alternative communication channels that can partially compensate for the restricted access to key personnel interviews.", "Auditors routinely employ structured questionnaires to capture essential insights when direct interviews are restricted, thereby preserving the independence of their evaluations."]$q$::jsonb, $q$["การจำกัดการสัมภาษณ์โดยตรงกับบุคลากรสำคัญเป็นการจำกัดการเข้าถึงข้อมูลเชิงลึกที่สำคัญอย่างรุนแรง ดังนั้นจึงลดความสามารถของผู้ตรวจสอบในการดำเนินการประเมินผลโดยอิสระ", "ผู้ตรวจสอบจะแทนที่การสัมภาษณ์แบบจำกัดด้วยการตรวจสอบเอกสารที่ครอบคลุมและละเอียดถี่ถ้วนอย่างมีประสิทธิภาพ เพื่อรวบรวมข้อมูลที่จำเป็นโดยยังคงรักษาความเป็นอิสระตลอดกระบวนการ", "ผู้ตรวจสอบจะได้รับข้อมูลทางอ้อมจากช่องทางการสื่อสารทางเลือกเป็นประจำ ซึ่งสามารถชดเชยบางส่วนจากการจำกัดการเข้าถึงการสัมภาษณ์บุคลากรสำคัญ", "ผู้ตรวจสอบจะใช้แบบสอบถามที่มีโครงสร้างเป็นประจำเพื่อรวบรวมข้อมูลเชิงลึกที่จำเป็นเมื่อมีการจำกัดการสัมภาษณ์โดยตรง ดังนั้นจึงรักษาความเป็นอิสระในการประเมินของพวกเขา"]$q$::jsonb, 0, $q$Correct. Restricting direct interviews with key personnel can severely limit access to  essential insights, reducing the ability to evaluate objectively.$q$, $q$ถูกต้อง. การจำกัดการสัมภาษณ์โดยตรงกับบุคลากรหลักสามารถจำกัดการเข้าถึงข้อมูลเชิงลึกที่จำเป็นอย่างรุนแรง ส่งผลให้ความสามารถในการประเมินอย่างเป็นกลางลดลง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10215', '2026', 1, 'B.2.b', $q$When an internal auditor has recently been employed in a  department the auditor now reviews, which scenario best  indicates a risk to objectivity?$q$, $q$เมื่อผู้ตรวจสอบภายในเพิ่งได้รับการว่าจ้างในแผนก ผู้ตรวจสอบจะตรวจสอบ สถานการณ์ใดที่บ่งบอกถึงความเสี่ยงต่อความเป็นกลางได้ดีที่สุด$q$, $q$["An auditor who fully discloses prior employment minimizes the risk of impaired objectivity effectively.", "An auditor with no prior employment in the department under review consistently maintains a neutral stance and objective judgment throughout the audit engagement.", "An auditor recently employed in the department under review may experience lingering personal loyalties that adversely affect impartial judgment during evaluations.", "An auditor assigned to a different unit from their former department avoids conflicts and maintains independent judgment throughout the audit process."]$q$::jsonb, $q$["ผู้ตรวจสอบบัญชีที่เปิดเผยการจ้างงานก่อนหน้าอย่างครบถ้วนช่วยลดความเสี่ยงของความเป็นกลางที่บกพร่องได้อย่างมีประสิทธิภาพ", "ผู้ตรวจสอบที่ไม่มีการจ้างงานในแผนกที่อยู่ระหว่างการสอบทานจะต้องรักษาจุดยืนที่เป็นกลางและวิจารณญาณอย่างเป็นกลางตลอดการปฏิบัติงานตรวจสอบ", "ผู้ตรวจสอบบัญชีที่เพิ่งได้รับการว่าจ้างในแผนกที่อยู่ระหว่างการสอบทานอาจประสบกับความภักดีส่วนบุคคลที่ยืดเยื้อ ซึ่งส่งผลเสียต่อวิจารณญาณที่เป็นกลางในระหว่างการประเมิน", "ผู้ตรวจสอบที่ได้รับมอบหมายไปยังหน่วยงานอื่นจากแผนกเดิมจะหลีกเลี่ยงความขัดแย้งและรักษาดุลยพินิจที่เป็นอิสระตลอดกระบวนการตรวจสอบ"]$q$::jsonb, 2, $q$Correct. Recent employment in a department under review may result in lingering  personal loyalties that adversely affect impartial judgment.$q$, $q$ถูกต้อง. การจ้างงานล่าสุดในแผนกที่อยู่ระหว่างการพิจารณาอาจส่งผลให้เกิดความภักดีส่วนบุคคลที่ยืดเยื้อซึ่งส่งผลเสียต่อวิจารณญาณที่เป็นกลาง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10216', '2026', 1, 'B.3.a', $q$In an internal audit policy, which measure best mitigates  impairments to objectivity when an internal auditor is repeatedly  assigned to the same business area?$q$, $q$ในนโยบายการตรวจสอบภายใน ข้อใดจะวัดได้ดีที่สุดในการบรรเทาความบกพร่องของความเป็นกลาง เมื่อผู้ตรวจสอบภายในถูกมอบหมายซ้ำๆ ให้กับกลุ่มธุรกิจเดียวกัน$q$, $q$["Periodically reassigning auditors to different areas to minimize familiarity and biased judgement.", "Increasing oversight and supervision without changing the auditor's assignment to the same area.", "Enhancing ethical training while maintaining long-term assignments in the same business area.", "Mandating additional documentation of potential conflicts while keeping consistent assignments in that area."]$q$::jsonb, $q$["มอบหมายผู้ตรวจสอบใหม่ไปยังพื้นที่ต่างๆ เป็นระยะเพื่อลดความคุ้นเคยและการตัดสินที่มีอคติ", "เพิ่มการกำกับดูแลและกำกับดูแลโดยไม่เปลี่ยนการมอบหมายงานของผู้สอบบัญชีให้อยู่ในขอบเขตเดิม", "ส่งเสริมการฝึกอบรมด้านจริยธรรมโดยยังคงรักษาการมอบหมายงานระยะยาวในด้านธุรกิจเดียวกัน", "จัดทำเอกสารเพิ่มเติมเกี่ยวกับความขัดแย้งที่อาจเกิดขึ้นในขณะเดียวกันก็รักษาการมอบหมายที่สอดคล้องกันในพื้นที่นั้น"]$q$::jsonb, 0, $q$Correct. Periodic reassignment reduces familiarity and bias risks by exposing auditors to  diverse areas.$q$, $q$ถูกต้อง. การมอบหมายงานใหม่เป็นระยะจะช่วยลดความเสี่ยงจากความคุ้นเคยและอคติโดยทำให้ผู้ตรวจสอบได้สัมผัสกับพื้นที่ที่หลากหลาย$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10217', '2026', 1, 'B.3.a', $q$In a situation where an internal auditor's objectivity is at risk due to  prolonged exposure to the same business area, which policy  measure is most effective?$q$, $q$ในสถานการณ์ที่ความเที่ยงธรรมของผู้ตรวจสอบภายในตกอยู่ในความเสี่ยงเนื่องจากการอยู่ในธุรกิจเดียวกันเป็นเวลานาน มาตรการนโยบายใดมีประสิทธิผลมากที่สุด$q$, $q$["Instituting a dual-review process for audit engagements in that business area while keeping the same assignment.", "Reassigning the auditor to a different, unrelated business area to break the cycle of familiarity bias.", "Scheduling periodic independent reviews of the auditor’s work without changing the assignment.", "Implementing mandatory conflict disclosures and enhanced monitoring while maintaining the current business area assignment."]$q$::jsonb, $q$["จัดทำกระบวนการตรวจสอบแบบคู่สำหรับการตรวจสอบในพื้นที่ธุรกิจนั้นโดยยังคงได้รับมอบหมายเดิม", "มอบหมายผู้ตรวจสอบใหม่ไปยังพื้นที่ธุรกิจอื่นที่ไม่เกี่ยวข้องเพื่อทำลายวงจรของอคติด้านความคุ้นเคย", "กำหนดเวลาการตรวจสอบงานของผู้สอบบัญชีอย่างเป็นอิสระเป็นระยะๆ โดยไม่ต้องเปลี่ยนงานมอบหมาย", "การดำเนินการเปิดเผยข้อขัดแย้งที่จำเป็นและการตรวจสอบที่ได้รับการปรับปรุงในขณะที่ยังคงรักษาการมอบหมายพื้นที่ธุรกิจในปัจจุบัน"]$q$::jsonb, 1, $q$Correct. Reassigning the auditor to a different risk area directly addresses self-review  bias and supports objectivity.$q$, $q$ถูกต้อง. การกำหนดผู้ตรวจสอบใหม่ไปยังพื้นที่ความเสี่ยงอื่นจะแก้ไขอคติในการตรวจสอบตนเองโดยตรงและสนับสนุนความเที่ยงธรรม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10218', '2026', 1, 'B.3.a', $q$In a scenario where an internal auditor’s long-term assignment to  a specific operational area raises concerns of self-review bias,  which policy option would best mitigate this risk?$q$, $q$ในสถานการณ์ที่การมอบหมายงานระยะยาวของผู้ตรวจสอบภายในไปยังพื้นที่ปฏิบัติงานเฉพาะทำให้เกิดความกังวลเรื่องอคติในการตรวจสอบตนเอง ทางเลือกนโยบายใดที่จะลดความเสี่ยงนี้ได้ดีที่สุด$q$, $q$["Scheduling more frequent audit engagements in the same area to balance out potential biases with additional oversight.", "Introducing a formal peer review process while allowing the auditor to continue in the same area.", "Increasing the auditor’s training in objectivity while retaining the current assignment for consistency.", "Reassigning the auditor to a different operational activity to avoid self-review and maintain independent evaluation."]$q$::jsonb, $q$["กำหนดเวลาการตรวจสอบให้บ่อยขึ้นในพื้นที่เดียวกันเพื่อสร้างสมดุลระหว่างอคติที่อาจเกิดขึ้นกับการควบคุมดูแลเพิ่มเติม", "แนะนำกระบวนการตรวจสอบโดยผู้ทรงคุณวุฒิอย่างเป็นทางการในขณะที่อนุญาตให้ผู้ตรวจสอบสามารถดำเนินการต่อในด้านเดียวกันได้", "เพิ่มการฝึกอบรมผู้ตรวจสอบในเรื่องความเป็นกลางโดยยังคงรักษางานที่ได้รับมอบหมายในปัจจุบันเพื่อความสม่ำเสมอ", "มอบหมายผู้ตรวจสอบใหม่ให้กับกิจกรรมการปฏิบัติงานอื่นเพื่อหลีกเลี่ยงการตรวจสอบตนเองและรักษาการประเมินผลที่เป็นอิสระ"]$q$::jsonb, 3, $q$Correct. Reassigning the auditor to a different activity is a direct method to prevent self- review bias and ensure independent evaluations.$q$, $q$ถูกต้อง. การมอบหมายผู้ตรวจสอบใหม่ให้กับกิจกรรมอื่นเป็นวิธีการโดยตรงในการป้องกันอคติในการตรวจสอบตนเองและรับรองการประเมินที่เป็นอิสระ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10219', '2026', 1, 'B.3.b', $q$In a scenario where internal auditing faces persistent self-review  and familiarity risks on a recurring audit engagement, which  option best supports promoting objectivity?$q$, $q$ในสถานการณ์ที่การตรวจสอบภายในเผชิญกับการตรวจสอบตนเองอย่างต่อเนื่องและความเสี่ยงในการทำความคุ้นเคยในการตรวจสอบที่เกิดขึ้นเป็นประจำ ตัวเลือกใดที่สนับสนุนการส่งเสริมความเป็นกลางได้ดีที่สุด$q$, $q$["Instituting an internal peer review system to provide checks on the auditor’s work while keeping the engagement in-house.", "Rotating internal auditors more frequently to reduce exposure to the same processes and potential self- review.", "Outsourcing the engagement’s performance or supervision to an independent, external provider to break the cycle of bias.", "Enhancing internal quality controls and increasing supervision from senior audit management to address potential biases."]$q$::jsonb, $q$["จัดทำระบบ peer review ภายในเพื่อตรวจสอบงานของผู้ตรวจสอบบัญชีในขณะที่ยังคงการมีส่วนร่วมภายในองค์กร", "หมุนเวียนผู้ตรวจสอบภายในบ่อยขึ้นเพื่อลดความเสี่ยงต่อกระบวนการเดียวกันและการตรวจสอบตนเองที่อาจเกิดขึ้น", "จ้างผู้ให้บริการภายนอกเพื่อการปฏิบัติงานหรือการกำกับดูแลให้กับผู้ให้บริการอิสระภายนอกเพื่อทำลายวงจรอคติ", "ปรับปรุงการควบคุมคุณภาพภายในและเพิ่มการกำกับดูแลจากผู้บริหารการตรวจสอบอาวุโสเพื่อแก้ไขอคติที่อาจเกิดขึ้น"]$q$::jsonb, 2, $q$Correct. Outsourcing performance or supervision to an external provider effectively  removes self-review and familiarity risks, thus promoting objectivity.$q$, $q$ถูกต้อง. การจ้างการปฏิบัติงานหรือการกำกับดูแลจากภายนอกให้กับผู้ให้บริการภายนอกช่วยขจัดความเสี่ยงในการตรวจสอบตนเองและคุ้นเคยได้อย่างมีประสิทธิภาพ ซึ่งจะช่วยส่งเสริมความเป็นกลาง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10220', '2026', 1, 'B.3.d', $q$When an internal auditor is offered a gift during an audit  engagement, which process best supports objectivity?$q$, $q$เมื่อผู้ตรวจสอบภายในได้รับของขวัญในระหว่างการปฏิบัติงานตรวจสอบ กระบวนการใดสนับสนุนความเป็นกลางได้ดีที่สุด$q$, $q$["Following established guidelines to respectfully decline the gift and report the offer.", "Accepting the gift after verifying its nominal value and reporting it.", "Consulting with a supervisor before accepting the gift and documenting the interaction.", "Evaluating the gift’s potential impact on independence and seeking peer input."]$q$::jsonb, $q$["ปฏิบัติตามแนวทางที่กำหนดไว้ในการปฏิเสธของขวัญด้วยความเคารพและรายงานข้อเสนอ", "การรับของขวัญหลังจากตรวจสอบมูลค่าที่ระบุและรายงานแล้ว", "ปรึกษากับหัวหน้างานก่อนรับของขวัญและบันทึกการโต้ตอบ", "การประเมินผลกระทบที่อาจเกิดขึ้นของของขวัญต่อความเป็นอิสระและการแสวงหาความคิดเห็นจากเพื่อน"]$q$::jsonb, 0, $q$Correct. Declining the gift and reporting the offer in line with policy safeguards objectivity  by preventing conflicts of interest.$q$, $q$ถูกต้อง. การปฏิเสธของขวัญและการรายงานข้อเสนอตามนโยบายจะปกป้องความเป็นกลางโดยการป้องกันความขัดแย้งทางผลประโยชน์$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10221', '2026', 1, 'B.3.d', $q$Which option best promotes objectivity when an internal auditor is  offered a reward from management of the activity under review?$q$, $q$ตัวเลือกใดที่ส่งเสริมความเป็นกลางได้ดีที่สุดเมื่อผู้ตรวจสอบภายในได้รับรางวัลจากฝ่ายบริหารของกิจกรรมที่อยู่ระหว่างการตรวจสอบ$q$, $q$["Consulting with the audit committee about the reward prior to acceptance.", "Accepting the reward only if it falls under a nominal value threshold and reporting it.", "Declining the reward and documenting the refusal as required by policy.", "Requesting a deferment of the reward decision until after the engagement."]$q$::jsonb, $q$["ปรึกษากับคณะกรรมการตรวจสอบเกี่ยวกับรางวัลก่อนรับมอบ", "การรับรางวัลเฉพาะในกรณีที่อยู่ภายใต้เกณฑ์มูลค่าที่กำหนดและรายงานรางวัล", "การปฏิเสธรางวัลและบันทึกการปฏิเสธตามที่นโยบายกำหนด", "ขอเลื่อนการพิจารณาการให้รางวัลออกไปจนกว่าจะเสร็จสิ้นการสู้รบ"]$q$::jsonb, 2, $q$Correct. Declining the reward and documenting the refusal ensures that objectivity is  maintained by avoiding potential bias.$q$, $q$ถูกต้อง. การปฏิเสธการให้รางวัลและการบันทึกการปฏิเสธจะทำให้แน่ใจได้ว่าการรักษาความเป็นกลางจะคงอยู่โดยการหลีกเลี่ยงอคติที่อาจเกิดขึ้น$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10222', '2026', 1, 'B.3.d', $q$When an internal auditor faces an offer of a gift that might impair  independence, which measure best mitigates potential bias?$q$, $q$เมื่อผู้ตรวจสอบภายในเผชิญกับข้อเสนอของขวัญที่อาจบั่นทอนความเป็นอิสระ ข้อใดจะช่วยลดอคติที่อาจเกิดขึ้นได้ดีที่สุด$q$, $q$["Adhering to a policy of declining the gift and reporting it immediately ensures that objectivity is maintained.", "Accepting the gift after confirming its minimal value and then recording it may mitigate bias.", "Seeking a formal review of the gift’s implications by an ethics committee before acceptance supports objectivity.", "Requesting additional guidance from a peer review process to decide on the gift may help mitigate bias."]$q$::jsonb, $q$["การปฏิบัติตามนโยบายการปฏิเสธของขวัญและการรายงานทันทีจะช่วยให้มั่นใจได้ว่าจะรักษาความเป็นกลางไว้", "การรับของขวัญหลังจากยืนยันมูลค่าขั้นต่ำแล้วบันทึกของขวัญอาจช่วยลดอคติได้", "การขอการตรวจสอบอย่างเป็นทางการเกี่ยวกับผลกระทบของของขวัญโดยคณะกรรมการจริยธรรมก่อนที่จะยอมรับจะสนับสนุนความเป็นกลาง", "การขอคำแนะนำเพิ่มเติมจากกระบวนการพิจารณาโดยผู้ทรงคุณวุฒิเพื่อตัดสินใจเกี่ยวกับของขวัญอาจช่วยลดอคติได้"]$q$::jsonb, 0, $q$Correct. Following a strict policy to decline and report any such offers prevents conflicts  of interest and maintains objectivity.$q$, $q$ถูกต้อง. การปฏิบัติตามนโยบายที่เข้มงวดในการปฏิเสธและรายงานข้อเสนอดังกล่าวจะช่วยป้องกันความขัดแย้งทางผลประโยชน์และรักษาความเป็นกลาง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10223', '2026', 1, 'B.3.d', $q$Which measure most effectively addresses potential impairments  from receiving rewards in an audit context?$q$, $q$มาตรการใดจัดการกับความบกพร่องที่อาจเกิดขึ้นจากการได้รับรางวัลในบริบทการตรวจสอบได้อย่างมีประสิทธิภาพมากที่สุด$q$, $q$["Implementing a threshold policy that permits small rewards while mandating disclosure contributes to objectivity.", "Maintaining a policy that requires internal auditors to refuse any reward and report the offer without exception supports objectivity.", "Establishing a procedure for consulting with management before accepting any reward helps sustain objectivity.", "Utilizing a process where rewards are evaluated by an independent committee before acceptance supports objectivity."]$q$::jsonb, $q$["การใช้นโยบายเกณฑ์ที่อนุญาตให้ได้รับรางวัลเล็กน้อยในขณะที่การบังคับเปิดเผยจะก่อให้เกิดความเป็นกลาง", "การรักษานโยบายที่กำหนดให้ผู้ตรวจสอบภายในปฏิเสธการให้รางวัลใดๆ และรายงานข้อเสนอโดยไม่มีข้อยกเว้นจะสนับสนุนความเที่ยงธรรม", "การสร้างขั้นตอนการปรึกษาหารือกับฝ่ายบริหารก่อนรับรางวัลใดๆ จะช่วยรักษาความเป็นกลางไว้ได้", "การใช้กระบวนการประเมินรางวัลโดยคณะกรรมการอิสระก่อนการยอมรับจะสนับสนุนความเป็นกลาง"]$q$::jsonb, 1, $q$Correct. A policy that requires refusal and prompt reporting of rewards prevents conflicts  of interest and preserves the auditor’s independent judgment.$q$, $q$ถูกต้อง. นโยบายที่กำหนดให้มีการปฏิเสธและการรายงานรางวัลทันทีจะช่วยป้องกันความขัดแย้งทางผลประโยชน์และรักษาวิจารณญาณที่เป็นอิสระของผู้สอบบัญชี$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10224', '2026', 1, 'B.4.a', $q$During a high-level meeting, an internal auditor must present key  risk findings to senior leadership. How should the auditor apply  verbal communication skills for effective delivery?$q$, $q$ในระหว่างการประชุมระดับสูง ผู้ตรวจสอบภายในต้องนำเสนอข้อค้นพบความเสี่ยงที่สำคัญต่อผู้นำระดับสูง ผู้ตรวจสอบควรใช้ทักษะการสื่อสารด้วยวาจาเพื่อการส่งมอบที่มีประสิทธิภาพอย่างไร$q$, $q$["By using technical terminology without simplifying concepts for nonspecialists.", "By reading the report to ensure no information is omitted.", "By using a structured approach that emphasizes major risk points with clear explanations and relevant examples.", "By giving background details with less emphasis on the core risk findings during the presentation."]$q$::jsonb, $q$["โดยใช้คำศัพท์ทางเทคนิคโดยไม่ลดความซับซ้อนของแนวคิดสำหรับผู้ที่ไม่ใช่ผู้เชี่ยวชาญ", "โดยการอ่านรายงานเพื่อให้แน่ใจว่าไม่มีการละเว้นข้อมูล", "โดยใช้แนวทางที่มีโครงสร้างซึ่งเน้นประเด็นความเสี่ยงหลักพร้อมคำอธิบายที่ชัดเจนและตัวอย่างที่เกี่ยวข้อง", "โดยให้รายละเอียดความเป็นมาโดยไม่เน้นไปที่การค้นพบความเสี่ยงหลักในระหว่างการนำเสนอ"]$q$::jsonb, 2, $q$Correct. A structured presentation that highlights major risks with clear explanations and  examples ensures the message is effectively conveyed.$q$, $q$ถูกต้อง. การนำเสนอที่มีโครงสร้างซึ่งเน้นย้ำถึงความเสี่ยงที่สำคัญพร้อมคำอธิบายและตัวอย่างที่ชัดเจน ช่วยให้มั่นใจว่าข้อความจะถูกถ่ายทอดอย่างมีประสิทธิภาพ$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10225', '2026', 1, 'B.4.a', $q$When participating in a team meeting, an internal auditor needs to  share updates on audit progress. Which approach best  demonstrates effective verbal communication skills?$q$, $q$เมื่อเข้าร่วมการประชุมทีม ผู้ตรวจสอบภายในจำเป็นต้องแจ้งข้อมูลอัปเดตเกี่ยวกับความคืบหน้าในการตรวจสอบ แนวทางใดแสดงให้เห็นถึงทักษะการสื่อสารด้วยวาจาที่มีประสิทธิภาพได้ดีที่สุด$q$, $q$["Clearly articulating progress, summarizing key points, and inviting feedback in an engaging, interactive manner.", "Delivering a detailed, technical update that leaves little room for questions or discussion.", "Offering a brief status report without explanation of potential audit findings.", "Focusing on background information without summarizing current status."]$q$::jsonb, $q$["อธิบายความคืบหน้าอย่างชัดเจน สรุปประเด็นสำคัญ และเชิญชวนความคิดเห็นในลักษณะโต้ตอบและมีส่วนร่วม", "นำเสนอการอัปเดตทางเทคนิคโดยละเอียดซึ่งทำให้เหลือพื้นที่สำหรับคำถามหรือการสนทนาเพียงเล็กน้อย", "เสนอรายงานสถานะโดยย่อโดยไม่มีคำอธิบายเกี่ยวกับผลการตรวจสอบที่อาจเกิดขึ้น", "เน้นข้อมูลความเป็นมาโดยไม่ต้องสรุปสถานะปัจจุบัน"]$q$::jsonb, 0, $q$Correct. Clearly articulating audit progress, with a focus on key points and interactive  discussion, supports effective communication in team settings.$q$, $q$ถูกต้อง. ความคืบหน้าในการตรวจสอบที่ชัดเจนโดยเน้นประเด็นสำคัญและการสนทนาเชิงโต้ตอบ สนับสนุนการสื่อสารที่มีประสิทธิภาพในการตั้งค่าทีม$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10226', '2026', 1, 'B.4.f', $q$How should an internal auditor apply research skills to update  knowledge on evolving regulatory requirements?$q$, $q$ผู้ตรวจสอบภายในควรใช้ทักษะการวิจัยเพื่อปรับปรุงความรู้เกี่ยวกับข้อกำหนดด้านกฎระเบียบที่เปลี่ยนแปลงไปอย่างไร$q$, $q$["By providing periodic internal briefings on potential regulatory trends.", "By primarily relying on the organization’s historical regulatory documents and past audit results.", "By accessing current regulatory filings, industry news, and academic analyses to stay informed on new standards and practices.", "By using prior standard checklists that have been effective in the past."]$q$::jsonb, $q$["โดยจัดให้มีการบรรยายสรุปภายในเป็นระยะเกี่ยวกับแนวโน้มด้านกฎระเบียบที่อาจเกิดขึ้น", "โดยอาศัยเอกสารการกำกับดูแลในอดีตขององค์กรและผลการตรวจสอบในอดีตเป็นหลัก", "โดยการเข้าถึงเอกสารการกำกับดูแลในปัจจุบัน ข่าวสารอุตสาหกรรม และการวิเคราะห์ทางวิชาการเพื่อรับทราบข้อมูลมาตรฐานและแนวปฏิบัติใหม่", "โดยใช้รายการตรวจสอบมาตรฐานเดิมที่มีผลใช้บังคับในอดีต"]$q$::jsonb, 2, $q$Correct. Leveraging current regulatory and industry resources ensures that internal  auditors maintain an updated and relevant knowledge base.$q$, $q$ถูกต้อง. การใช้ประโยชน์จากทรัพยากรด้านกฎระเบียบและอุตสาหกรรมในปัจจุบันทำให้มั่นใจได้ว่าผู้ตรวจสอบภายในจะรักษาฐานความรู้ที่ทันสมัยและเกี่ยวข้อง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10227', '2026', 1, 'B.5.e', $q$When evaluating a new data source during an audit engagement,  how can an internal auditor best apply professional skepticism?$q$, $q$เมื่อประเมินแหล่งข้อมูลใหม่ในระหว่างการปฏิบัติงานตรวจสอบ ผู้ตรวจสอบภายในจะนำความสงสัยทางวิชาชีพมาใช้ให้เกิดประโยชน์สูงสุดได้อย่างไร$q$, $q$["By reviewing the external source’s reputation and comparing its data to an independent source for confirmation.", "By accepting the data if it aligns with internal records and past performance trends.", "By corroborating new information with multiple independent sources and questioning any inconsistencies to ensure the data's reliability.", "By conducting a trend analysis of the data and validating selected transactions."]$q$::jsonb, $q$["โดยการตรวจสอบชื่อเสียงของแหล่งข้อมูลภายนอกและเปรียบเทียบข้อมูลกับแหล่งข้อมูลอิสระเพื่อยืนยัน", "โดยการยอมรับข้อมูลหากสอดคล้องกับบันทึกภายในและแนวโน้มผลการดำเนินงานที่ผ่านมา", "โดยการยืนยันข้อมูลใหม่กับแหล่งข้อมูลอิสระหลายแห่ง และตั้งคำถามถึงความไม่สอดคล้องกันเพื่อให้มั่นใจในความน่าเชื่อถือของข้อมูล", "โดยดำเนินการวิเคราะห์แนวโน้มของข้อมูลและตรวจสอบธุรกรรมที่เลือก"]$q$::jsonb, 2, $q$Correct. Cross-referencing new information with multiple sources and questioning  inconsistencies is crucial for an unbiased assessment of data reliability.$q$, $q$ถูกต้อง. การอ้างอิงข้อมูลใหม่ที่มีแหล่งที่มาหลายแห่งและการตั้งคำถามถึงความไม่สอดคล้องกันถือเป็นสิ่งสำคัญสำหรับการประเมินความน่าเชื่อถือของข้อมูลอย่างเป็นกลาง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10228', '2026', 1, 'B.5.e', $q$When confronted with conflicting evidence during an audit  engagement, how should an internal auditor best apply  professional skepticism?$q$, $q$เมื่อต้องเผชิญกับหลักฐานที่ขัดแย้งกันในระหว่างการปฏิบัติงานตรวจสอบ ผู้ตรวจสอบภายในควรใช้ความสงสัยทางวิชาชีพได้ดีที่สุดอย่างไร$q$, $q$["By carefully evaluating all sources of evidence, seeking independent confirmation, and maintaining an unbiased perspective throughout the review.", "By prioritizing evidence that supports the initial hypothesis.", "By comparing evidence against historical trends and prior periods.", "By referring to previous audit findings as a basis for resolving any conflicts in the evidence encountered."]$q$::jsonb, $q$["โดยการประเมินแหล่งที่มาของหลักฐานทั้งหมดอย่างรอบคอบ ขอคำยืนยันที่เป็นอิสระ และรักษามุมมองที่เป็นกลางตลอดการทบทวน", "โดยการจัดลำดับความสำคัญของหลักฐานที่สนับสนุนสมมติฐานเบื้องต้น", "โดยการเปรียบเทียบหลักฐานกับแนวโน้มในอดีตและช่วงก่อนๆ", "โดยอ้างอิงถึงผลการตรวจสอบที่ผ่านมาเพื่อเป็นพื้นฐานในการแก้ไขข้อขัดแย้งในหลักฐานที่พบ"]$q$::jsonb, 0, $q$Correct. A thorough evaluation of all evidence and seeking independent confirmation are  essential to upholding an unbiased review when conflicts arise.$q$, $q$ถูกต้อง. การประเมินหลักฐานทั้งหมดอย่างละเอียดและการขอคำยืนยันจากหน่วยงานอิสระถือเป็นสิ่งสำคัญในการสนับสนุนการทบทวนอย่างเป็นกลางเมื่อเกิดข้อขัดแย้ง$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10229', '2026', 1, 'B.5.e', $q$When assessing the reliability of external data sources, how  should an internal auditor best apply professional skepticism?$q$, $q$เมื่อประเมินความน่าเชื่อถือของแหล่งข้อมูลภายนอก ผู้ตรวจสอบภายในควรใช้ความสงสัยอย่างมืออาชีพอย่างไร$q$, $q$["By cross-referencing data with multiple independent sources and questioning any inconsistencies to ensure the data's reliability.", "By accepting the data if it aligns with internal records and past performance trends.", "By reviewing the external source’s reputation and comparing its data to an independent source for confirmation.", "By reviewing the external data's methodology and validating key amounts from prior reports."]$q$::jsonb, $q$["โดยการอ้างอิงข้อมูลกับแหล่งข้อมูลอิสระหลายแห่ง และตั้งคำถามถึงความไม่สอดคล้องกันเพื่อให้มั่นใจในความน่าเชื่อถือของข้อมูล", "โดยการยอมรับข้อมูลหากสอดคล้องกับบันทึกภายในและแนวโน้มผลการดำเนินงานที่ผ่านมา", "โดยการตรวจสอบชื่อเสียงของแหล่งข้อมูลภายนอกและเปรียบเทียบข้อมูลกับแหล่งข้อมูลอิสระเพื่อยืนยัน", "โดยการทบทวนวิธีการของข้อมูลภายนอกและตรวจสอบความถูกต้องของจำนวนเงินที่สำคัญจากรายงานก่อนหน้านี้"]$q$::jsonb, 0, $q$Correct. Cross-referencing with multiple independent sources and questioning  inconsistencies is fundamental to verifying the reliability of external data.$q$, $q$ถูกต้อง. การอ้างอิงโยงกับแหล่งข้อมูลอิสระหลายแห่งและการตั้งคำถามที่ไม่สอดคล้องกันเป็นพื้นฐานในการตรวจสอบความน่าเชื่อถือของข้อมูลภายนอก$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10230', '2026', 1, 'B.6.a', $q$When collaborating with external stakeholders, how can an  internal auditor ensure that confidential information is used  appropriately?$q$, $q$When collaborating with external stakeholders, how can an  ผู้ตรวจสอบภายใน ensure that confidential information is used  appropriately?$q$, $q$["By disclosing only the necessary information under strict confidentiality agreements and in compliance with organizational policies and relevant laws.", "By providing comprehensive details to external parties once a preliminary review is completed, ensuring transparency.", "By sharing summarized findings with external stakeholders while retaining full details for internal review only.", "By consulting external experts on sensitive issues and later integrating their feedback into the audit report without further disclosure."]$q$::jsonb, $q$["By disclosing only the necessary information under strict confidentiality agreements and in compliance with organizational policies and relevant laws.", "By providing comprehensive details to external parties once a preliminary review is completed, ensuring transparency.", "By sharing summarized findings with external stakeholders while retaining full details for internal review only.", "By consulting external experts on sensitive issues and later integrating their feedback into the audit report without further disclosure."]$q$::jsonb, 0, $q$Correct. Limiting disclosure to necessary information under formal confidentiality  agreements and in compliance with policies maintains appropriate use of sensitive data.$q$, $q$ถูกต้อง: Limiting disclosure to necessary information under formal confidentiality  agreements and in compliance with policies maintains appropriate use of sensitive data.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10231', '2026', 1, 'B.6.a', $q$When incorporating confidential information into audit  recommendations, which approach best ensures appropriate use?$q$, $q$When incorporating confidential information into audit  recommendations, which approach best ensures appropriate use?$q$, $q$["Summarizing confidential recommendations in the main report and discussing sensitive details verbally with the board.", "Including summary recommendations in the final report and providing additional confidential details in a separate appendix for senior management.", "Clearly identifying confidential sections in the recommendations and sharing them only with authorized parties through secure channels.", "Preparing a draft report with confidential data that is later redacted before final distribution to external stakeholders."]$q$::jsonb, $q$["Summarizing confidential recommendations in the main report and discussing sensitive details verbally with คณะกรรมการ.", "Including summary recommendations in the final report and providing additional confidential details in a separate appendix for ผู้บริหารระดับสูง.", "Clearly identifying confidential sections in the recommendations and sharing them only with authorized parties through secure channels.", "Preparing a draft report with confidential data that is later redacted before final distribution to external stakeholders."]$q$::jsonb, 2, $q$Correct. Clearly marking confidential sections and using secure channels for distribution  ensures that confidential recommendations are communicated appropriately.$q$, $q$ถูกต้อง: Clearly marking confidential sections and using secure channels for distribution  ensures that confidential recommendations are communicated appropriately.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10232', '2026', 1, 'B.6.b', $q$During an audit engagement of operational processes involving  proprietary information, how can an internal auditor ensure proper  use of sensitive information?$q$, $q$During an การปฏิบัติงานตรวจสอบ of operational processes involving  proprietary information, how can an ผู้ตรวจสอบภายใน ensure proper  use of sensitive information?$q$, $q$["By transferring all collected proprietary information into a central database for ease of access.", "By using secure audit software, following established data protection protocols, and sharing information only with authorized individuals.", "By disseminating full details of proprietary data only in draft reports but not included in the final report.", "By summarizing sensitive proprietary information in reports distributed to promote dissemination."]$q$::jsonb, $q$["By transferring all collected proprietary information into a central database for ease of access.", "By using secure audit software, following established data protection protocols, and sharing information only with authorized individuals.", "By disseminating full details of proprietary data only in draft reports but not included in the final report.", "By summarizing sensitive proprietary information in reports distributed to promote dissemination."]$q$::jsonb, 1, $q$Correct. Employing secure audit software and strict data protection protocols ensures  sensitive information is used appropriately during the engagement.$q$, $q$ถูกต้อง: Employing secure audit software and strict data protection protocols ensures  sensitive information is used appropriately during the การปฏิบัติงานตรวจสอบ.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10233', '2026', 1, 'B.6.b', $q$When incorporating third-party data for audit evidence, which  approach best applies internal audit methodologies to maintain  confidentiality?$q$, $q$When incorporating third-party data for audit evidence, which  approach best applies internal audit methodologies to maintain  confidentiality?$q$, $q$["Obtaining data through secure channels and integrating it into the audit process in line with data protection policies.", "Requesting third-party data through email.", "Using reliable third-party data as a primary source for audit evidence.", "Sharing all third-party data with the internal audit function to foster a collaborative review process."]$q$::jsonb, $q$["Obtaining data through secure channels and integrating it into the audit process in line with data protection policies.", "Requesting third-party data through email.", "Using reliable third-party data as a primary source for audit evidence.", "Sharing all third-party data with the หน่วยงานตรวจสอบภายใน to foster a collaborative review process."]$q$::jsonb, 0, $q$Correct. Securing third-party data through verified channels and integrating it per data  protection policies ensures that confidentiality is maintained.$q$, $q$ถูกต้อง: Securing third-party data through verified channels and integrating it per data  protection policies ensures that confidentiality is maintained.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10234', '2026', 1, 'B.6.c', $q$In an audit engagement that requires the review of third-party  proprietary data, which practice best demonstrates respect for  privacy and data ownership?$q$, $q$In an การปฏิบัติงานตรวจสอบ that requires the review of third-party  proprietary data, which practice best demonstrates respect for  privacy and data ownership?$q$, $q$["Distributing original third- party data within the organization to encourage feedback during the audit engagement.", "Sharing third-party proprietary data with internal departments to obtain feedback from internal experts.", "Obtaining third-party data without formal agreements, trusting that confidentiality will be maintained.", "Accessing and using third-party data strictly under the terms of confidentiality agreements and secure transfer protocols."]$q$::jsonb, $q$["Distributing original third- party data within the organization to encourage feedback during the การปฏิบัติงานตรวจสอบ.", "Sharing third-party proprietary data with internal departments to obtain feedback from internal experts.", "Obtaining third-party data without formal agreements, trusting that confidentiality will be maintained.", "Accessing and using third-party data strictly under the terms of confidentiality agreements and secure transfer protocols."]$q$::jsonb, 3, $q$Correct. Strict adherence to confidentiality agreements and secure protocols ensures  that third-party proprietary data is handled appropriately.$q$, $q$ถูกต้อง: Strict adherence to confidentiality agreements and secure protocols ensures  that third-party proprietary data is handled appropriately.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10235', '2026', 1, 'B.6.c', $q$During an audit engagement that involves personal data collected  from interviews, which approach best maintains respect for  privacy and information ownership?$q$, $q$During an การปฏิบัติงานตรวจสอบ that involves personal data collected  from interviews, which approach best maintains respect for  privacy and information ownership?$q$, $q$["Conducting interviews in private settings, securely recording and storing the data, and limiting its use to the engagement’s scope.", "Recording interviews to document audit information.", "Sharing interview transcripts with internal stakeholders to obtain feedback from internal experts.", "Recording all client interviews in order to expedite the audit process."]$q$::jsonb, $q$["Conducting interviews in private settings, securely recording and storing the data, and limiting its use to the การปฏิบัติงานตรวจสอบ’s scope.", "Recording interviews to document audit information.", "Sharing interview transcripts with internal stakeholders to obtain feedback from internal experts.", "Recording all client interviews in order to expedite the audit process."]$q$::jsonb, 0, $q$Correct. Conducting interviews in private and securing recorded data upholds the  privacy of individuals and respects information ownership.$q$, $q$ถูกต้อง: Conducting interviews in private and securing recorded data upholds the  privacy of individuals and respects information ownership.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10236', '2026', 1, 'B.6.d', $q$In an audit engagement involving the collection of customer data,  which method best maintains confidentiality and proper use?$q$, $q$In an การปฏิบัติงานตรวจสอบ involving the collection of customer data,  which method best maintains confidentiality and proper use?$q$, $q$["Collecting data via secure, encrypted channels and restricting access to only those explicitly authorized for the audit engagement.", "Acquiring data through standard methods and storing it in a shared drive with departmental access.", "Collecting data from approved sources and using internal software with default security settings to restrict access.", "Obtaining customer data without formal encryption but limiting access through passwords."]$q$::jsonb, $q$["Collecting data via secure, encrypted channels and restricting access to only those explicitly authorized for the การปฏิบัติงานตรวจสอบ.", "Acquiring data through standard methods and storing it in a shared drive with departmental access.", "Collecting data from approved sources and using internal software with default security settings to restrict access.", "Obtaining customer data without formal encryption but limiting access through passwords."]$q$::jsonb, 0, $q$Correct. Using secure, encrypted channels and restricting access to authorized  individuals ensures customer data is maintained confidentially and used appropriately.$q$, $q$ถูกต้อง: Using secure, encrypted channels and restricting access to authorized  individuals ensures customer data is maintained confidentially and used appropriately.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10237', '2026', 1, 'B.6.d', $q$When sharing audit findings with management, which method  best ensures the confidentiality and appropriate use of sensitive  information?$q$, $q$When sharing audit findings with management, which method  best ensures the confidentiality and appropriate use of sensitive  information?$q$, $q$["Transmitting documents through internal messaging systems with standard security settings and limited access.", "Distributing digital copies via secure email to management.", "Sharing reports via a secure intranet portal with multi- factor authentication to verify recipient identity.", "Using secure file transfer protocols and password-protected documents so that only authorized management receives the information."]$q$::jsonb, $q$["Transmitting documents through internal messaging systems with standard security settings and limited access.", "Distributing digital copies via secure email to management.", "Sharing reports via a secure intranet portal with multi- factor authentication to verify recipient identity.", "Using secure file transfer protocols and password-protected documents so that only authorized management receives the information."]$q$::jsonb, 3, $q$Correct. Secure file transfer with password protection best controls access and maintains  the confidentiality of sensitive audit findings.$q$, $q$ถูกต้อง: Secure file transfer with password protection best controls access and maintains  the confidentiality of sensitive audit findings.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10238', '2026', 1, 'B.6.d', $q$When updating internal audit documentation containing sensitive  data, which method best maintains confidentiality?$q$, $q$When updating internal audit documentation containing sensitive  data, which method best maintains confidentiality?$q$, $q$["Storing all updated documentation in encrypted systems with access limited to authorized personnel and following data retention policies.", "Saving updated documentation on a secure server with strict user authentication and periodic access reviews.", "Maintaining documentation in an encrypted format on an internal portal with role-based access controls and audit trails.", "Using password-protected files on a shared drive with controlled access and routine backup procedures."]$q$::jsonb, $q$["Storing all updated documentation in encrypted systems with access limited to authorized personnel and following data retention policies.", "Saving updated documentation on a secure server with strict user authentication and periodic access reviews.", "Maintaining documentation in an encrypted format on an internal portal with role-based access controls and audit trails.", "Using password-protected files on a shared drive with controlled access and routine backup procedures."]$q$::jsonb, 0, $q$Correct. Encrypting documentation and restricting access to authorized users are critical  practices for maintaining confidentiality during updates.$q$, $q$ถูกต้อง: Encrypting documentation and restricting access to authorized users are critical  practices for maintaining confidentiality during updates.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10239', '2026', 1, 'C.1.b', $q$Which governance principle is fundamental to promoting  accountability within an organization?$q$, $q$Which การกำกับดูแล principle is fundamental to promoting  accountability within an organization?$q$, $q$["Hierarchy, which focuses on top‑down decision‑making without broader participation.", "Autonomy, which emphasizes independent decision‑making without external oversight.", "Exclusivity, which limits information sharing to selected groups to maintain control.", "Transparency, which requires open sharing of information and clear communication of decision‑making processes."]$q$::jsonb, $q$["Hierarchy, which focuses on top‑down decision‑making without broader participation.", "Autonomy, which emphasizes independent decision‑making without external oversight.", "Exclusivity, which limits information sharing to selected groups to maintain control.", "Transparency, which requires open sharing of information and clear communication of decision‑making processes."]$q$::jsonb, 3, $q$Correct. Transparency is essential for accountability as it ensures that decisions and  processes are openly communicated.$q$, $q$ถูกต้อง: Transparency is essential for accountability as it ensures that decisions and  processes are openly communicated.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10240', '2026', 1, 'C.2.a', $q$What role does organizational culture play in defining the overall  control environment?$q$, $q$What role does organizational culture play in defining the overall  control environment?$q$, $q$["Organizational culture influences cost management practices more than internal control frameworks.", "Organizational culture primarily affects external communications, with limited relevance to internal control mechanisms.", "Organizational culture is impacted by the tone at the top by establishing values and ethical standards that guide the behavior of personnel.", "Organizational culture is important for talent management but does not have a direct role in shaping internal controls."]$q$::jsonb, $q$["Organizational culture influences cost management practices more than การควบคุมภายใน frameworks.", "Organizational culture primarily affects external communications, with limited relevance to การควบคุมภายใน mechanisms.", "Organizational culture is impacted by the tone at the top by establishing values and ethical standards that guide the behavior of personnel.", "Organizational culture is important for talent management but does not have a direct role in shaping การควบคุมภายในs."]$q$::jsonb, 2, $q$Correct. Culture at the top of the organization guides ethical standards and values, which  are essential in the design and functioning of internal controls.$q$, $q$ถูกต้อง: Culture at the top of the organization guides ethical standards and values, which  are essential in the design and functioning of การควบคุมภายในs.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10241', '2026', 1, 'C.2.a', $q$Which factor best exemplifies the relationship between  organizational culture and the control environment?$q$, $q$Which factor best exemplifies the relationship between  organizational culture and the control environment?$q$, $q$["The alignment of values primarily drives market strategy rather than the robustness of internal control systems.", "The alignment of values influences customer relations, with a secondary impact on internal controls.", "The alignment of values, ethical standards, and leadership behavior directly enhances the effectiveness of internal controls and risk management practices.", "The alignment of values is relevant to performance reviews and has minimal direct impact on control effectiveness."]$q$::jsonb, $q$["The alignment of values primarily drives market strategy rather than the robustness of การควบคุมภายใน systems.", "The alignment of values influences customer relations, with a secondary impact on การควบคุมภายในs.", "The alignment of values, ethical standards, and leadership behavior directly enhances the effectiveness of การควบคุมภายในs and การบริหารความเสี่ยง practices.", "The alignment of values is relevant to performance reviews and has minimal direct impact on control effectiveness."]$q$::jsonb, 2, $q$Correct. The consistent application of values and ethics by leadership is crucial in  building a strong control environment and effective risk management practices.$q$, $q$ถูกต้อง: The consistent application of values and ethics by leadership is crucial in  building a strong control environment and effective การบริหารความเสี่ยง practices.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10242', '2026', 1, 'C.2.c', $q$How can an organization’s approach to decision‑making  positively impact its overall governance framework?$q$, $q$How can an organization’s approach to decision‑making  positively impact its overall การกำกับดูแล framework?$q$, $q$["A reactive process that addresses issues only as they arise can undermine strategic governance and risk management.", "Relying solely on historical data may lead to outdated governance practices and ineffective control measures.", "Integrating comprehensive stakeholder input and systematic review into decision‑making results in stronger governance and improved risk mitigation.", "Centralized decisions made without diverse input can impede innovation and weaken the overall governance framework."]$q$::jsonb, $q$["A reactive process that addresses issues only as they arise can undermine strategic การกำกับดูแล and การบริหารความเสี่ยง.", "Relying solely on historical data may lead to outdated การกำกับดูแล practices and ineffective control measures.", "Integrating comprehensive stakeholder input and systematic review into decision‑making results in stronger การกำกับดูแล and improved risk mitigation.", "Centralized decisions made without diverse input can impede innovation and weaken the overall การกำกับดูแล framework."]$q$::jsonb, 2, $q$Correct. Inclusive, systematic decision‑making enhances governance by ensuring  effective oversight of risks and controls.$q$, $q$ถูกต้อง: Inclusive, systematic decision‑making enhances การกำกับดูแล by ensuring  effective oversight of risks and controls.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10243', '2026', 1, 'C.2.c', $q$How do effective decision‑making processes positively influence  individual engagement risks and control measures within an  organization?$q$, $q$How do effective decision‑making processes positively influence  individual การปฏิบัติงานตรวจสอบ risks and control measures within an  organization?$q$, $q$["Processes focused mainly on efficiency can neglect critical individual risk factors, leading to weaker controls.", "Effective decision‑making characterized by thorough reviews and diverse input minimizes engagement risks and enhances the strength of control measures.", "Centralized decision‑making with minimal stakeholder input may yield inconsistent risk assessments and suboptimal controls.", "Rapid decision‑making that prioritizes short‑term gains may increase engagement risks and compromise control quality."]$q$::jsonb, $q$["Processes focused mainly on efficiency can neglect critical individual risk factors, leading to weaker controls.", "Effective decision‑making characterized by thorough reviews and diverse input minimizes การปฏิบัติงานตรวจสอบ risks and enhances the strength of control measures.", "Centralized decision‑making with minimal stakeholder input may yield inconsistent risk assessments and suboptimal controls.", "Rapid decision‑making that prioritizes short‑term gains may increase การปฏิบัติงานตรวจสอบ risks and compromise control quality."]$q$::jsonb, 1, $q$Correct. Thorough, inclusive decision‑making reduces individual engagement risks and  strengthens control measures across the organization.$q$, $q$ถูกต้อง: Thorough, inclusive decision‑making reduces individual การปฏิบัติงานตรวจสอบ risks and  strengthens control measures across the organization.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10244', '2026', 1, 'C.2.c', $q$How does the adoption of participatory decision‑making  practices positively affect an organization’s governance, risk  management, and control processes?$q$, $q$How does the adoption of participatory decision‑making  practices positively affect an organization’s การกำกับดูแล, risk  management, and control processes?$q$, $q$["A consensus‑driven approach might neglect specialized expertise needed to optimize internal controls and risk oversight.", "Broad participation may sometimes delay decisions, which can hinder timely updates to risk management processes.", "Relying solely on consensus may dilute accountability and result in less-focused risk assessments and controls.", "Participatory decision‑making that encourages collaboration, transparency, and accountability enhances governance, risk management, and control systems."]$q$::jsonb, $q$["A consensus‑driven approach might neglect specialized expertise needed to optimize การควบคุมภายในs and risk oversight.", "Broad participation may sometimes delay decisions, which can hinder timely updates to การบริหารความเสี่ยง processes.", "Relying solely on consensus may dilute accountability and result in less-focused risk assessments and controls.", "Participatory decision‑making that encourages collaboration, transparency, and accountability enhances การกำกับดูแล, การบริหารความเสี่ยง, and control systems."]$q$::jsonb, 3, $q$Correct. Participatory decision‑making promotes collaboration and accountability,  leading to improved governance, risk management, and controls.$q$, $q$ถูกต้อง: Participatory decision‑making promotes collaboration and accountability,  leading to improved การกำกับดูแล, การบริหารความเสี่ยง, and controls.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10245', '2026', 1, 'C.3.a', $q$Which scenario best demonstrates the identification of  compliance requirements within an organization?$q$, $q$Which scenario best demonstrates the identification of  compliance requirements within an organization?$q$, $q$["Basing compliance on informal employee feedback and anecdotal evidence rather than documented standards.", "Relying on past compliance practices without considering recent regulatory changes or industry trends.", "Following the advice of external auditors to shape compliance measures.", "Reviewing current regulatory guidelines, industry standards, and internal policies to establish a comprehensive compliance framework."]$q$::jsonb, $q$["Basing compliance on informal employee feedback and anecdotal evidence rather than documented standards.", "Relying on past compliance practices without considering recent regulatory changes or industry trends.", "Following the advice of external auditors to shape compliance measures.", "Reviewing current regulatory guidelines, industry standards, and internal policies to establish a comprehensive compliance framework."]$q$::jsonb, 3, $q$Correct. A comprehensive review of regulatory guidelines, industry standards, and  internal policies is essential for identifying compliance requirements.$q$, $q$ถูกต้อง: A comprehensive review of regulatory guidelines, industry standards, and  internal policies is essential for identifying compliance requirements.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10246', '2026', 1, 'C.3.b', $q$How does the internal auditor contribute to detecting compliance- related issues within an organization’s ethical framework?$q$, $q$How does the ผู้ตรวจสอบภายใน contribute to detecting compliance- related issues within an organization’s ethical framework?$q$, $q$["By monitoring financial controls while relying on management to address any ethical or compliance concerns.", "By delegating the evaluation of compliance issues to external auditors and focusing on operational reviews.", "By collecting data on ethical practices without conducting an assurance audit engagement.", "By reviewing internal policies and practices against established ethical and legal benchmarks and reporting any discrepancies for corrective action."]$q$::jsonb, $q$["By monitoring financial controls while relying on management to address any ethical or compliance concerns.", "By delegating the evaluation of compliance issues to external auditors and focusing on operational reviews.", "By collecting data on ethical practices without conducting an assurance การปฏิบัติงานตรวจสอบ.", "By reviewing internal policies and practices against established ethical and legal benchmarks and reporting any discrepancies for corrective action."]$q$::jsonb, 3, $q$Correct. Evaluating policies against ethical and legal benchmarks and reporting  discrepancies is central to the auditor’s role in compliance monitoring.$q$, $q$ถูกต้อง: Evaluating policies against ethical and legal benchmarks and reporting  discrepancies is central to the auditor’s role in compliance monitoring.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10247', '2026', 1, 'C.3.b', $q$How can internal auditors recognize compliance-related issues  through analysis of decision‑making processes?$q$, $q$How can ผู้ตรวจสอบภายในs recognize compliance-related issues  through analysis of decision‑making processes?$q$, $q$["By evaluating whether decision‑making incorporates diverse input and clear criteria, which supports effective risk management and ethical control.", "By assuming that decisions made by top management are compliant with ethical standards and legal requirements.", "By relying on external reports to assess decision‑making without considering internal stakeholder feedback.", "By focusing on the speed of decision‑making rather than its quality or the diversity of input when assessing ethical compliance."]$q$::jsonb, $q$["By evaluating whether decision‑making incorporates diverse input and clear criteria, which supports effective การบริหารความเสี่ยง and ethical control.", "By assuming that decisions made by top management are compliant with ethical standards and legal requirements.", "By relying on external reports to assess decision‑making without considering internal stakeholder feedback.", "By focusing on the speed of decision‑making rather than its quality or the diversity of input when assessing ethical compliance."]$q$::jsonb, 0, $q$Correct. Assessing decision‑making for diverse input and clear criteria enables auditors  to identify compliance issues that impact ethical controls.$q$, $q$ถูกต้อง: Assessing decision‑making for diverse input and clear criteria enables auditors  to identify compliance issues that impact ethical controls.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10248', '2026', 1, 'C.4.b', $q$How can an internal auditor compare inherent and residual risks  to evaluate control effectiveness?$q$, $q$How can an ผู้ตรวจสอบภายใน compare inherent and residual risks  to evaluate control effectiveness?$q$, $q$["By focusing on residual risk alone, the auditor infers that the effect of controls is sufficient without comparing it to inherent risk.", "By measuring risk levels before controls and then after controls are applied, the auditor can determine the reduction achieved.", "By estimating inherent risk based on historical data and then assuming that residual risk follows similar patterns after controls.", "By assessing inherent risk from external benchmarks while treating residual risk as an independent measure unaffected by controls."]$q$::jsonb, $q$["By focusing on residual risk alone, the auditor infers that the effect of controls is sufficient without comparing it to inherent risk.", "By measuring risk levels before controls and then after controls are applied, the auditor can determine the reduction achieved.", "By estimating inherent risk based on historical data and then assuming that residual risk follows similar patterns after controls.", "By assessing inherent risk from external benchmarks while treating residual risk as an independent measure unaffected by controls."]$q$::jsonb, 1, $q$Correct. Comparing risk levels before and after control application provides a direct  measure of how effective the controls are.$q$, $q$ถูกต้อง: Comparing risk levels before and after control application provides a direct  measure of how effective the controls are.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10249', '2026', 1, 'C.4.b', $q$How does the application of controls transform inherent risk into  residual risk?$q$, $q$How does the application of controls transform inherent risk into  residual risk?$q$, $q$["Controls serve only to document inherent risk, leaving residual risk unchanged regardless of the controls’ effectiveness.", "Controls are applied to mitigate inherent risk, and the remaining exposure is identified as the residual risk level.", "Controls are used to measure inherent risk and then are factored out, resulting in residual risk being set by external variables.", "Controls are applied in parallel to inherent risk assessment, but residual risk is calculated independently from the effect of those controls."]$q$::jsonb, $q$["Controls serve only to document inherent risk, leaving residual risk unchanged regardless of the controls’ effectiveness.", "Controls are applied to mitigate inherent risk, and the remaining exposure is identified as the residual risk level.", "Controls are used to measure inherent risk and then are factored out, resulting in residual risk being set by external variables.", "Controls are applied in parallel to inherent risk assessment, but residual risk is calculated independently from the effect of those controls."]$q$::jsonb, 1, $q$Correct. The application of controls reduces the inherent risk, and the risk that remains  after these controls is known as residual risk.$q$, $q$ถูกต้อง: The application of controls reduces the inherent risk, and the risk that remains  after these controls is known as residual risk.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10250', '2026', 1, 'C.5.a', $q$Which statement best defines risk management in an organization?$q$, $q$Which statement best defines การบริหารความเสี่ยง in an organization?$q$, $q$["Risk management is the process of identifying, assessing, mitigating, and monitoring risks to minimize adverse impacts on objectives.", "Risk management is the practice of avoiding risks by halting operations when any risk is identified.", "Risk management is a reactive process that addresses issues only after they occur, without proactive measures.", "Risk management is the delegation of risk- related decisions to external consultants without internal evaluation."]$q$::jsonb, $q$["การบริหารความเสี่ยง is the process of identifying, assessing, mitigating, and monitoring risks to minimize adverse impacts on objectives.", "การบริหารความเสี่ยง is the practice of avoiding risks by halting operations when any risk is identified.", "การบริหารความเสี่ยง is a reactive process that addresses issues only after they occur, without proactive measures.", "การบริหารความเสี่ยง is the delegation of risk- related decisions to external consultants without internal evaluation."]$q$::jsonb, 0, $q$Correct. Risk management involves a systematic process that includes risk identification,  assessment, mitigation, and monitoring.$q$, $q$ถูกต้อง: การบริหารความเสี่ยง involves a systematic process that includes risk identification,  assessment, mitigation, and monitoring.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10251', '2026', 1, 'C.5.a', $q$Which statement best explains the role of risk assessment in the  risk management process?$q$, $q$Which statement best explains the role of risk assessment in the  การบริหารความเสี่ยง process?$q$, $q$["Risk assessment is a quantitative exercise that ignores qualitative factors in risk evaluation.", "Risk assessment is the practice of dismissing potential risks that appear unlikely, without further analysis.", "Risk assessment involves systematically evaluating the likelihood and impact of potential risks to inform effective mitigation strategies.", "Risk assessment considers all potential risks without considering risk mitigation."]$q$::jsonb, $q$["Risk assessment is a quantitative exercise that ignores qualitative factors in risk evaluation.", "Risk assessment is the practice of dismissing potential risks that appear unlikely, without further analysis.", "Risk assessment involves systematically evaluating the likelihood and impact of potential risks to inform effective mitigation strategies.", "Risk assessment considers all potential risks without considering risk mitigation."]$q$::jsonb, 2, $q$Correct. Risk assessment is a systematic evaluation of both the likelihood and impact of  risks, serving as a foundation for mitigation strategies.$q$, $q$ถูกต้อง: Risk assessment is a systematic evaluation of both the likelihood and impact of  risks, serving as a foundation for mitigation strategies.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10252', '2026', 1, 'C.5.a', $q$How does a systematic risk management process benefit  organizational decision-making?$q$, $q$How does a systematic การบริหารความเสี่ยง process benefit  organizational decision-making?$q$, $q$["How does a systematic risk management process benefit organizational decision- making? A systematic process offers structured analysis and clear mitigation strategies, enabling informed decisions that support resilience and performance.", "A systematic process tends to overcomplicate decisions by relying solely on rigid frameworks without flexibility.", "A systematic process restricts decision-making by focusing only on past risks and ignoring future opportunities.", "A systematic process separates risk considerations from decision-making, making them irrelevant to strategic planning."]$q$::jsonb, $q$["How does a systematic การบริหารความเสี่ยง process benefit organizational decision- making? A systematic process offers structured analysis and clear mitigation strategies, enabling informed decisions that support resilience and performance.", "A systematic process tends to overcomplicate decisions by relying solely on rigid frameworks without flexibility.", "A systematic process restricts decision-making by focusing only on past risks and ignoring future opportunities.", "A systematic process separates risk considerations from decision-making, making them irrelevant to strategic planning."]$q$::jsonb, 0, $q$Correct. A structured risk management process provides clear insights and strategies  that enhance decision-making and organizational resilience.$q$, $q$ถูกต้อง: A structured การบริหารความเสี่ยง process provides clear insights and strategies  that enhance decision-making and organizational resilience.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10253', '2026', 1, 'C.5.b', $q$How does an organization typically determine its risk appetite  within a risk management framework?$q$, $q$an organization กำหนด determine its risk appetite  within a การบริหารความเสี่ยง framework อย่างไรโดยทั่วไป?$q$, $q$["By adopting industry benchmarks without adjusting for the organization’s unique risk environment.", "By relying on historical loss data to set fixed risk tolerance ranges.", "By assessing strategic objectives, market conditions, and stakeholder expectations to establish a broad level of acceptable risk.", "By complying with regulatory requirements instead of strategic considerations."]$q$::jsonb, $q$["By adopting industry benchmarks without adjusting for the organization’s unique risk environment.", "By relying on historical loss data to set fixed risk tolerance ranges.", "By assessing strategic objectives, market conditions, and stakeholder expectations to establish a broad level of acceptable risk.", "By complying with regulatory requirements instead of strategic considerations."]$q$::jsonb, 2, $q$Correct. Determining risk appetite involves evaluating strategic objectives, market  conditions, and stakeholder expectations to set a holistic risk threshold.$q$, $q$ถูกต้อง: Determining risk appetite involves evaluating strategic objectives, market  conditions, and stakeholder expectations to set a holistic risk threshold.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10254', '2026', 1, 'C.5.b', $q$How can an organization use risk tolerance levels to monitor and  control its overall risk exposure?$q$, $q$How can an organization use risk tolerance levels to monitor and  control its overall risk exposure?$q$, $q$["Risk tolerance levels serve as guideposts that allow continuous monitoring and adjustment to ensure risk exposures remain within acceptable limits.", "Risk tolerance levels are set at one point and remain static throughout the risk management cycle, regardless of changes.", "Risk tolerance levels are primarily defined by external market conditions.", "Risk tolerance levels are used at the start of an audit engagement and separate from ongoing risk assessments."]$q$::jsonb, $q$["Risk tolerance levels serve as guideposts that allow continuous monitoring and adjustment to ensure risk exposures remain within acceptable limits.", "Risk tolerance levels are set at one point and remain static throughout the การบริหารความเสี่ยง cycle, regardless of changes.", "Risk tolerance levels are primarily defined by external market conditions.", "Risk tolerance levels are used at the start of an การปฏิบัติงานตรวจสอบ and separate from ongoing risk assessments."]$q$::jsonb, 0, $q$Correct. Risk tolerance levels provide measurable benchmarks that facilitate continuous  monitoring and adjustments to maintain acceptable risk exposures.$q$, $q$ถูกต้อง: Risk tolerance levels provide measurable benchmarks that facilitate continuous  monitoring and adjustments to maintain acceptable risk exposures.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10255', '2026', 1, 'C.5.c', $q$How does integrating risk assessment with continuous monitoring  enhance the overall risk management process?$q$, $q$How does integrating risk assessment with continuous monitoring  enhance the overall การบริหารความเสี่ยง process?$q$, $q$["Integration ensures that risk assessment is completed once, with monitoring occurring independently of control changes.", "Integration focuses on quantitative data without considering the effectiveness of controls.", "Integration allows for ongoing evaluation of risk levels and control performance, facilitating timely adjustments to risk strategies.", "Integration replaces the need for separate risk assessment by relying entirely on continuous monitoring."]$q$::jsonb, $q$["Integration ensures that risk assessment is completed once, with monitoring occurring independently of control changes.", "Integration focuses on quantitative data without considering the effectiveness of controls.", "Integration allows for ongoing evaluation of risk levels and control performance, facilitating timely adjustments to risk strategies.", "Integration replaces the need for separate risk assessment by relying entirely on continuous monitoring."]$q$::jsonb, 2, $q$Correct. Integrating risk assessment and continuous monitoring enables timely  adjustments by providing an ongoing evaluation of risks and controls.$q$, $q$ถูกต้อง: Integrating risk assessment and continuous monitoring enables timely  adjustments by providing an ongoing evaluation of risks and controls.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10256', '2026', 1, 'C.6.b', $q$How does a risk management framework benefit an organization's  processes and functions?$q$, $q$How does a การบริหารความเสี่ยง framework benefit an organization's  processes and functions?$q$, $q$["It is used mainly to document risk events and integrate current strategic objectives into operational processes.", "It primarily serves as a method to identify risks and strategic objectives without determining risk response.", "It acts as a reactive tool that addresses issues after they occur, offering suggestions for improvement.", "It provides a systematic approach to identify, assess, and mitigate risks, aligning processes with strategic objectives and enhancing decision‑making."]$q$::jsonb, $q$["It is used mainly to document risk events and integrate current strategic objectives into operational processes.", "It primarily serves as a method to identify risks and strategic objectives without determining risk response.", "It acts as a reactive tool that addresses issues after they occur, offering suggestions for improvement.", "It provides a systematic approach to identify, assess, and mitigate risks, aligning processes with strategic objectives and enhancing decision‑making."]$q$::jsonb, 3, $q$Correct. A systematic framework enables proactive risk identification, assessment, and  mitigation, aligning processes with strategy and improving decisions.$q$, $q$ถูกต้อง: A systematic framework enables proactive risk identification, assessment, and  mitigation, aligning processes with strategy and improving decisions.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10257', '2026', 1, 'C.6.b', $q$How does the adoption of a risk management framework enhance  overall organizational effectiveness?$q$, $q$How does the adoption of a การบริหารความเสี่ยง framework enhance  overall organizational effectiveness?$q$, $q$["It focuses on financial risks, ensuring accurate and complete financial reporting.", "It provides a record of risk events that can be used for post‑incident evaluation.", "It establishes clear procedures for risk identification, assessment, and control, thereby supporting informed decision‑making and strategic alignment.", "It standardizes the risk register and ensures transparent reporting of risk events."]$q$::jsonb, $q$["It focuses on financial risks, ensuring accurate and complete financial reporting.", "It provides a record of risk events that can be used for post‑incident evaluation.", "It establishes clear procedures for risk identification, assessment, and control, thereby supporting informed decision‑making and strategic alignment.", "It standardizes the risk register and ensures transparent reporting of risk events."]$q$::jsonb, 2, $q$Correct. By establishing clear risk management procedures, the framework supports  informed decision‑making and strategic alignment, enhancing organizational  effectiveness.$q$, $q$ถูกต้อง: By establishing clear การบริหารความเสี่ยง procedures, the framework supports  informed decision‑making and strategic alignment, enhancing organizational  effectiveness.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10258', '2026', 1, 'C.6.b', $q$How does the implementation of a risk management framework  best impact the organization's ability to manage risks effectively?$q$, $q$How does the implementation of a การบริหารความเสี่ยง framework  best impact the organization's ability to manage risks effectively?$q$, $q$["It serves as a repository for categorizing relevant risks.", "It creates a structured environment for proactive risk management, leading to improved mitigation strategies and enhanced operational resilience.", "It provides a risk management template to document the risk universe.", "It includes historical risk analysis along with horizon risks."]$q$::jsonb, $q$["It serves as a repository for categorizing relevant risks.", "It creates a structured environment for proactive การบริหารความเสี่ยง, leading to improved mitigation strategies and enhanced operational resilience.", "It provides a การบริหารความเสี่ยง template to document the risk universe.", "It includes historical risk analysis along with horizon risks."]$q$::jsonb, 1, $q$Correct. A structured risk management framework supports effective risk mitigation by  fostering proactive management and enhancing organizational resilience.$q$, $q$ถูกต้อง: A structured การบริหารความเสี่ยง framework supports effective risk mitigation by  fostering proactive management and enhancing organizational resilience.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10259', '2026', 1, 'C.7.a', $q$How do internal controls support compliance with legal and  regulatory requirements?$q$, $q$How do การควบคุมภายในs support compliance with legal and  regulatory requirements?$q$, $q$["They serve as advisory guidelines that management may choose to follow without strict enforcement.", "They primarily provide a framework for documenting compliance activities.", "They establish structured procedures and protocols that help ensure adherence to laws and regulations.", "They are focused on internal process improvement and comparison to competitive benchmarking."]$q$::jsonb, $q$["They serve as advisory guidelines that management may choose to follow without strict enforcement.", "They primarily provide a framework for documenting compliance activities.", "They establish structured procedures and protocols that help ensure adherence to laws and regulations.", "They are focused on internal process improvement and comparison to competitive benchmarking."]$q$::jsonb, 2, $q$Correct. Structured internal controls are essential in ensuring that organizations follow  legal and regulatory mandates consistently.$q$, $q$ถูกต้อง: Structured การควบคุมภายในs are essential in ensuring that organizations follow  legal and regulatory mandates consistently.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10260', '2026', 1, 'C.7.a', $q$How do internal controls enhance operational efficiency within an  organization?$q$, $q$How do การควบคุมภายในs enhance operational efficiency within an  organization?$q$, $q$["They focus on setting long- term strategic goals.", "They streamline processes through defined procedures, reduce errors, and minimize waste, thereby improving overall efficiency.", "They are used mainly for monitoring compliance with external standards.", "They provide guidelines for employee behavior that indirectly impact operational speed."]$q$::jsonb, $q$["They focus on setting long- term strategic goals.", "They streamline processes through defined procedures, reduce errors, and minimize waste, thereby improving overall efficiency.", "They are used mainly for monitoring compliance with external standards.", "They provide guidelines for employee behavior that indirectly impact operational speed."]$q$::jsonb, 1, $q$Correct. Clearly defined internal controls streamline operations by reducing errors and  waste, leading to greater efficiency.$q$, $q$ถูกต้อง: Clearly defined การควบคุมภายในs streamline operations by reducing errors and  waste, leading to greater efficiency.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10261', '2026', 1, 'D.2.b', $q$When reviewing processes involving large cash transactions, how  should an internal auditor determine whether fraud risks require  special consideration?$q$, $q$When reviewing processes involving large cash transactions, how  should an ผู้ตรวจสอบภายใน determine whether fraud risks require  special consideration?$q$, $q$["By analyzing transaction volume, segregation of duties, and reconciliation procedures to assess vulnerabilities.", "By noting the frequency of transactions and relying upon internal controls.", "By focusing on management reports and analytical review procedures.", "By evaluating the qualifications of operating personnel and documented internal controls."]$q$::jsonb, $q$["By analyzing transaction volume, segregation of duties, and reconciliation procedures to assess vulnerabilities.", "By noting the frequency of transactions and relying upon การควบคุมภายในs.", "By focusing on management reports and analytical review procedures.", "By evaluating the qualifications of operating personnel and documented การควบคุมภายในs."]$q$::jsonb, 0, $q$Correct. Analyzing transaction volume, duty segregation, and reconciliation procedures  is essential to identifying vulnerabilities in high-risk cash processes.$q$, $q$ถูกต้อง: Analyzing transaction volume, duty segregation, and reconciliation procedures  is essential to identifying vulnerabilities in high-risk cash processes.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10262', '2026', 1, 'D.2.b', $q$In an audit engagement focusing on payroll processes, which  factors should lead an internal auditor to assess fraud risks in  detail?$q$, $q$In an การปฏิบัติงานตรวจสอบ focusing on payroll processes, which  factors should lead an ผู้ตรวจสอบภายใน to assess fraud risks in  detail?$q$, $q$["When the payroll system is completely integrated with human resources, relying primarily on automated controls.", "When payroll is processed offsite and human resources has high turnover.", "When anomalies such as ghost employees, irregular payroll adjustments, and weak approval processes signal potential fraud.", "When regular independent reviews indicate that journal entries are made relating to vacation time and employee departures."]$q$::jsonb, $q$["When the payroll system is completely integrated with human resources, relying primarily on automated controls.", "When payroll is processed offsite and human resources has high turnover.", "When anomalies such as ghost employees, irregular payroll adjustments, and weak approval processes signal potential fraud.", "When regular independent reviews indicate that journal entries are made relating to vacation time and employee departures."]$q$::jsonb, 2, $q$Correct. Anomalies like ghost employees and irregular adjustments in payroll indicate a  higher potential for fraud, warranting special consideration.$q$, $q$ถูกต้อง: Anomalies like ghost employees and irregular adjustments in payroll indicate a  higher potential for fraud, warranting special consideration.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10263', '2026', 1, 'D.2.b', $q$When evaluating inventory management processes, how should  an internal auditor determine whether fraud risks warrant special  consideration?$q$, $q$When evaluating inventory management processes, how should  an ผู้ตรวจสอบภายใน determine whether fraud risks warrant special  consideration?$q$, $q$["By focusing on cost control measures and inventory trend analysis.", "By relying on periodic inventory reports and analytical review procedures.", "By assessing inventory based on historical data and established controls.", "By reviewing inventory recording methods, performing physical counts, and identifying discrepancies that could indicate manipulation."]$q$::jsonb, $q$["By focusing on cost control measures and inventory trend analysis.", "By relying on periodic inventory reports and analytical review procedures.", "By assessing inventory based on historical data and established controls.", "By reviewing inventory recording methods, performing physical counts, and identifying discrepancies that could indicate manipulation."]$q$::jsonb, 3, $q$Correct. Reviewing recording methods, conducting physical counts, and identifying  discrepancies are essential steps to uncovering potential fraud in inventory management.$q$, $q$ถูกต้อง: Reviewing recording methods, conducting physical counts, and identifying  discrepancies are essential steps to uncovering potential fraud in inventory management.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10264', '2026', 1, 'D.3.a', $q$How can an organization’s integration of risk assessments and  monitoring best be used to determine the effectiveness of its fraud  risk management process?$q$, $q$How can an organization’s integration of risk assessments and  monitoring best be used to determine the effectiveness of its fraud  การบริหารความเสี่ยง process?$q$, $q$["By using independent audit engagements to review risk assessments and perform analytical review procedures.", "By relying on historical risk assessments without incorporating data from routine monitoring for current exposures.", "By comparing risk assessments with ongoing monitoring results to measure how well controls reduce potential fraud exposure.", "By focusing on external benchmarks for risk identification and relying on the external auditors to evaluate financial controls."]$q$::jsonb, $q$["By using independent การปฏิบัติงานตรวจสอบs to review risk assessments and perform analytical review procedures.", "By relying on historical risk assessments without incorporating data from routine monitoring for current exposures.", "By comparing risk assessments with ongoing monitoring results to measure how well controls reduce potential fraud exposure.", "By focusing on external benchmarks for risk identification and relying on the external auditors to evaluate financial controls."]$q$::jsonb, 2, $q$Correct. Comparing risk assessments with ongoing monitoring results helps measure the  effectiveness of controls in reducing fraud exposure.$q$, $q$ถูกต้อง: Comparing risk assessments with ongoing monitoring results helps measure the  effectiveness of controls in reducing fraud exposure.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10265', '2026', 1, 'D.4.a', $q$When reviewing an organization’s fraud risk management  framework, how does the tone at the top contribute to the overall  control environment?$q$, $q$When reviewing an organization’s fraud การบริหารความเสี่ยง  framework, how does the tone at the top contribute to the overall  control environment?$q$, $q$["It establishes clear ethical standards and accountability measures that help maintain robust controls and reduce fraud risk.", "It shifts the focus to compliance with regulatory requirements and the organization’s strategic plans.", "It primarily drives financial performance targets and budget monitoring.", "It emphasizes reliance on external audit results to detect the financial fraud."]$q$::jsonb, $q$["It establishes clear ethical standards and accountability measures that help maintain robust controls and reduce fraud risk.", "It shifts the focus to compliance with regulatory requirements and the organization’s strategic plans.", "It primarily drives financial performance targets and budget monitoring.", "It emphasizes reliance on external audit results to detect the financial fraud."]$q$::jsonb, 0, $q$Correct. The tone at the top, by setting ethical standards and accountability, plays a  critical role in maintaining an effective control environment to deter fraud.$q$, $q$ถูกต้อง: The tone at the top, by setting ethical standards and accountability, plays a  critical role in maintaining an effective control environment to deter fraud.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10266', '2026', 1, 'D.4.b', $q$How does segregation of duties best contribute to fraud detection  in financial processes?$q$, $q$How does segregation of duties best contribute to fraud detection  in financial processes?$q$, $q$["Centralizing similar transaction processing within one department to provide efficiency, and conducting routine external audit engagements.", "Assigning distinct responsibilities for processing, approving, and reconciling transactions to provide multiple layers of review.", "Relying on automated systems and using the accounting department to conduct periodic monitoring.", "Centralizing similar transaction processing within one department to provide efficiency, and conducting routine internal audit engagements."]$q$::jsonb, $q$["Centralizing similar transaction processing within one department to provide efficiency, and conducting routine external การปฏิบัติงานตรวจสอบs.", "Assigning distinct responsibilities for processing, approving, and reconciling transactions to provide multiple layers of review.", "Relying on automated systems and using the accounting department to conduct periodic monitoring.", "Centralizing similar transaction processing within one department to provide efficiency, and conducting routine internal การปฏิบัติงานตรวจสอบs."]$q$::jsonb, 1, $q$Correct. Separating roles ensures independent verification at each step, which enhances  fraud detection.$q$, $q$ถูกต้อง: Separating roles ensures independent verification at each step, which enhances  fraud detection.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10267', '2026', 1, 'D.4.b', $q$In financial reporting, which control best utilizes segregation of  duties to enhance information reliability?$q$, $q$In financial reporting, which control best utilizes segregation of  duties to enhance information reliability?$q$, $q$["Separating transaction authorization, recording, and reconciliation processes to provide independent checks at every stage.", "Combining authorization and recording functions and utilizing periodic supervisory reviews for validation.", "Relying on an automated system to perform all transaction functions combined with reconciliation by the accounting department.", "Implementing routine internal audit engagements of transactions while maintaining a centralized processing function."]$q$::jsonb, $q$["Separating transaction authorization, recording, and reconciliation processes to provide independent checks at every stage.", "Combining authorization and recording functions and utilizing periodic supervisory reviews for validation.", "Relying on an automated system to perform all transaction functions combined with reconciliation by the accounting department.", "Implementing routine internal การปฏิบัติงานตรวจสอบs of transactions while maintaining a centralized processing function."]$q$::jsonb, 0, $q$Correct. Separating key functions in financial reporting creates a robust system of checks  that enhances the reliability of reported data.$q$, $q$ถูกต้อง: Separating key functions in financial reporting creates a robust system of checks  that enhances the reliability of reported data.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10268', '2026', 1, 'D.4.c', $q$When reviewing an organization’s control structure, which aspect  of authority levels most effectively helps prevent fraud?$q$, $q$When reviewing an organization’s control structure, which aspect  of authority levels most effectively helps prevent fraud?$q$, $q$["A hierarchical structure where authority is delegated to unrelated departments.", "Centralized authority concentrated in one individual, ensuring efficient oversight.", "Authority shared among several departments with ongoing control monitoring.", "Clear segregation of authority that distributes decision-making power across multiple roles to create effective checks and balances."]$q$::jsonb, $q$["A hierarchical structure where authority is delegated to unrelated departments.", "Centralized authority concentrated in one individual, ensuring efficient oversight.", "Authority shared among several departments with ongoing control monitoring.", "Clear segregation of authority that distributes decision-making power across multiple roles to create effective checks and balances."]$q$::jsonb, 3, $q$Correct. Clear segregation of authority creates effective checks and balances that  minimize opportunities for fraud.$q$, $q$ถูกต้อง: Clear segregation of authority creates effective checks and balances that  minimize opportunities for fraud.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10269', '2026', 1, 'D.4.c', $q$In evaluating risk controls, how can the implementation of defined  authority levels reduce the likelihood of fraud?$q$, $q$In evaluating risk controls, how can the implementation of defined  authority levels reduce the likelihood of fraud?$q$, $q$["By centralizing decision- making authority with top management to maintain consistency and reduce administrative overhead.", "By establishing distinct roles with clear limits on decision- making power, thereby ensuring that each critical function is independently verified.", "By allowing flexible role assignments that adapt quickly to changing business needs with ongoing transaction monitoring.", "By providing full authority to appropriate operating management along with routine internal auditing."]$q$::jsonb, $q$["By centralizing decision- making authority with top management to maintain consistency and reduce administrative overhead.", "By establishing distinct roles with clear limits on decision- making power, thereby ensuring that each critical function is independently verified.", "By allowing flexible role assignments that adapt quickly to changing business needs with ongoing transaction monitoring.", "By providing full authority to appropriate operating management along with routine การตรวจสอบภายใน."]$q$::jsonb, 1, $q$Correct. Defined authority levels create clear, independent verification at each critical  stage, significantly reducing fraud risk.$q$, $q$ถูกต้อง: Defined authority levels create clear, independent verification at each critical  stage, significantly reducing fraud risk.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10270', '2026', 1, 'D.5.a', $q$How does the internal audit function ensure the integrity of fraud  investigations?$q$, $q$How does the หน่วยงานตรวจสอบภายใน ensure the integrity of fraud  investigations?$q$, $q$["By performing thorough, unbiased reviews of fraud claims and validating evidence before reporting findings to the appropriate oversight bodies.", "By accepting initial fraud reports and relying on management’s review of the incident.", "By conducting reviews that focus primarily on compliance and interviewing staff suspected of fraud.", "By outsourcing the evidence validation process entirely to third-party specialists, eliminating the need for oversight."]$q$::jsonb, $q$["By performing thorough, unbiased reviews of fraud claims and validating evidence before reporting findings to the appropriate oversight bodies.", "By accepting initial fraud reports and relying on management’s review of the incident.", "By conducting reviews that focus primarily on compliance and interviewing staff suspected of fraud.", "By outsourcing the evidence validation process entirely to third-party specialists, eliminating the need for oversight."]$q$::jsonb, 0, $q$Correct. A thorough, independent review of fraud claims and evidence validation is  essential to maintaining the integrity of investigations.$q$, $q$ถูกต้อง: A thorough, independent review of fraud claims and evidence validation is  essential to maintaining the integrity of investigations.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10271', '2026', 1, 'D.5.b', $q$During a fraud investigation, which interviewing technique best  encourages witnesses to provide detailed, candid responses?$q$, $q$During a fraud investigation, which interviewing technique best  encourages witnesses to provide detailed, candid responses?$q$, $q$["Asking open‑ended questions that invite narrative responses and elaboration.", "Asking yes‑or‑no questions to get the perpetrator to admit wrongdoing.", "Using leading questions that suggest a desired response to guide the interviewee.", "By following an organized script of standard questions that often prove effective."]$q$::jsonb, $q$["Asking open‑ended questions that invite narrative responses and elaboration.", "Asking yes‑or‑no questions to get the perpetrator to admit wrongdoing.", "Using leading questions that suggest a desired response to guide the interviewee.", "By following an organized script of standard questions that often prove effective."]$q$::jsonb, 0, $q$Correct. Open‑ended questions foster detailed, candid responses by allowing  interviewees to share their perspectives in their own words.$q$, $q$ถูกต้อง: Open‑ended questions foster detailed, candid responses by allowing  interviewees to share their perspectives in their own words.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10272', '2026', 1, 'D.5.b', $q$In a fraud investigation, how should an internal auditor prepare in  order to ensure effective interviewing?$q$, $q$In a fraud investigation, how should an ผู้ตรวจสอบภายใน prepare in  order to ensure effective interviewing?$q$, $q$["By using standard interview forms that are distributed to all interviewees to ensure consistency.", "By focusing on past incidents and preparing a fixed set of questions utilized in prior investigations.", "By having an informal, ad hoc conversation during the interview to relax the offender.", "By reviewing background information on the case, planning open‑ended questions, and preparing to document responses meticulously."]$q$::jsonb, $q$["By using standard interview forms that are distributed to all interviewees to ensure consistency.", "By focusing on past incidents and preparing a fixed set of questions utilized in prior investigations.", "By having an informal, ad hoc conversation during the interview to relax the offender.", "By reviewing background information on the case, planning open‑ended questions, and preparing to document responses meticulously."]$q$::jsonb, 3, $q$Correct. Proper preparation, including background research and planning open ‑ended  questions, is essential for conducting effective and unbiased fraud investigation  interviews.$q$, $q$ถูกต้อง: Proper preparation, including background research and planning open ‑ended  questions, is essential for conducting effective and unbiased fraud investigation  interviews.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10273', '2026', 1, 'D.5.e', $q$Which scenario best illustrates an opportunity for internal auditors  to coordinate with fraud investigators?$q$, $q$Which scenario best illustrates an opportunity for ผู้ตรวจสอบภายในs  to coordinate with fraud investigators?$q$, $q$["Relying on historical fraud data and existing internal controls and deferring to the external auditors.", "Conducting risk assessments independently without integrating findings from fraud investigations or whistleblower reports to corroborate the results.", "Jointly reviewing risk assessments, prior investigations, and whistleblower complaints to identify emerging fraud patterns.", "Delegating fraud-related reviews to the external auditors."]$q$::jsonb, $q$["Relying on historical fraud data and existing การควบคุมภายในs and deferring to the external auditors.", "Conducting risk assessments independently without integrating findings from fraud investigations or whistleblower reports to corroborate the results.", "Jointly reviewing risk assessments, prior investigations, and whistleblower complaints to identify emerging fraud patterns.", "Delegating fraud-related reviews to the external auditors."]$q$::jsonb, 2, $q$Correct. Coordinating reviews enhances fraud detection by integrating diverse sources  of information.$q$, $q$ถูกต้อง: Coordinating reviews enhances fraud detection by integrating diverse sources  of information.$q$);
INSERT INTO questions (qid, version, part, topic, question_en, question_th, options_en, options_th, answer_index, explanation_en, explanation_th) VALUES ('AI10274', '2026', 1, 'D.5.e', $q$How does integrating fraud investigation findings into risk  assessments best enhance fraud risk management?$q$, $q$How does integrating fraud investigation findings into risk  assessments best enhance fraud การบริหารความเสี่ยง?$q$, $q$["By systematically comparing current risk assessments with findings from fraud investigations to update controls and mitigation strategies.", "By maintaining separate review processes for risk assessments and fraud investigations.", "By relying on internal financial data and prior audit results to complete risk assessments.", "By conducting risk assessments on an annual basis and including input from management."]$q$::jsonb, $q$["By systematically comparing current risk assessments with findings from fraud investigations to update controls and mitigation strategies.", "By maintaining separate review processes for risk assessments and fraud investigations.", "By relying on internal financial data and prior audit results to complete risk assessments.", "By conducting risk assessments on an annual basis and including input from management."]$q$::jsonb, 0, $q$Correct. Integration of investigation findings improves risk management by ensuring that  control measures are updated and effective.$q$, $q$ถูกต้อง: Integration of investigation findings improves การบริหารความเสี่ยง by ensuring that  control measures are updated and effective.$q$);

